/* DAWAH X — ahmad, অধ্যায় 97 · খণ্ড 97 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][97]=[[19201,19201,"","আমি কিভাবে ঘটেছে সে সম্পর্কে কথা বলতে চাই সে বলল আমি তাকে দেখতে চাই আর সে আমাকে বলে সে ভাল হবে. আমরা তার কানের মত পড়াচ্ছি. এমনকি বিয়েও না।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏حُمَيْدِ بْنِ هِلَالٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏مَنْ سَمِعَ ‏ ‏الْأَعْرَابِيَّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي قَالَ ‏ ‏فَرَفَعَ رَأْسَهُ مِنْ الرُّكُوعِ فَرَفَعَ كَفَّيْهِ حَتَّى ‏ ‏حَاذَتَا ‏ ‏أَوْ بَلَغَتَا فُرُوعَ أُذُنَيْهِ كَأَنَّهُمَا مِرْوَحَتَانِ ‏","","",""],[19202,19202,"","আমি দেখেছি যে, ঈশ্বর তাঁর পতাকা তুলে রেখেছেন এবং তিনি তা উদ্ধার করবেন এবং তিনি প্রার্থনা করবেন যে তিনি কামা থেকে তা করেছেন। এটা কর।","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏مَنْ سَمِعَ ‏ ‏الْأَعْرَابِيَّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يُصَلِّي وَعَلَيْهِ نَعْلَانِ مِنْ بَقَرٍ قَالَ فَتَفَلَ عَنْ يَسَارِهِ ثُمَّ حَكَّ حَيْثُ ‏ ‏تَفَلَ ‏ ‏بِنَعْلِهِ ‏","","",""],[19203,19203,"","আমরা বাবা-মা'র সাথে কথা বলেছি, না আমরা মদ খেয়ে মাতাল হয়ে গেছি, আমি বলছি আমি লড়াই করছি, আমরা তোমার ঈশ্বর সম্পর্কে জেনেছি এবং একটা শর্ট-কাট চাই। আমি বলছি, আমি বলছি, আমি যুদ্ধ করছি।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو أَحْمَدَ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏يَزِيدَ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏مُطَرِّفِ بْنِ الشِّخِّيرِ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَعْرَابِيٌّ ‏ ‏لَنَا ‏ ‏قَالَ ‏ ‏رَأَيْتُ نَعْلَ نَبِيِّكُمْ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَخْصُوفَةً ‏","","",""],[19204,19204,"","আমরা কথা বলেছি সবচেয়ে সুন্দর মানুষের তৃতীয় প্রজন্মের পর্দার পর্দার পর্দার কথা। তার বাবা অথবা চাচার কাছে আছে। হয়তো সে বলবে, ঈশ্বর তিন সেকেন্ডের মধ্যে রক্ষা পেয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عَبْدِ الرَّحْمَنِ الطُّفَاوِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ الْجُرَيْرِيُّ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏بَنِي تَمِيمٍ ‏ ‏وَأَحْسَنَ الثَّنَاءَ عَلَيْهِ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏أَوْ ‏ ‏عَمِّهِ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَسَأَلْنَاهُ عَنْ قَدْرِ رُكُوعِهِ وَسُجُودِهِ فَقَالَ قَدْرُ مَا يَقُولُ الرَّجُلُ سُبْحَانَ اللَّهِ وَبِحَمْدِهِ ثَلَاثًا ‏","","",""],[19205,19205,"","আমরা আকাশ নিয়ে যে শপথ শুনেছি, সে সময় আমরা পাথর মারার কথা বলেছিলাম। আমি এমন একজন যে তার প্রতিবেশীর জন্য স্বাক্ষর করেছিল। তার মত এটা কর এবং সে হতে পারত। চিন্তা করো এটা তাকে মুক্ত করে তার মতো করে কাজ করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ دِينَارٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبِّقِ ‏ ‏أَنَّ رَجُلًا ‏ ‏وَقَعَ ‏ ‏عَلَى ‏ ‏جَارِيَةِ ‏ ‏امْرَأَتِهِ فَرُفِعَ ذَاكَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنْ كَانَتْ طَاوَعَتْهُ فَهِيَ لَهُ وَعَلَيْهِ مِثْلُهَا لَهَا وَإِنْ كَانَ اسْتَكْرَهَهَا فَهِيَ حُرَّةٌ وَعَلَيْهِ مِثْلُهَا لَهَا ‏","","",""],[19206,19206,"","আমরা পিছনে ফিরে যাওয়ার চেষ্টা করার চেয়ে বরং একটা ক্যারিয়ারের কথোপকথনের বিষয়ে কথা বলেছিলাম । ভগবানকে ঈশ্বরের কাছে প্রার্থনা করতে বলবে, তার মগজের গুলি করেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَوْنِ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى بَيْتٍ قُدَّامُهُ قِرْبَةٌ مُعَلَّقَةٌ ‏ ‏فَسَأَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الشَّرَابَ فَقَالُوا إِنَّهَا مَيْتَةٌ فَقَالَ ‏ ‏دِبَاغُهَا ‏ ‏ذَكَاتُهَا ‏","","",""],[19207,19207,"","আমরা একটি সালাদ বলা জীবনের সব থেকে ভাল অভ্যাসের কথা বলেছি, আমি প্রার্থনা করছি ঈশ্বর এটা একটি হলালঝা, তিনি বললেন পর্দাটা ছিল তার শিং।","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏قَدْ سَمَّاهُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبَّقِ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى أَهْلِ بَيْتٍ ‏ ‏فَاسْتَسْقَى فَإِذَا قِرْبَةٌ فِيهَا مَاءٌ فَقَالُوا إِنَّهَا مَيْتَةٌ يَا رَسُولَ اللَّهِ قَالَ ‏ ‏الْأَدِيمُ ‏ ‏طُهُورُهُ ‏ ‏دِبَاغُهُ ‏","","",""],[19208,19208,"","আমরা ঈশ্বরের আশীর্বাদ নিয়ে কথা বলেছি, আমরা খুশি হয়েছি মানে আমার বাবার ছেলেকে সৎতার সাজা দেয়া হয়েছে। রাজার ক্ষমতা নিয়ে প্রার্থনা করে সে তার টাকা ছেড়ে দিয়েছে আর তাকে খুঁজে বের করার জন্য তাকে সবচেয়ে ভাল চেষ্টা করতে বলেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بَكْرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ يَعْنِي ابْنَ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبِّقِ ‏ ‏أَنَّ رَجُلًا ‏ ‏غَشِيَ ‏ ‏جَارِيَةَ ‏ ‏امْرَأَتِهِ وَهُوَ فِي غَزْوٍ فَرُفِعَ ذَلِكَ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنْ كَانَ اسْتَكْرَهَهَا فَهِيَ حُرَّةٌ مِنْ مَالِهِ وَعَلَيْهِ شِرَاؤُهَا لِسَيِّدَتِهَا وَإِنْ كَانَتْ طَاوَعَتْهُ فَمِثْلُهَا مِنْ مَالِهِ لِسَيِّدَتِهَا ‏","","",""],[19209,19209,"","তার স্ত্রী আমার প্রভুর কাছে স্বাক্ষর করেছিলেন, তাকে বলতে বলেছিলেন যে, সে তার প্রেমে পড়েছে । তার কথা শুনে মনে হচ্ছে, সে ঈশ্বর সম্পর্কে ভালো কথা বলার চেয়ে ভাল আর তার হাতে আছে। ঈশ্বরের প্রতি প্রেম","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبِّقِ ‏ ‏أَنَّ رَجُلًا خَرَجَ فِي غَزَاةٍ وَمَعَهُ ‏ ‏جَارِيَةٌ ‏ ‏لِامْرَأَتِهِ ‏ ‏فَوَقَعَ ‏ ‏بِهَا فَذُكِرَ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ إِنْ كَانَ اسْتَكْرَهَهَا فَهِيَ ‏ ‏عَتِيقَةٌ ‏ ‏وَلَهَا عَلَيْهِ مِثْلُهَا وَإِنْ كَانَتْ طَاوَعَتْهُ فَهِيَ أَمَتُهُ وَلَهَا عَلَيْهِ مِثْلُهَا ‏ ‏وَقَالَ ‏ ‏إِسْمَاعِيلُ ‏ ‏مَرَّةً إِنَّ رَجُلًا كَانَ فِي غَزْوَةٍ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبِّقِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبِّقِ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[19210,19210,"","আমরা আমাদের আবেগ দিয়ে বাপ্তাইজিত হয়েছি... ...আমরা ভালো জায়গা খোঁজার চেয়ে ভাল জায়গা খোঁজার জন্য... এবং আমি এটা রাজতন্ত্রের মৃত্যুর উপর একটি শট দেব।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَوْنِ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبِّقِ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى ‏ ‏قِرْبَةٍ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فَدَعَا مِنْهَا بِمَاءٍ وَعِنْدَهَا امْرَأَةٌ فَقَالَتْ إِنَّهَا مَيْتَةٌ فَقَالَ سَلُوهَا أَلَيْسَ قَدْ ‏ ‏دُبِغَتْ ‏ ‏فَقَالَتْ بَلَى فَأَتَى مِنْهَا لِحَاجَتِهِ فَقَالَ ذَكَاةُ ‏ ‏الْأَدِيمِ ‏ ‏دِبَاغُهُ ‏","","",""],[19211,19211,"","আমরা পরবর্তী কয়েকদিন কথা বলেছি আমরা শাসন শাসনের শাসন করার চেষ্টা করেছি. তিনি ঈশ্বরের অনুগ্রহের সাথে ছিলেন, প্রার্থনা এবং আকুতিতে আত্মসমর্পণ আপনার নিজের কথা, সে তার স্বৈরতন্ত্রকে হত্যা করেছে।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَوْنِ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبِّقِ ‏ ‏أَنَّهُ ‏ ‏كَانَ مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي غَزْوَةِ ‏ ‏تَبُوكَ ‏ ‏فَأَتَى عَلَى بَيْتٍ قُدَّامُهُ قِرْبَةٌ مُعَلَّقَةٌ ‏ ‏فَسَأَلَ الشَّرَابَ فَقِيلَ إِنَّهَا ‏ ‏مَيْتَةٌ ‏ ‏فَقَالَ ‏ ‏ذَكَاتُهَا ‏ ‏دِبَاغُهَا ‏","","",""],[19212,19212,"","আমরা সবচেয়ে ভালো কিছুর কথা বলেছি, ঈশ্বর শুধু জিজ্ঞাসা করলেন তিনি নিজের নিজের নিজের ক্ষমতা নিয়ে আছেন আর তাকে তার প্রতিবেশী হিসেবেই দিয়েছেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏قَبِيصَةَ بْنِ حُرَيْثٍ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبِّقِ ‏ ‏قَالَ ‏ ‏قَضَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي رَجُلٍ ‏ ‏وَطِئَ ‏ ‏جَارِيَةَ ‏ ‏امْرَأَتِهِ إِنْ كَانَ اسْتَكْرَهَهَا فَهِيَ حُرَّةٌ وَعَلَيْهِ لِسَيِّدَتِهَا مِثْلُهَا ‏","","",""],[19213,19213,"","আমি আমার ভাইকে বলেছিলাম যে কিভাবে ঈশ্বরের মাথা দিয়ে যেতে হয়. বছরের পর বছর আমার ছেলের শান্তির স্বপ্নের জন্য এবং তিনি হয়তো ঈশ্বর এই সিদ্ধান্ত নিয়েছেন. আর সে তার জীবনের শান্তি পাবে, ঈশ্বর এটা দিতে পারবেন যে একজন মানুষ তাকে দুই বছর আগে তার কাছে প্রকাশ করা হয়েছে যখন সে মুক্ত এবং অন্ধ হয়ে আছে. তারা সবসময় বলে, আপনার মহিমা আপনার সম্মান।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏ابْنُ جُرَيْجٍ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْكَرِيمِ بْنُ أَبِي الْمُخَارِقِ ‏ ‏عَنْ ‏ ‏مُعَاذِ بْنِ سَعْوَةَ الرَّاسِبِيِّ ‏ ‏عَنْ ‏ ‏سِنَانِ بْنِ سَلَمَةَ الْهُذَلِيِّ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏سَلَمَةَ ‏ ‏وَكَانَ قَدْ صَحِبَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ بَعَثَ ‏ ‏بَدَنَتَيْنِ ‏ ‏مَعَ رَجُلٍ وَقَالَ ‏ ‏إِنْ عَرَضَ ‏ ‏لَهُمَا ‏ ‏فَانْحَرْهُمَا ‏ ‏وَاغْمِسْ النَّعْلَ فِي دِمَائِهِمَا ثُمَّ اضْرِبْ بِهِ ‏ ‏صَفْحَتَيْهِمَا ‏ ‏حَتَّى يُعْلَمَ أَنَّهُمَا ‏ ‏بَدَنَتَانِ ‏ ‏قَالَ ‏ ‏صَفْحَتَيْ ‏ ‏كُلِّ وَاحِدَةٍ قَالَ وَلَا تَأْكُلْ مِنْهَا أَنْتَ وَلَا أَحَدٌ مِنْ رُفْقَتِكَ وَدَعْهَا لِمَنْ بَعْدَكُمْ ‏","","",""],[19214,19214,"","কিন্তু আমি যে শান্তি ভালবাসি তা হলো যে আমি যেন খুব কঠোর ভাবে সেবা করি। তিনি বলেন, তার বইগুলো তার ভাষায় নয়।","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏الْمَعْنَى ‏ ‏قَالُوا أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏جَوْنِ بْنِ قَتَادَةَ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ الْمُحَبِّقِ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا بِمَاءٍ مِنْ قِرْبَةٍ عِنْدَ امْرَأَةٍ فَقَالَتْ إِنَّهَا مَيْتَةٌ فَقَالَ أَلَيْسَ قَدْ ‏ ‏دَبَغْتِهَا ‏ ‏قَالَتْ بَلَى قَالَ ‏ ‏دِبَاغُهَا ‏ ‏ذَكَاتُهَا ‏","","",""],[19215,19215,"","আমি আমার বাবার হৃদয়ের কথা বলেছি। আমার বাবার হৃদয়ের কথা বলেছিলাম। আমার বাবা আমাকে বলেছিলেন যে, তারা তোমার কাছে একটা পেন্সিল নিয়ে এসেছিল, যে আমাকে ঈশ্বরের কাছে পাঠাতে আমাকে অনুপ্রাণিত করেছিল ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ بْنُ حَبِيبٍ الْعَوْذِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏قَالَ ‏ ‏غَزَوْنَا مَعَ ‏ ‏سِنَانِ بْنِ سَلَمَةَ ‏ ‏مُكْرَانَ ‏ ‏فَقَالَ ‏ ‏سِنَانُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏سَلَمَةُ بْنُ الْمُحَبِّقِ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ أَدْرَكَهُ رَمَضَانُ لَهُ ‏ ‏حُمُولَةٌ ‏ ‏يَأْوِي إِلَى شِبَعٍ فَلْيَصُمْ رَمَضَانَ حَيْثُ أَدْرَكَهُ ‏ ‏و قَالَ ‏ ‏سِنَانٌ ‏ ‏وُلِدْتُ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فَبُشِّرَ بِي ‏ ‏أَبِي ‏ ‏فَقَالُوا لَهُ وُلِدَ لَكَ غُلَامٌ فَقَالَ ‏ ‏سَهْمٌ أَرْمِي بِهِ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَبُّ إِلَيَّ مِمَّا بَشَّرْتُمُونِي بِهِ وَسَمَّانِي ‏ ‏سِنَانًا ‏","","",""],[19216,19216,"","আমরা ওকে তার দাদার সাথে কথা বলেছি... ...তিনি ঈশ্বরের শান্তি ও শান্তি শুনেছেন, আর তার ব্যাপারে কি ঘটবে তা নিয়ে কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏بَهْزٌ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏وَيْلٌ لِلَّذِي يُحَدِّثُ فَيَكْذِبُ لِيُضْحِكَ بِهِ الْقَوْمَ وَيْلٌ لَهُ وَيْلٌ لَهُ ‏","","",""],[19217,19217,"","আমরা এক জীবন নিয়ে কথা বলেছি... ...যে জীবনের জন্য এসেছে লর্ডের ঘোড়া বহন করতে। তার সাথে কথা বলার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏الْهِرْمَاسُ بْنُ زِيَادٍ الْبَاهِلِيُّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبِي ‏ ‏مُرْدِفِي ‏ ‏خَلْفَهُ عَلَى حِمَارٍ وَأَنَا صَغِيرٌ فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ ‏ ‏بِمِنًى ‏ ‏عَلَى نَاقَتِهِ ‏ ‏الْعَضْبَاءِ ‏","","",""],[19218,19218,"","আমরা কিভাবে নদীকে আমার নিজের ঘোড়ার মাঝে দিয়ে শুরু করলাম, আমি আল্লাহ্‌কে বলছি, তিনি তার জন্য প্রার্থনা করেছেন এবং মানুষকে মাংসের সেলাই দিতে পারতেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عِكْرِمَةُ بْنُ عَمَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏الْهِرْمَاسُ بْنُ زِيَادٍ الْبَاهِلِيُّ ‏ ‏قَالَ ‏ ‏كَانَ أَبِي ‏ ‏مُرْدِفِي ‏ ‏فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَخْطُبُ النَّاسَ ‏ ‏يَوْمَ النَّحْرِ ‏ ‏بِمِنًى ‏ ‏عَلَى نَاقَتِهِ ‏ ‏الْعَضْبَاءِ ‏","","",""],[19219,19219,"","আমি আমার বাবার কাছ থেকে একটা বাপ্তিস্ম নিয়ে কথা বলেছিলাম, আমি তাকে ৩শ বছর স্কুলে যেতে দেব আর তাকে ছেড়ে দেবো, তোমার ভাই তার সাথে তার নিজের হাত, হয়তো সে দাবি করেছে যে সে তার সাথে কিছু করেছে, আমি তাকে একটা সঠিক অধিকার দিচ্ছি, আমরা তার স্বপ্নকে রক্ষা করার চেষ্টা করছি, আমি চেষ্টা করছি নবী ঈশ্বরের কাছে প্রার্থনা করেছে। তার আদর্শ দিয়ে কাজ করেছি.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏عَبْدُ الْمَلِكِ أَبُو جَعْفَرٍ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏سَعْدِ بْنِ الْأَطْوَلِ ‏ ‏أَنَّ أَخَاهُ مَاتَ وَتَرْكَ ثَلَاثَ مِائَةِ دِرْهَمٍ وَتَرَكَ عِيَالًا فَأَرَدْتُ أَنْ أُنْفِقَهَا عَلَى عِيَالِهِ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ أَخَاكَ مَحْبُوسٌ بِدَيْنِهِ فَاقْضِ عَنْهُ فَقَالَ يَا رَسُولَ اللَّهِ فَقَدْ أَدَّيْتُ عَنْهُ إِلَّا دِينَارَيْنِ ادَّعَتْهُمَا امْرَأَةٌ وَلَيْسَ لَهَا بَيِّنَةٌ قَالَ فَأَعْطِهَا فَإِنَّهَا مُحِقَّةٌ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنِ ‏ ‏الْجُرَيْرِيِّ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏رَجُلٍ ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِمِثْلِهِ ‏","","",""],[19220,19220,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের এক বছরের জন্য দৃষ্টি দিয়েছে। একটা ভাল্লুক তার কাছে প্রার্থনা করেছে। আর সে তোমার শপথের ব্যাপারে কিছু বলে নি। আমি দুঃখিত।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏رَبِيعِ بْنِ عَمِيلَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُسَمِّ غُلَامَكَ أَفْلَحَ وَلَا نَجِيحًا وَلَا يَسَارًا وَلَا رَبَاحًا فَإِنَّكَ إِذَا قُلْتَ أَثَمَّ هُوَ أَوْ أَثَمَّ فُلَانٌ قَالُوا لَا ‏","","",""],[19221,19221,"","আমরা একটি খারাপ এলাকা থেকে ভয়ঙ্কর শক্তি পেতে চেষ্টা করেছি, যেখানে আমরা খারাপ এলাকা থেকে একটি ভয়ঙ্কর অবস্থা পেতে চেষ্টা করেছি. এটা আপনাকে এই সাদা জায়গার জন্য আহ্বান করতে প্রলুব্ধ করে, যাতে আঘাত না হয় বা আঘাত না দেয় ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏شَيْخٍ ‏ ‏مِنْ ‏ ‏بَنِيٍ قُشَيْرٍ ‏ ‏قَالَ ‏ ‏رَوْحٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَوَادَةَ الْقُشَيْرِيَّ ‏ ‏وَكَانَ إِمَامَهُمْ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَمُرَةَ بْنَ جُنْدُبٍ ‏ ‏يَخْطُبُ ‏ ‏يَقُولُ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَغُرَّنَّكُمْ نِدَاءُ ‏ ‏بِلَالٍ ‏ ‏وَهَذَا الْبَيَاضُ حَتَّى يَنْفَجِرَ الْفَجْرُ ‏ ‏أَوْ يَطْلُعَ الْفَجْرُ ‏","","",""],[19222,19222,"","আমরা আবেগ নিয়ে কথা বলেছি যা আমাদের বলা হয়েছে... ...তাকে একটা গাল খুঁজতে আর তার গাল খুজে বের করতে। কিন্তু ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি ভালোর জন্য বিখ্যাত। ঈশ্বর, আপনি উঠেন আর আপনি ই যাচ্ছেন। প্রতারণা।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَعْبَدَ بْنَ خَالِدٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏زَيْدِ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي الْعِيدَيْنِ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَهَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ‏","","",""],[19223,19223,"","আমরা আবেগ নিয়ে কথা বলেছি... ...যে আমরা কিনা কাপুরুষের মত ভালোর শাসন নিয়ে খুশি হয়েছি, ঈশ্বর আদেশ দিয়েছেন আর তার স্বপ্নকে আত্মসমর্পণ করতে হবে সে তোমার বাবার ছেলে হিসেবে নিজেকে বড় মনে করতো যে আমার বাবার নামকে দমাতে বলবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنِ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏كَانَتْ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَكْتَتَانِ فِي صَلَاتِهِ ‏ ‏وَقَالَ ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏أَنَا مَا أَحْفَظُهُمَا عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَكَتَبُوا فِي ذَلِكَ إِلَى ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏يَسْأَلُونَهُ عَنْهُ فَكَتَبَ ‏ ‏أُبَيٌّ ‏ ‏أَنَّ ‏ ‏سَمُرَةَ ‏ ‏قَدْ حَفِظَ ‏","","",""],[19224,19224,"","আমরা একটা আবেগ দ্বারা বাপ্তাইজিত হয়েছি, যা আমাদের জন্য ভালো মানুষ হবার জন্য খুশি হয়েছে। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি বলবেন যে, এই থীভ নাকি খারাপ ছেলে বলে দিয়েছে আবেগ... ...তার শক্তি চাই।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَرَوْحٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏هِيَ الْعَصْرُ ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏سُئِلَ عَنْ صَلَاةِ الْوُسْطَى ‏","","",""],[19225,19225,"","আমরা আমাদের কাজ ভাল করে করেছি আর আমরা আমাদের সাহায্য করতে বলেছি। ভালো, একজন সৈন্য বলেছিল যে তাকে যেতে হবে, সে তার সব অক্ষর বিক্রি করে দিয়েছে। আর বলে সে তার কাজে আছে আর তাকে ফোন করেছে আর সে আটকে গেছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَيَزِيدُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏وَبَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏كُلُّ غُلَامٍ ‏ ‏رَهِينَةٌ ‏ ‏بِعَقِيقَتِهِ ‏ ‏تُذْبَحُ عَنْهُ يَوْمَ سَابِعِهِ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏وَيُدَمَّى وَيُسَمَّى فِيهِ وَيُحْلَقُ ‏ ‏قَالَ ‏ ‏يَزِيدُ ‏ ‏رَأْسُهُ ‏","","",""],[19226,19226,"","আমরা আনন্দের সাথে এই ভেবে বাপ্তাইজিত হয়েছি এবং আমরা যখন একটি সময় দ্বারা আক্রান্ত হয়েছি, আমরা আইনের শাসন নিয়ে এক নিয়ম তৈরি করেছি, তখন ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং লর্ডের কাছে আত্মসমর্পণ করেছেন তাকে খুঁজতে গিয়ে তার বাবার পুরষ্কার পেতে, আমি কিছু মনে করি না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَبَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى ‏ ‏جَائِزَةٌ لِأَهْلِهَا ‏ ‏قَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏فِي حَدِيثِهِ لِأَهْلِهَا ‏ ‏أَوْ مِيرَاثٌ لِأَهْلِهَا ‏","","",""],[19227,19227,"","আমরা আবেগ নিয়ে কথা বলেছি যে আমরা ভালোর জন্য কাজ করেছি, ভাল কিছু করার চেয়ে ভালো কিছু করার চেয়ে বরং ভালো কিছু করার জন্য। তাকে ও ল্যানকে প্রথমে বিয়ে করেছিল এবং আমাকে তার স্বামীর কাছ থেকে বিক্রি করে দিয়েছিল ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَشَكَّ فِيهِ فِي كِتَابِ الْبُيُوعِ ‏ ‏فَقَالَ عَنْ ‏ ‏عُقْبَةَ ‏ ‏أَوْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا امْرَأَةٍ زَوَّجَهَا ‏ ‏وَلِيَّانِ ‏ ‏فَهِيَ لِلْأَوَّلِ مِنْهُمَا وَمَنْ بَاعَ بَيْعًا مِنْ رَجُلَيْنِ فَهُوَ لِلْأَوَّلِ مِنْهُمَا ‏","","",""],[19228,19228,"","আমরা কামনা আর দৃঢ়সংকল্প নিয়ে কথা বলেছি, কিন্তু আমরা ভালো শাসনের জন্য আনন্দিত হব। লর্ড তার জন্য প্রার্থনা করলেন এবং আমি যা করেছি তা হাত থেকে তাকে উদ্ধার করলাম যাতে তিনি তা করতে এবং কাজ করতে পারেন একটা ছেলে মারা গেছে বলে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَمُحَمَّدُ بْنُ بِشْرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَلَى الْيَدِ مَا أَخَذَتْ حَتَّى تُؤَدِّيَهُ ‏ ‏وَقَالَ ‏ ‏ابْنُ بِشْرٍ ‏ ‏حَتَّى تُؤَدِّيَ ‏","","",""],[19229,19229,"","ঈশ্বরের এক অনুগ্রহের মধ্যে একজন ব্যক্তি একবার একজন ঈশ্বরকে বলতে শিখিয়েছিলেন যে, তিনি হলেন একজন দেবতা । এমন কোন দিন বিশ্বাস করা হয়না যে অর্ধ ডজন লোক খুঁজে পায়নি।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏وَيَزِيدُ ‏ ‏وَحَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنِي ‏ ‏قُدَامَةُ بْنُ وَبَرَةَ ‏ ‏رَجُلٌ مِنْ ‏ ‏بَنِي عُجَيْفٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَرَكَ جُمُعَةً فِي غَيْرِ عُذْرٍ فَلْيَتَصَدَّقْ بِدِينَارٍ فَإِنْ لَمْ يَجِدْ فَنِصْفُ دِينَارٍ ‏","","",""],[19230,19230,"","আমরা একবার বলেছি যে তাকে তার অনুগ্রহের ব্যাপারে কিছু করতে বলা হয়েছে, ঈশ্বর বাড়ির প্রতিবেশীকে তার কাছ থেকে যে স্ট্রিমগুলো নিয়ে এসেছেন তা নিয়ে তদন্ত করতে বলেছেন। ঈর্ষা ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَارُ الدَّارِ أَحَقُّ بِالدَّارِ مِنْ غَيْرِهِ ‏","","",""],[19231,19231,"","ঈশ্বর যিনি আলো দিয়েছেন এবং বধির লোকেদের কাছে গিয়েছেন, তিনি সেই ব্যক্তিদের উদ্ধার করতে পারবেন ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ فَبِهَا ‏ ‏وَنِعْمَتْ وَمَنْ اغْتَسَلَ فَذَلِكَ أَفْضَلُ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏فِي حَدِيثِهِ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏","","",""],[19232,19232,"","আমরা এই ধরনের ঘটনার কথা বলেছি, যখন বধিররা যখন এই দুর্দশার মুখোমুখি হত তখন সেই ঘটনার কথা বলেছিল। তাদের জন্য টাকা দিতে হবে.","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَبْدُ الصَّمَدِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا نَكَحَ الْمَرْأَةَ ‏ ‏الْوَلِيَّانِ ‏ ‏فَهِيَ لِلْأَوَّلِ مِنْهُمَا وَإِذَا بِيعَ الْبَيْعُ مِنْ الرَّجُلَيْنِ فَهِيَ لِلْأَوَّلِ مِنْهُمَا ‏","","",""],[19233,19233,"","আমরা যে সময়ে যৌন সম্পর্ক করার কথা বলেছিলাম, সে বলতেই হচ্ছে, প্রার্থনা ছেড়ে প্রার্থনা করতে করতে করতে করতে করতে করতে তার ঘুম ভেঙে যায়।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حَافِظُوا عَلَى الصَّلَوَاتِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏الصَّلَاةِ وَالصَّلَاةِ الْوُسْطَى وَسَمَّاهَا لَنَا إِنَّمَا هِيَ صَلَاةُ الْعَصْرِ ‏","","",""],[19234,19234,"","তিনি বলেছিলেন, এক বৃষ্টিতে দু - জন তিমিকে এক বৃষ্টির মধ্যে একটা করে তিমির আঘাত করতে পারে ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فِي يَوْمٍ مَطِيرٍ ‏ ‏الصَّلَاةُ فِي ‏ ‏الرِّحَالِ ‏","","",""],[19235,19235,"","সে বলছে, সে তার জন্য প্রার্থনা করেছে আর বলবে যে, সে ভুল আর তুমি তার মাঝে জীবন ফিরে পাবে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏قَالَ وَحَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَمُرَةَ ‏ ‏يَخْطُبُ عَلَى مِنْبَرِ ‏ ‏الْبَصْرَةِ ‏ ‏وَهُوَ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ الْمَرْأَةَ خُلِقَتْ مِنْ ضِلْعٍ وَإِنَّكَ إِنْ تُرِدْ إِقَامَةَ الضِّلْعِ تَكْسِرْهَا فَدَارِهَا تَعِشْ بِهَا ‏","","",""],[19236,19236,"","আমরা বাবার সাথে যা ঘটেছে তার একটা তুমাতে খুশি হয়েছি, কিন্তু আমার বাবা একসময় কাপুরুষ ছিলেন। ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি যা বলেছেন তা দেখে তার মুখ বন্ধ করে রেখেছেন। সে বলেছে, লাঞ্চের সময় সে আমার সাথে ব্যবহার করতে এসেছিল। আমাদের একজন হবে যে এটা করতে আসবে। সে পাথরের পিছু নিয়েছে, তারপর সে এটা নিয়ে গেছে, সে আবার জীবিত হয়েছে, প্রথম আমি বলেছি আমি ঈশ্বরের কাছে যাচ্ছি যেটা তারা বলেছিল আমাকে খুন করেছে। এবং তার পরে তার হৃদয়ের কথা। আর তার পরে আমি বললাম, \"আমার\" একটা বিশেষ আত্মা, আর তারপর সে আমার দাদাদের একজন। সে এটা করতে চেয়েছিল। তারপর সে তার মুখের অন্য দিকে চলে যাবে। প্রথমে সে কিভাবে এটা করতে হয় সে তাই করতে পারে? যদি আমাদের নিজস্ব কথা থাকে, তাহলে আমি কেবল পুরুষ এবং নারীদের খুন করেছি যারা খুব দুর্বল তাদের মেরে ফেলেছি। তারা আমাকে বলেছে যে আমরা মারা গেছি, তাই আমাকে বলা হয়েছে। ( হিতোপদেশ ১৪: ১) একজন ব্যক্তি যখন তার কাছে ফিরে আসেন, তখন তিনি যখন তা করতে চান, তখন তিনি ফিরে আসেন । তারা আমাকে বলেছে যদি আমরা কোন মেয়েকে ঈশ্বরের সব দুঃখ থেকে দেখি তাহলে তাকে ফেলে দেই। টেবিলটা এমন লম্বা, যে মানুষ হিসেবে আমি আকাশের দিকে তার নেতৃত্বকে খুব কমই দেখি না এবং তাই আমি বলেছি। আমি বলেছিলাম এটা ছিল আমার জীবনের সবচেয়ে বড় ভুল। আমি আপনাদের সামনে তুলে ধরতে চাই। আমি আপনাদের সবাইকে বলছি, আমি আপনাদের সামনে হাজির করতে চাই। আমি আপনাদের সাথে আমার জীবনের উদ্দেশ্য হচ্ছে, আমি আপনাদের সাথে জড়িত। আমি আপনাদের কাছে এটা একটা বিষয় নিয়ে কথা বলেছি। আমি যদি আমার মনে করি, আমি আপনাদের সামনে থেকে বলছি, আমি আপনাদের সামনে হাজির হতে চাই, আমি যদি আমার মনে হয়, আমি আপনাদের সাথে আমার মনে হয়, আমি আমার মনে করি, আমি কি করবো, আমি জানি, আমি জানি যে, আমি জানি, আমি জানি, আমি জানি, আমি কি না যে, আমি জানি, আমি এটা একটা মানুষ। আমি কি করবো? যা আমাকে সব সময় বলা হয়েছে তা ভুল, আমি তার থেকে ভাল, আর আমি তার থেকে ভাল বলতে চাই আমি তার থেকে দূরে আছি। মনে হয় তারা যখন নদীর মধ্যে গিয়ে গিয়েছিল, তখন আমরা হালকাভাবে এগিয়ে গিয়েছিলাম । সাদারা বলেছিল তারা তার কাছে গিয়েছে আর তারপর তারা আমাদের কাছে ফিরে এসেছে. আর এটা হল তোমার বাড়ি. আমি ভেবেছিলাম তুমি তাকে ছেড়ে দিবে, সে আমাকে বলেছে তুমি এখন তার ভিতরে আছো, সে বলল যে আমি তাকে দেখেছি তারপর থেকে তাকে দেখেছি. আমরা তোমাকে বলব এই মানুষটিকে ছেড়ে দিতে প্রথম ব্যক্তি, যেই ব্যাক্তি তার সম্মান করতে এসেছে তাকে না পাওয়ার ক্ষমতা... আত্মারা হচ্ছে জাঞ্জানা আর জোন্না, অথবা যে কিনা নদী ও দেবতা দ্বারা আদেশ দেয়, আগুনের আগুন তার প্রতি ঈর্ষা করে, এটা তোমার টাকা, কিংবা পাইলট সেটা দেখেছে। সেই দৈত্যটা বলেছিল যে, ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং তিনি হবেন । ঈশ্বরের পুত্র এবং ঈশ্বরের প্রভু দ্বারা রক্ষা পেয়েছি। তারা একটা চাকরির সাথে যুক্ত এবং তাদের জন্য ঈশ্বরের বিরুদ্ধে যুদ্ধ করা হয়েছে। আমি আমার জীবনকে সাদাসিধে করেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏أَبِي رَجَاءٍ الْعُطَارِدِيِّ ‏ ‏حَدَّثَنَا ‏ ‏سَمُرَةُ بْنُ جُنْدُبٍ الْفَزَارِيُّ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِمَّا يَقُولُ لِأَصْحَابِهِ هَلْ رَأَى أَحَدٌ مِنْكُمْ رُؤْيَا قَالَ فَيَقُصُّ عَلَيْهِ مَنْ شَاءَ اللَّهُ أَنْ يَقُصَّ قَالَ وَإِنَّهُ قَالَ لَنَا ذَاتَ غَدَاةٍ ‏ ‏إِنَّهُ أَتَانِي اللَّيْلَةَ آتِيَانِ وَإِنَّهُمَا ابْتَعَثَانِي وَإِنَّهُمَا قَالَا لِي انْطَلِقْ وَإِنِّي انْطَلَقْتُ مَعَهُمَا وَإِنَّا أَتَيْنَا عَلَى رَجُلٍ مُضْطَجِعٍ وَإِذَا آخَرُ قَائِمٌ عَلَيْهِ بِصَخْرَةٍ وَإِذَا هُوَ يَهْوِي عَلَيْهِ بِالصَّخْرَةِ لِرَأْسِهِ ‏ ‏فَيَثْلَغُ ‏ ‏بِهَا رَأْسَهُ ‏ ‏فَيَتَدَهْدَهُ ‏ ‏الْحَجَرُ هَاهُنَا فَيَتْبَعُ الْحَجَرَ يَأْخُذُهُ فَمَا يَرْجِعُ إِلَيْهِ حَتَّى يَصِحَّ رَأْسُهُ كَمَا كَانَ ثُمَّ يَعُودُ عَلَيْهِ فَيَفْعَلُ بِهِ مِثْلَ مَا فَعَلَ الْمَرَّةَ الْأُولَى قَالَ قُلْتُ سُبْحَانَ اللَّهِ مَا هَذَانِ قَالَ قَالَا لِي انْطَلِقْ انْطَلِقْ فَانْطَلَقْتُ مَعَهُمَا فَأَتَيْنَا عَلَى رَجُلٍ مُسْتَلْقٍ لِقَفَاهُ وَإِذَا آخَرُ قَائِمٌ عَلَيْهِ ‏ ‏بِكَلُّوبٍ ‏ ‏مِنْ حَدِيدٍ وَإِذَا هُوَ يَأْتِي أَحَدَ شِقَّيْ وَجْهِهِ ‏ ‏فَيُشَرْشِرُ ‏ ‏شِدْقَهُ ‏ ‏إِلَى قَفَاهُ وَمَنْخِرَاهُ إِلَى قَفَاهُ وَعَيْنَاهُ إِلَى قَفَاهُ قَالَ ثُمَّ يَتَحَوَّلُ إِلَى الْجَانِبِ الْآخَرِ فَيَفْعَلُ بِهِ مِثْلَ مَا فَعَلَ بِالْجَانِبِ الْأَوَّلِ فَمَا يَفْرُغُ مِنْ ذَلِكَ الْجَانِبِ حَتَّى يَصِحَّ الْأَوَّلُ كَمَا كَانَ ثُمَّ يَعُودُ فَيَفْعَلُ بِهِ مِثْلَ مَا فَعَلَ بِهِ الْمَرَّةَ الْأُولَى قَالَ قُلْتُ سُبْحَانَ اللَّهِ مَا هَذَانِ قَالَ قَالَا لِي انْطَلِقْ انْطَلِقْ قَالَ فَانْطَلَقْنَا فَأَتَيْنَا عَلَى مِثْلِ بِنَاءِ ‏ ‏التَّنُّورِ ‏ ‏قَالَ ‏ ‏عَوْفٌ ‏ ‏وَأَحْسَبُ أَنَّهُ قَالَ وَإِذَا فِيهِ ‏ ‏لَغَطٌ ‏ ‏وَأَصْوَاتٌ ‏ ‏قَالَ فَاطَّلَعْتُ فَإِذَا فِيهِ رِجَالٌ وَنِسَاءٌ عُرَاةٌ وَإِذَا هُمْ ‏ ‏يَأْتِيهِمْ لَهِيبٌ مِنْ أَسْفَلَ مِنْهُمْ فَإِذَا أَتَاهُمْ ذَلِكَ اللَّهَبُ ‏ ‏ضَوْضَوْا ‏ ‏قَالَ قُلْتُ مَا هَؤُلَاءِ قَالَ قَالَا لِي انْطَلِقْ انْطَلِقْ قَالَ فَانْطَلَقْنَا فَأَتَيْنَا عَلَى نَهَرٍ ‏ ‏حَسِبْتُ أَنَّهُ قَالَ أَحْمَرَ مِثْلِ الدَّمِ ‏ ‏وَإِذَا فِي النَّهَرِ رَجُلٌ يَسْبَحُ ثُمَّ يَأْتِي ذَلِكَ الرَّجُلُ الَّذِي قَدْ جَمَعَ الْحِجَارَةَ ‏ ‏فَيَفْغَرُ ‏ ‏لَهُ فَاهُ فَيُلْقِمُهُ حَجَرًا حَجَرًا قَالَ فَيَنْطَلِقُ فَيَسْبَحُ مَا يَسْبَحُ ثُمَّ يَرْجِعُ إِلَيْهِ كُلَّمَا رَجَعَ إِلَيْهِ ‏ ‏فَغَرَ ‏ ‏لَهُ فَاهُ وَأَلْقَمَهُ حَجَرًا قَالَ قُلْتُ مَا هَذَا قَالَ قَالَا لِي انْطَلِقْ انْطَلِقْ فَانْطَلَقْنَا فَأَتَيْنَا عَلَى رَجُلٍ كَرِيهِ الْمَرْآةِ كَأَكْرَهِ مَا أَنْتَ رَاءٍ رَجُلًا مَرْآةً فَإِذَا هُوَ عِنْدَ نَارٍ لَهُ ‏ ‏يَحُشُّهَا ‏ ‏وَيَسْعَى حَوْلَهَا قَالَ قُلْتُ لَهُمَا مَا هَذَا قَالَ قَالَا لِي انْطَلِقْ انْطَلِقْ قَالَ فَانْطَلَقْنَا ‏ ‏فَأَتَيْنَا عَلَى رَوْضَةٍ ‏ ‏مُعْشِبَةٍ ‏ ‏فِيهَا مِنْ كُلِّ نَوْرِ الرَّبِيعِ قَالَ وَإِذَا بَيْنَ ‏ ‏ظَهْرَانَيْ ‏ ‏الرَّوْضَةِ رَجُلٌ قَائِمٌ طَوِيلٌ لَا أَكَادُ أَنْ أَرَى رَأْسَهُ طُولًا فِي السَّمَاءِ وَإِذَا حَوْلَ الرَّجُلِ مِنْ أَكْثَرِ وِلْدَانٍ رَأَيْتُهُمْ قَطُّ وَأَحْسَنِهِ قَالَ قُلْتُ لَهُمَا مَا هَذَا وَمَا هَؤُلَاءِ قَالَ قَالَا لِي انْطَلِقْ انْطَلِقْ قَالَ فَانْطَلَقْنَا فَانْتَهَيْنَا إِلَى ‏ ‏دَوْحَةٍ ‏ ‏عَظِيمَةٍ لَمْ أَرَ ‏ ‏دَوْحَةً ‏ ‏قَطُّ أَعْظَمَ مِنْهَا وَلَا أَحْسَنَ قَالَ فَقَالَا لِي ‏ ‏ارْقَ ‏ ‏فِيهَا ‏ ‏فَارْتَقَيْنَا ‏ ‏فِيهَا فَانْتَهَيْتُ إِلَى مَدِينَةٍ مَبْنِيَّةٍ بِلَبِنٍ ذَهَبٍ وَلَبِنٍ فِضَّةٍ فَأَتَيْنَا بَابَ الْمَدِينَةِ فَاسْتَفْتَحْنَا فَفُتِحَ لَنَا فَدَخَلْنَا فَلَقِينَا فِيهَا رِجَالًا ‏ ‏شَطْرٌ ‏ ‏مِنْ خَلْقِهِمْ كَأَحْسَنِ مَا أَنْتَ رَاءٍ ‏ ‏وَشَطْرٌ ‏ ‏كَأَقْبَحِ مَا أَنْتَ رَاءٍ قَالَ فَقَالَا لَهُمْ اذْهَبُوا فَقَعُوا فِي ذَلِكَ النَّهَرِ فَإِذَا نَهَرٌ صَغِيرٌ ‏ ‏مُعْتَرِضٌ ‏ ‏يَجْرِي كَأَنَّمَا هُوَ ‏ ‏الْمَحْضُ ‏ ‏فِي الْبَيَاضِ قَالَ فَذَهَبُوا فَوَقَعُوا فِيهِ ثُمَّ رَجَعُوا إِلَيْنَا وَقَدْ ذَهَبَ ذَلِكَ السُّوءُ عَنْهُمْ وَصَارُوا فِي أَحْسَنِ صُورَةٍ قَالَ فَقَالَا لِي هَذِهِ جَنَّةُ عَدْنٍ وَهَذَاكَ مَنْزِلُكَ قَالَ فَبَيْنَمَا بَصَرِي صُعُدًا فَإِذَا قَصْرٌ مِثْلُ ‏ ‏الرَّبَابَةِ ‏ ‏الْبَيْضَاءِ قَالَا لِي هَذَاكَ مَنْزِلُكَ قَالَ قُلْتُ لَهُمَا بَارَكَ اللَّهُ فِيكُمَا ذَرَانِي فَلَأَدْخُلُهُ قَالَ قَالَا لِي الْآنَ فَلَا وَأَنْتَ دَاخِلُهُ قَالَ فَإِنِّي رَأَيْتُ مُنْذُ اللَّيْلَةِ عَجَبًا فَمَا هَذَا الَّذِي رَأَيْتُ قَالَ قَالَا لِي أَمَا إِنَّا سَنُخْبِرُكَ أَمَّا الرَّجُلُ الْأَوَّلُ الَّذِي أَتَيْتَ عَلَيْهِ ‏ ‏يُثْلَغُ ‏ ‏رَأْسُهُ بِالْحَجَرِ فَإِنَّهُ رَجُلٌ يَأْخُذُ الْقُرْآنَ فَيَرْفُضُهُ وَيَنَامُ عَنْ الصَّلَوَاتِ الْمَكْتُوبَةِ وَأَمَّا الرَّجُلُ الَّذِي أَتَيْتَ عَلَيْهِ ‏ ‏يُشَرْشَرُ ‏ ‏شِدْقُهُ ‏ ‏إِلَى قَفَاهُ وَعَيْنَاهُ إِلَى قَفَاهُ وَمَنْخِرَاهُ إِلَى قَفَاهُ فَإِنَّهُ الرَّجُلُ يَغْدُو مِنْ بَيْتِهِ فَيَكْذِبُ الْكَذِبَةَ تَبْلُغُ الْآفَاقَ وَأَمَّا الرِّجَالُ وَالنِّسَاءُ الْعُرَاةُ الَّذِينَ فِي بِنَاءٍ مِثْلِ بِنَاءِ ‏ ‏التَّنُّورِ ‏ ‏فَإِنَّهُمْ الزُّنَاةُ وَالزَّوَانِي وَأَمَّا الرَّجُلُ الَّذِي يَسْبَحُ فِي النَّهَرِ وَيُلْقَمُ الْحِجَارَةَ فَإِنَّهُ آكِلُ الرِّبَا وَأَمَّا الرَّجُلُ الْكَرِيهُ الْمَرْآةِ الَّذِي عِنْدَ النَّارِ ‏ ‏يَحُشُّهَا ‏ ‏فَإِنَّهُ ‏ ‏مَالِكٌ ‏ ‏خَازِنُ ‏ ‏جَهَنَّمَ وَأَمَّا الرَّجُلُ الطَّوِيلُ الَّذِي رَأَيْتَ فِي الرَّوْضَةِ فَإِنَّهُ ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَأَمَّا الْوِلْدَانُ الَّذِينَ حَوْلَهُ فَكُلُّ مَوْلُودٍ مَاتَ عَلَى الْفِطْرَةِ قَالَ فَقَالَ بَعْضُ الْمُسْلِمِينَ يَا رَسُولَ اللَّهِ وَأَوْلَادُ الْمُشْرِكِينَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَوْلَادُ الْمُشْرِكِينَ وَأَمَّا الْقَوْمُ الَّذِينَ كَانَ ‏ ‏شَطْرٌ ‏ ‏مِنْهُمْ حَسَنًا ‏ ‏وَشَطْرٌ ‏ ‏قَبِيحًا فَإِنَّهُمْ خَلَطُوا عَمَلًا صَالِحًا وَآخَرَ سَيِّئًا فَتَجَاوَزَ اللَّهُ عَنْهُمْ ‏ ‏سَمِعْت ‏ ‏مِنْ ‏ ‏عَبَّادِ بْنِ عَبَّادٍ ‏ ‏يُخْبِرُ بِهِ عَنْ ‏ ‏عَوْفٍ ‏ ‏عَنْ ‏ ‏أَبِي رَجَاءٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏فَيَتَدَهْدَهُ ‏ ‏الْحَجَرُ هَاهُنَا ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏فَجَعَلْتُ أَتَعَجَّبُ مِنْ فَصَاحَةِ ‏ ‏عَبَّادٍ ‏","","",""],[19237,19237,"","আমরা আমাদের বাবার মৃত্যুকে আমার সমুদ্র প্রেম দিয়ে দিয়ে দিয়ে এটা করার মাধ্যমে রক্ষা করেছি। সে বলেছে, আমি ঈশ্বরের কাছে প্রার্থনা করতে চাই এবং তিনি যে যুদ্ধ করেছেন, তা তিনি একবার করেছেন। শত বছর ধরে, তার পুলিশ বাহিনী আমার ছেলের বিরুদ্ধে যুদ্ধ করেছে, আমার একজন মহান কামনাকারী, আইনের আইন আছে এবং সে জানে না সে কি বলছে, ঈশ্বর, সে বিজ্ঞানের নাম। তাই সে বলেছে, সে নাকি বিচ্ছিন্ন।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ أَبِي الْحُرِّ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا ‏ ‏الْحَجَّامَ ‏ ‏فَأَتَاهُ بِقُرُونٍ فَأَلْزَمَهُ إِيَّاهَا ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً بِقَرْنٍ ثُمَّ شَرَطَهُ ‏ ‏بِشَفْرَةٍ ‏ ‏فَدَخَلَ أَعْرَابِيٌّ مِنْ ‏ ‏بَنِي فَزَارَةَ ‏ ‏أَحَدِ ‏ ‏بَنِي جَذِيمَةَ ‏ ‏فَلَمَّا رَآهُ ‏ ‏يَحْتَجِمُ ‏ ‏وَلَا ‏ ‏عَهْدَ ‏ ‏لَهُ ‏ ‏بِالْحِجَامَةِ ‏ ‏وَلَا يَعْرِفُهَا قَالَ مَا هَذَا يَا رَسُولَ اللَّهِ عَلَامَ تَدَعُ هَذَا يَقْطَعُ جِلْدَكَ قَالَ هَذَا ‏ ‏الْحَجْمُ ‏ ‏قَالَ وَمَا ‏ ‏الْحَجْمُ ‏ ‏قَالَ هَذَا مِنْ خَيْرِ مَا تَدَاوَى بِهِ النَّاسُ ‏","","",""],[19238,19238,"","আমরা কথা বলেছিলাম একটা ভালুকের মত সে আমাকে বলতে বলেছে সে নাকি দেবতা হতে যাচ্ছে, সে রাতে হাল ছেড়ে দেবে না যখন সে নির্দোষ আর কখনো না একদিন যেতে দাও।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنِي ‏ ‏سَوَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَمُرَةَ بْنَ جُنْدُبٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَغُرَّنَّكُمْ نِدَاءُ ‏ ‏بِلَالٍ ‏ ‏فَإِنَّ فِي بَصَرِهِ سُوءًا وَلَا بَيَاضٌ يُرَى بِأَعْلَى ‏ ‏السَّحَرِ ‏","","",""],[19239,19239,"","আমাদের আলোচনা সম্পর্কে আমরা কথা বলেছি, এবং তিনি আমার বাবার সম্পর্কে কথা বলেছেন যে আমার বাবার ভয় পেয়েছে। প্রভুর জন্য দুঃখ হচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏وَيَزِيدُ بْنُ زُرَيْعٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏دَاوُدُ ‏ ‏عَنْ ‏ ‏أَبِي قَزَعَةَ ‏ ‏عَنِ ‏ ‏الْأَسْقَعِ بْنِ الْأَسْلَعِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا أَسْفَلَ مِنْ الْكَعْبَيْنِ مِنْ ‏ ‏الْإِزَارِ ‏ ‏فِي النَّارِ ‏","","",""],[19240,19240,"","আমরা একবার এটা করার চেয়ে বরং বরং ভাল হওয়ার জন্য যেতে কথা বলেছি। তিনি বলেন, বাবা বাবা বলেন \"ভালবাসি\" এবং \"বাবা\" \"বাবা\" \"বাবা\" \"বাবা\" এবং \"বাবা\" বাবাকে\" ভালবাসে\"","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَامُ ‏ ‏أَبُو ‏ ‏الْعَرَبِ ‏ ‏وَحَامُ ‏ ‏أَبُو ‏ ‏الْحَبَشِ ‏ ‏وَيَافِثُ ‏ ‏أَبُو ‏ ‏الرُّومِ ‏","","",""],[19241,19241,"","তিনি আমার বাবা আর আমরা কথা বলেছি বলতে, আল্লাহ আছে আর তিনি বললেন স্যামের বাবার ভালোবাসা জয় করতে।","‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ وَحَدَّثَ ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏سَامُ ‏ ‏أَبُو ‏ ‏الْعَرَبِ ‏ ‏وَيَافِثُ ‏ ‏أَبُو ‏ ‏الرُّومِ ‏ ‏وَحَامُ ‏ ‏أَبُو ‏ ‏الْحَبَشِ ‏","","",""],[19242,19242,"","একবার সে বলেছিল যে সে দেবতা হবে, আমি খুশি হব দিনের মধ্যে আর ব্যবসা চলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏عَنْ ‏ ‏أَبِي رَجَاءٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ نَبِيُّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَيْتُ لَيْلَةَ أُسْرِيَ بِي رَجُلًا يَسْبَحُ فِي نَهَرٍ ‏ ‏وَيُلْقَمُ ‏ ‏الْحِجَارَةَ فَسَأَلْتُ مَا هَذَا فَقِيلَ لِي آكِلُ الرِّبَا ‏","","",""],[19243,19243,"","ঈশ্বর তার জন্য প্রার্থনা করেছিলেন এবং তিনি টাকাপয়সা ও ক্ষমতা দেওয়ার কারণ ও ক্ষমতা দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏حَدَّثَنَا ‏ ‏سَلَّامُ بْنُ أَبِي مُطِيعٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْحَسَبُ الْمَالُ وَالْكَرَمُ التَّقْوَى ‏","","",""],[19244,19244,"","আমরা কয়েক বার কথা বলেছি, কিন্তু আমরা কিছু সময় শুনলাম। আমার ছেলে এটা শোনে এবং সে বলবে, আগুন হচ্ছে কে তুমি নিয়ে যাবে। তাদের কাছ থেকে নিয়ে নিতে আগুন লাগে।","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ بْنُ مُحَمَّدٍ ‏ ‏وَحُسَيْنٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَسَمِعْتُ ‏ ‏أَبَا نَضْرَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّهُ ‏ ‏سَمِعَ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْهُمْ مَنْ تَأْخُذُهُ النَّارُ إِلَى كَعْبَيْهِ وَمِنْهُمْ مَنْ تَأْخُذُهُ النَّارُ إِلَى رُكْبَتَيْهِ وَمِنْهُمْ مَنْ تَأْخُذُهُ النَّارُ إِلَى حُجْزَتِهِ وَمِنْهُمْ مَنْ تَأْخُذُهُ النَّارُ إِلَى ‏ ‏تَرْقُوَتِهِ ‏","","",""],[19245,19245,"","ঈশ্বর তাদের বলেন যে, কে তাঁকে হত্যা করেছে এবং কে তাঁকে নিজের জীবন দিতে এসেছে ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو النَّضْرِ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏وَلَمْ يَسْمَعْهُ مِنْهُ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَتَلَ عَبْدَهُ قَتَلْنَاهُ وَمَنْ ‏ ‏جَدَعَ ‏ ‏عَبْدَهُ ‏ ‏جَدَعْنَاهُ ‏","","",""],[19246,19246,"","তিনি আমাদের সাদা কাপড় থেকে আসা দুঃখকে রক্ষা করেছিলেন এবং তাদেরকে মৃত্যু থেকে বিরত করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏عَنْ ‏ ‏خَالِدٍ الْحَذَّاءِ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَسُوا مِنْ ثِيَابِكُمْ الْبِيضَ وَكَفِّنُوا فِيهَا مَوْتَاكُمْ ‏","","",""],[19247,19247,"","আমরা ভাল করেছি যে, মূসা আমাদের একসাথে নিয়ে এসেছেন আপনার দায়িত্বের অনুগ্রহ থেকে মুক্ত করার জন্য। আমি একটি ছেলের জন্য আপশোস করছি কারণ এটা মুক্ত হওয়ার জন্য হয়েছে। ঈশ্বর আদেশ দিয়েছেন। তিনি বলেন যে ঈশ্বর আছেন । অথবা চলে যাও।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عُقْبَةَ الْفَزَارِيِّ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏الْحَجَّاجِ بْنِ يُوسُفَ ‏ ‏فَقُلْتُ أَصْلَحَ اللَّهُ الْأَمِيرَ أَلَا أُحَدِّثُكَ حَدِيثًا ‏ ‏حَدَّثَنِيهِ ‏ ‏سَمُرَةُ بْنُ جُنْدُبٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ بَلَى قَالَ سَمِعْتُهُ يَقُولُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَسَائِلُ ‏ ‏كَدٌّ ‏ ‏يَكُدُّ ‏ ‏بِهَا الرَّجُلُ وَجْهَهُ فَمَنْ شَاءَ أَبْقَى عَلَى وَجْهِهِ وَمَنْ شَاءَ تَرَكَ إِلَّا أَنْ يَسْأَلَ رَجُلٌ ذَا سُلْطَانٍ أَوْ يَسْأَلَ فِي أَمْرٍ لَا بُدَّ مِنْهُ ‏","","",""],[19248,19248,"","আমরা একটা মাসোর কথা বলেছি, যে কিনা ঈশ্বরকে ভয় করে, সে তার কাছে প্রার্থনা করে, আর আমি তোমাকে আশীর্বাদ করি ঈশ্বরের কাছে। আপনি বলেন যে, এর মূল্য এমন নয়, যখন আমি উপেক্ষা করব না ।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏رَبِيعِ بْنِ عَمِيلَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَبُّ الْكَلَامِ إِلَى اللَّهِ تَبَارَكَ وَتَعَالَى أَرْبَعٌ لَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ لَا يَضُرُّكَ بِأَيِّهِنَّ بَدَأْتَ لَا تُسَمِّيَنَّ غُلَامَكَ يَسَارًا وَلَا رَبَاحًا وَلَا نَجِيحًا وَلَا أَفْلَحًا فَإِنَّكَ تَقُولُ أَثَمَّ هُوَ فَلَا يَكُونُ فَيَقُولُ لَا إِنَّمَا هُنَّ أَرْبَعٌ لَا تَزِيدُنَّ عَلَيَّ ‏","","",""],[19249,19249,"","আমরা বাবার সাথে কথা বলেছি, আমার বাবার ভালবাসার সাথে কঠিন সময় কাটাব, সে তাদেরকে দিয়ে দিবে যাকে তুমি তার হাড় থেকে তাকে মুক্ত করবে আর তার কাছ থেকে নিয়ে যাবে.","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مِنْهُمْ مَنْ تَأْخُذُهُ النَّارُ إِلَى رُكْبَتَيْهِ وَمِنْهُمْ مَنْ تَأْخُذُهُ إِلَى ‏ ‏حُجْزَتِهِ ‏ ‏وَمِنْهُمْ مَنْ تَأْخُذُهُ إِلَى ‏ ‏تَرْقُوَتِهِ ‏","","",""],[19250,19250,"","আমরা সেই বধিরদের কথা বলেছি যাদের আমরা ভালো নাম দিয়েছি তাকে ছেড়ে দিতে হবে, যে তার মজাটা পেয়েছে তার চোখ দিয়ে সে একটা পাগলের মত তদন্ত করছে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ وَجَدَ مَتَاعَهُ عِنْدَ مُفْلِسٍ بِعَيْنِهِ فَهُوَ أَحَقُّ بِهِ ‏","","",""],[19251,19251,"","একবার তিনি এটা লর্ডের মাধ্যমে করেছিলেন এবং তাঁকে অত্যাচার করার সময় তিনি তাকে উদ্ধার করেছিলেন।","‏ ‏وَعَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَيِّتُ يُعَذَّبُ بِمَا ‏ ‏نِيحَ ‏ ‏عَلَيْهِ ‏","","",""],[19252,19252,"","আমরা মোশির সাথে ভালো ব্যবহার করেছি, আমরা আমাদের দেখা থেকে ভালো মানুষ হতে পেরে খুশি হব। ঈশ্বর তাঁর জন্য প্রার্থনা করেছেন এবং তাকে গদিতে ব্যবহার করা হবে এবং ভুলে যাওয়া হবে না।","‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ بَشِيرٍ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَعْتَدِلَ فِي الْجُلُوسِ وَأَنْ لَا نَسْتَوْفِزَ ‏","","",""],[19253,19253,"","আমরা তোমাকে ঈশ্বরের অনুগ্রহের ভিত্তিতে বিচার করার চেষ্টা করেছি, ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তার মৃত্যুর যোগ্যকে সমর্পণ করবেন। আমি যে খেতে থাকি সে অপরাধী না।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏الْحَكَمُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏احْضُرُوا الْجُمُعَةَ وَادْنُوا مِنْ الْإِمَامِ فَإِنَّ الرَّجُلَ لَيَتَخَلَّفُ عَنْ الْجُمُعَةِ حَتَّى إِنَّهُ لَيَتَخَلَّفُ عَنْ الْجَنَّةِ وَإِنَّهُ لَمِنْ أَهْلِهَا ‏","","",""],[19254,19254,"","আমি মনে মনে মনে মনে প্রার্থনা করি যেন ঈশ্বর আমাকে ভুলে যান ।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏أَشْعَثُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَّةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ صَلَّى صَلَاةَ ‏ ‏الْغَدَاةِ ‏ ‏فَهُوَ فِي ذِمَّةِ اللَّهِ فَلَا ‏ ‏تُخْفِرُوا ‏ ‏اللَّهَ تَبَارَكَ وَتَعَالَى فِي ذِمَّتِهِ ‏","","",""],[19255,19255,"","আমি তার বই নিয়ে কথা বলেছিলাম । প্রভুর বাবা, কাল তার সংরক্ষণের পর, তার তিনটা বিষাক্ত ঘটনা আছে, আর সে মারা যাচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏مِنْ كِتَابِهِ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَ ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏سَامُ ‏ ‏أَبُو ‏ ‏الْعَرَبِ ‏ ‏وَيَافِثُ ‏ ‏أَبُو ‏ ‏الرُّومِ ‏ ‏وَحَامُ ‏ ‏أَبُو ‏ ‏الْحَبَشِ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏بِبَغْدَادَ ‏ ‏مِنْ حِفْظِهِ وَلَدُ ‏ ‏نُوحٍ ‏ ‏ثَلَاثَةٌ ‏ ‏سَامُ ‏ ‏وَحَامُ ‏ ‏وَيَافِثُ ‏","","",""],[19256,19256,"","আমরা এই ঋতুর সর্বোত্তম দিক নিয়ে কথা বলেছি, ঈশ্বর তাকে উদ্ধার করতে বলেছেন, তিনি তার ভাইয়ের পাপের জন্য পাপ করবেন অথবা তার ইচ্ছা উপভোগ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ الطَّيَالِسِيُّ ‏ ‏حَدَّثَنَا ‏ ‏عِمْرَانُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ يَخْطُبَ الرَّجُلُ عَلَى خِطْبَةِ أَخِيهِ أَوْ ‏ ‏يَبْتَاعَ ‏ ‏عَلَى بَيْعِهِ ‏","","",""],[19257,19257,"","আমরা যখন তার চেয়ে ভালো হওয়ার কথা বলেছিলাম সে বলত, সে বলত আমাদের দু'জন ছেলে যদি আগে যেতে পারত তাহলে সে আমার বাবা মার কাছে বিক্রি করতো","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا نَكَحَ ‏ ‏وَلِيَّانِ ‏ ‏فَهِيَ لِلْأَوَّلِ وَإِذَا بَاعَ ‏ ‏وَلِيَّانِ ‏ ‏فَالْبَيْعُ لِلْأَوَّلِ ‏","","",""],[19258,19258,"","তিনি বলেছিলেন যে, কেন তিনি তার নিম্নের ক্ষমতা নিয়ে এসেছেন এবং তার নিজের জীবনই নয় কিন্তু তিনি তা সহ্য করতে পারতেন । এটা নাবিকের বাসা আর এটা তোমার দোষ ছিল উপকূল থেকে আর এটা আদেশ করে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَمَّا حَمَلَتْ ‏ ‏حَوَّاءُ ‏ ‏طَافَ بِهَا إِبْلِيسُ وَكَانَ لَا يَعِيشُ لَهَا وَلَدٌ فَقَالَ سَمِّيهِ ‏ ‏عَبْدَ الْحَارِثِ ‏ ‏فَإِنَّهُ يَعِيشُ فَسَمَّوْهُ ‏ ‏عَبْدَ الْحَارِثِ ‏ ‏فَعَاشَ وَكَانَ ذَلِكَ مِنْ وَحْيِ الشَّيْطَانِ وَأَمْرِهِ ‏","","",""],[19259,19259,"","তিনি বলেছেন যে আমি বাবার হাতে তার হাতের লেখা বই পেয়েছি এবং আমি মনে করি আমি হয়তো তার কথা শুনতে পাচ্ছি এমনকি সে বলেছে যে আমি আমার বাবার সাথে তার লেখার সময় আমি তার সাথে কথা বলেছি একবার, ভাববাদী তার কাছে প্রার্থনা করেছিলেন এবং বলবেন যে, তারা বিশ্বাস করে এবং রক্ষা পাওয়ার জন্য তাকে দেরি করতে হবে । আর তাকে ভিতরে আসতে দাও।","‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏وَجَدْتُ فِي كِتَابِ أَبِي بِخَطِّ يَدِهِ ‏ ‏وَأَكْبَرُ ظَنِّي أَنِّي قَدْ سَمِعْتُهُ مِنْهُ قَالَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏قَالَ وَجَدْتُ فِي كِتَابِ ‏ ‏أَبِي ‏ ‏بِخَطِّ يَدِهِ وَلَمْ أَسْمَعْهُ مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ مَالِكٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏احْضُرُوا الذِّكْرَ وَادْنُوا مِنْ الْإِمَامِ فَإِنَّ الرَّجُلَ لَا يَزَالُ يَتَبَاعَدُ حَتَّى يُؤَخَّرَ فِي الْجَنَّةِ وَإِنْ دَخَلَهَا ‏","","",""],[19260,19260,"","আমরা ঈশ্বরের সাথে আমার বাবার কথা বলেছি যে ঘুমাতে যাওয়ার চেয়ে ভালো কথা বলে, আল্লাহ বলতেই হবে যে এই উপাদান বা উপাদানের জন্য পর্দার সামনে রাখা হবে। অযৌক্তিকভাবে এই জাতিগততাকে ঢেকে দেয়।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏مَطَرٍ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى أَنْ ‏ ‏تُتَلَقَّى ‏ ‏الْأَجْلَابُ ‏ ‏حَتَّى تَبْلُغَ الْأَسْوَاقَ أَوْ يَبِيعَ حَاضِرٌ ‏ ‏لِبَادٍ ‏","","",""],[19261,19261,"","আমরা ঈশ্বরের সঙ্গে আমাদের সম্পর্কের বিষয়ে কথা বলেছিলাম, যা বয়স হয়ে যাওয়ার চেষ্টা করার চেয়ে আমাদের কাছে আরও বেশি গুরুত্বপূর্ণ । ( ২ করি.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَوَضَّأَ فَبِهَا ‏ ‏وَنِعْمَتْ وَمَنْ اغْتَسَلَ فَذَاكَ أَفْضَلُ ‏","","",""],[19262,19262,"","আমরা একটা স্বপ্ন নিয়ে কথা বলেছি বড় হওয়ার চেয়ে বড় হবার চেয়ে ভালো। সে বলল, যদি তুমি দুইটা বিয়ে দেখতে চাও তাহলে সে প্রথমে তাদের কাছে যাবে আর তারপর দরজা তার কাছে বিক্রি করবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أُنْكِحَتْ الْمَرْأَةُ زَوْجَيْنِ فَهِيَ لِلْأَوَّلِ مِنْهُمَا وَإِذَا بِيعَ الْبَيْعُ مِنْ رَجُلَيْنِ فَهُوَ لِلْأَوَّلِ مِنْهُمَا ‏","","",""],[19263,19263,"","তিনি নিজেকে আত্মসমর্পণ করেছিলেন এবং যিনি তাকে তার গলায় নিয়ে এসেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ عَبْدَهُ قَتَلْنَاهُ وَمَنْ ‏ ‏جَدَعَهُ ‏ ‏جَدَعْنَاهُ ‏","","",""],[19264,19264,"","আমরা একবার ওকে বলার চেয়ে ভালো কথা বলেছি, ঈশ্বর তাকে আত্মসমর্পণ করতে হবে... ...তোমার হাত গুটিয়ে রাখতে হবে আর তারপর তুমি হবে সূর্য শত্রু. আর তোমার মুখে খেয়ে নাও।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوشِكُ أَنْ يَمْلَأَ اللَّهُ عَزَّ وَجَلَّ أَيْدِيَكُمْ مِنْ ‏ ‏الْعَجَمِ ‏ ‏ثُمَّ ‏ ‏يَكُونُوا ‏ ‏أُسْدًا لَا يَفِرُّونَ فَيَقْتُلُونَ مُقَاتِلَتَكُمْ وَيَأْكُلُونَ فَيْئَكُمْ ‏","","",""],[19265,19265,"","আমরা আবেগ নিয়ে কথা বলেছি... ...যে আমরা বাবার ছেলের ছেলের খোঁজ নিয়ে এসেছি, এক সময় একজন সৈনিক বলেছিল যে, একজন ভালো রাজা সেরা ছবি তোলার জন্য এসেছে. তোমার বন্ধুরা তার ঋণের কারণে পাগলের দরজা দিয়ে আটকে আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الشَّعْبِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الصُّبْحَ فَقَالَ ‏ ‏هَاهُنَا أَحَدٌ مِنْ بَنِي فُلَانٍ قَالُوا نَعَمْ قَالَ إِنَّ صَاحِبَكُمْ مُحْتَبَسٌ عَلَى بَابِ الْجَنَّةِ فِي دَيْنٍ عَلَيْهِ ‏","","",""],[19266,19266,"","আমরা একটা আবেগ নিয়ে কথা বলেছি যা আমাদের হৃদয়ের মধ্যে একটা কাপুরুষের নামে শাসন করার জন্য এনেছে। তিনি আত্মসমর্পণ করেছেন এবং বলেছেন যে তাকে খুন করেছে তাকে অবশ্যই খুন করেছে এবং তাকে যে তাকে নিয়ে এসেছে তাকে খুঁজে বের করো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَتَلَ عَبْدَهُ قَتَلْنَاهُ وَمَنْ ‏ ‏جَدَعَهُ ‏ ‏جَدَعْنَاهُ ‏","","",""],[19267,19267,"","আমরা আবেগ সৃষ্টি করেছি যা আমাদের জন্য এক আদর্শ সন্তান হবার স্বপ্নের সৃষ্টি করেছে, ঈশ্বর তাকে আদেশ দিয়েছেন আমি যদি তোমার সাথে থাকি, সে বলবে এটা তোমার জন্য অনেক কষ্ট করে। ঈশ্বর এবং ত্রুষ কখনোই ঈশ্বর হন নি এবং ঈশ্বর তাকে ঈশ্বর বলে ডাকতে চান কেউ হাঁটছে না।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ إِذَا حَدَّثْتُكُمْ حَدِيثًا فَلَا تَزِيدُنَّ عَلَيْهِ وَقَالَ ‏ ‏أَرْبَعٌ مِنْ أَطْيَبِ الْكَلَامِ وَهُنَّ مِنْ الْقُرْآنِ لَا يَضُرُّكَ بِأَيِّهِنَّ بَدَأْتَ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ ثُمَّ قَالَ لَا تُسَمِّيَنَّ غُلَامَكَ أَفْلَحًا وَلَا نَجِيحًا وَلَا رَبَاحًا وَلَا يَسَارًا ‏","","",""],[19268,19268,"","তিনি যদি সেই রহস্যটি থেকে পালিয়ে যেতেন, তাহলে তিনি এখানে এই কথা বলতে পারতেন । বিশ্বাস করো।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏إِذَا كَبَّرَ سَكَتَ هُنَيَّةً وَإِذَا فَرَغَ مِنْ قِرَاءَةِ السُّورَةِ سَكَتَ هُنَيَّةً ‏ ‏فَأَنْكَرَ ذَلِكَ عَلَيْهِ ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏فَكَتَبُوا إِلَى ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏فَكَتَبَ ‏ ‏أُبَيٌّ ‏ ‏يُصَدِّقُهُ ‏","","",""],[19269,19269,"","আমরা কথা বলেছি একটা কাপুরুষের ব্যাজ নিয়ে লুকিয়ে লুকিয়ে থাকতে... ...ঈশ্বর তার জন্য প্রার্থনা করেছেন আর আমি বাড়ির প্রতিবেশীকে তুলেছি.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ الْخَفَّافُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَارُ الدَّارِ أَحَقُّ بِالدَّارِ ‏","","",""],[19270,19270,"","তিনি একবার প্রভুর কাছে এটা করেছিলেন, তিনি জয়ের জন্য প্রার্থনা করেছিলেন।","‏ ‏وَعَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصَّلَاةُ الْوُسْطَى صَلَاةُ الْعَصْرِ ‏","","",""],[19271,19271,"","তিনি বলেছিলেন, ঈশ্বর তার কাছে প্রার্থনা করেন এবং জিজ্ঞেস করেন, আমি কে ।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ أَحَاطَ حَائِطًا عَلَى أَرْضٍ فَهِيَ لَهُ ‏","","",""],[19272,19272,"","তিনি বলেছিলেন যে, তিনি যা কিছু করেছেন, তা তাকে দিতে হবে ।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى الْيَدِ مَا أَخَذَتْ حَتَّى تُؤَدِّيَ ‏","","",""],[19273,19273,"","তিনি বলেন, ঈশ্বর তার জন্য প্রার্থনা করেন এবং তাকে খুন করেন এবং তার দাদাকে তার কাছে নিয়ে আসেন।","‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ عَبْدَهُ قَتَلْنَاهُ وَمَنْ ‏ ‏جَدَعَهُ ‏ ‏جَدَعْنَاهُ ‏","","",""],[19274,19274,"","সে ঈশ্বরের কাছে প্রার্থনা করলো... ...আর সে তার পাপের কাছে আত্মসমর্পণ করবে, আমি মাথা টেনে ফেলব.","‏ ‏قَالَ ‏ ‏وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّهُ ‏ ‏مَعَ الْغُلَامِ ‏ ‏عَقِيقَتُهُ ‏ ‏تُذْبَحُ عَنْهُ يَوْمَ سَابِعِهِ وَيُسَمَّى وَيُحْلَقُ رَأْسُهُ ‏","","",""],[19275,19275,"","আমরা ঐ বধিরদের কথা বলেছিলাম. বাবার জের কথা যখন তিনি কথা বলেছিলেন তখন ঈশ্বর তাকে ওয়াইনে পাঠিয়ে দেবেন.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ يَعْنِي أَبَا زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ ‏ ‏ذَكَرَ ‏ ‏أَنَّ الَّذِي ‏ ‏يُحَدِّثُ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَذِنَ فِي ‏ ‏النَّبِيذِ ‏ ‏بَعْدَ مَا نَهَى عَنْهُ ‏ ‏مُنْذِرٌ أَبُو حَسَّانَ ‏ ‏ذَكَرَهُ عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏وَكَانَ ‏ ‏يَقُولُ ‏ ‏مَنْ خَالَفَ ‏ ‏الْحَجَّاجَ ‏ ‏فَقَدْ خَالَفَ ‏","","",""],[19276,19276,"","আমরা একটা রাজধানী সম্বন্ধে কথা বলেছিলাম, যেখানে আমরা ভালো ছেলে হওয়ার কথা বলেছিলাম । তারপর ফিরে এসে তারা তাকে মেরে ফেলবে, সে বলেছে, গর্ভপাতের কারণে তুমি বিষ থেকে বের হতে পারতে না।","‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَاصِمٍ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ بْنِ الشِّخِّيرِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏بَيْنَا نَحْنُ عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ ‏ ‏أُتِيَ ‏ ‏بِقَصْعَةٍ ‏ ‏فِيهَا ‏ ‏ثَرِيدٌ ‏ ‏قَالَ فَأَكَلَ وَأَكَلَ الْقَوْمُ فَلَمْ يَزَلْ يَتَدَاوَلُونَهَا إِلَى قَرِيبٍ مِنْ الظُّهْرِ يَأْكُلُ كُلُّ قَوْمٍ ثُمَّ يَقُومُونَ وَيَجِيءُ قَوْمٌ فَيَتَعَاقَبُوهُ قَالَ فَقَالَ لَهُ رَجُلٌ هَلْ كَانَتْ تُمَدُّ بِطَعَامٍ قَالَ أَمَّا مِنْ الْأَرْضِ فَلَا إِلَّا أَنْ تَكُونَ كَانَتْ تُمَدُّ مِنْ السَّمَاءِ ‏","","",""],[19277,19277,"","আমরা তার সাথে বন্ধুত্বের কথা বলেছি।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏قَالَ جَاءَهُ رَجُلٌ فَقَالَ إِنَّ عَبْدًا لَهُ ‏ ‏أَبَقَ ‏ ‏وَإِنَّهُ نَذَرَ إِنْ قَدَرَ عَلَيْهِ أَنْ يَقْطَعَ يَدَهُ ‏ ‏فَقَالَ ‏ ‏الْحَسَنُ ‏ ‏حَدَّثَنَا ‏ ‏سَمُرَةُ ‏ ‏قَالَ ‏ ‏قَلَّمَا خَطَبَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُطْبَةً إِلَّا ‏ ‏أَمَرَ فِيهَا ‏ ‏بِالصَّدَقَةِ ‏ ‏وَنَهَى فِيهَا عَنْ ‏ ‏الْمُثْلَةِ ‏","","",""],[19278,19278,"","আমরা কথা বলেছি কিভাবে আমাদের চেষ্টা করা উচিত এবং এটাকে ভগবানের চেয়ে ভাল করে বদলে বদলে ফেলা উচিত। সে আত্মসমর্পণ করেছে তাকে খুন করেছে আর তার গলা ধরে এনেছে।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَنْبَأَنَا ‏ ‏شُعْبَةُ ‏ ‏وَغَيْرُهُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ عَبْدَهُ قَتَلْنَاهُ وَمَنْ ‏ ‏جَدَعَهُ ‏ ‏جَدَعْنَاهُ ‏","","",""],[19279,19279,"","আমরা একটি স্বপ্নের কথা বলেছিলাম তিনি যে দুই জায়গা সম্পর্কে বলেছেন তার বাবার ফোন দিয়ে তিনি বলেন তিনি আপনার অনুগ্রহ ছেড়ে দিতে হবে আমার পানিকে তিনি সাঁতার কাটতে হবে এবং আমরা কাজ করব এবং যান.","‏ ‏حَدَّثَنَا ‏ ‏مُعْتَمِرُ بْنُ سُلَيْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الرُّكَيْنَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ تُسَمِّيَ رَقِيقَكَ أَرْبَعَةَ أَسْمَاءٍ أَفْلَحَ وَيَسَارًا وَنَافِعًا وَرَبَاحًا ‏","","",""],[19280,19280,"","আমরা চেষ্টা করছি আমাদের সময় জয় করার জন্য, ঈশ্বরের কাছে প্রার্থনা করার চেয়ে ভালো সময় পাওয়া। সে বলেছিল, তার সব মূল্যবান কলম তার মাথায় রাখা হয়েছে এবং বিষ প্রয়োগ করা হয়।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ غُلَامٍ ‏ ‏رَهِينٌ ‏ ‏بِعَقِيقَتِهِ ‏ ‏تُذْبَحُ عَنْهُ يَوْمَ السَّابِعِ وَيُحْلَقُ رَأْسُهُ وَيُسَمَّى ‏","","",""],[19281,19281,"","বাবার উপর হার্টের আঘাত নিয়ে আমরা কথা বলেছিলাম একবার বলেছিলেন যে সে কখনো পারবে না, আমি তোমাকে এই সাদা ছেলেটি দিয়ে দেবো যাতে সে তাকে জিততে পারে আর তারপর তাকে বাঁচাতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكُمْ بِهَذِهِ الْبَيَاضِ فَلْيَلْبَسْهَا أَحْيَاؤُكُمْ وَكَفِّنُوا فِيهَا مَوْتَاكُمْ فَإِنَّهَا مِنْ خَيْرِ ثِيَابِكُمْ ‏","","",""],[19282,19282,"","আমরা বাবার এই উদারতার স্বপ্নের কথা বলেছিলাম, ঈশ্বর বলতে হবে, ওয়ালিয়ান যদি তাদের থেকে ভালো হয়, তাহলে তাকে বিক্রি করতে হবে।","‏ ‏حَدَّثَنَا ‏ ‏عَمْرُو بْنُ الْهَيْثَمِ أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَنْكَحَ الْوَلِيَّانِ فَهِيَ لِلْأَوَّلِ مِنْهُمَا وَإِذَا بَاعَ بَيْعًا مِنْ رَجُلَيْنِ فَهُوَ لِلْأَوَّلِ مِنْهُمَا ‏","","",""],[19283,19283,"","ব্যাজ রাখার চেয়ে ভালো কথা বলে আমরা অনেক খুশি হয়েছি। ঈশ্বর ভাল কিছু দিয়েছেন যা কখনও ব্যর্থ হবে না।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا ‏","","",""],[19284,19284,"","আমরা একটা সুখী সিদ্ধান্ত নিয়ে কথা বলেছি, তাকে তার কাছে প্রার্থনা করতে হবে, জীবিত এবং ভুলে যাওয়া।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الْحَيَوَانِ بِالْحَيَوَانِ ‏ ‏نَسِيئَةً ‏","","",""],[19285,19285,"","আমি আমার বাবাকে বলেছিলাম যে, তার বাবা একটা কুত্তার বাচ্চা ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو مَالِكٍ الْأَشْجَعِيُّ ‏ ‏عَنْ ‏ ‏نُعَيْمِ بْنِ أَبِي هِنْدٍ ‏ ‏عَنِ ‏ ‏ابْنِ سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ قَتَلَ فَلَهُ ‏ ‏السَّلَبُ ‏","","",""],[19286,19286,"","আমরা বাবা-এর সাথে লড়াই করার চেষ্টা করে কথা বলেছি। ঈশ্বরের কাছে প্রার্থনা করলে তারা খারাপকে মেরে ফেলবে। সূর্য ছোট।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَجَّاجُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْتُلُوا شُيُوخَ الْمُشْرِكِينَ ‏ ‏وَاسْتَحْيُوا ‏ ‏شَرْخَهُمْ ‏ ‏قَالَ ‏ ‏عَبْد اللَّهِ ‏ ‏سَأَلْتُ أَبِي عَنْ تَفْسِيرِ هَذَا ‏ ‏الْحَدِيثِ اقْتُلُوا شُيُوخَ الْمُشْرِكِينَ ‏ ‏قَالَ ‏ ‏يَقُولُ الشَّيْخُ لَا يَكَادُ أَنْ يُسْلِمَ وَالشَّابُّ أَيْ يُسْلِمُ كَأَنَّهُ أَقْرَبُ إِلَى الْإِسْلَامِ مِنْ الشَّيْخِ قَالَ الشَّرْخُ الشَّبَابُ ‏","","",""],[19287,19287,"","ঈশ্বর তার জন্য প্রার্থনা করেছেন এবং তিনি সেই ব্যক্তি যে - ব্যক্তি বা তার স্বাদ অথবা স্বাদ নিয়ে চুরি করে থাকলে তাকে আত্মসমর্পণ করবেন । ক্রেতারা দামের বিনিময়ে বিক্রি করেছে।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو مُعَاوِيَةَ ‏ ‏عَنْ ‏ ‏حَجَّاجٍ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ عُبَيْدِ بْنِ زَيْدِ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا سُرِقَ مِنْ الرَّجُلِ مَتَاعٌ أَوْ ضَاعَ لَهُ مَتَاعٌ فَوَجَدَهُ بِيَدِ رَجُلٍ بِعَيْنِهِ فَهُوَ أَحَقُّ بِهِ وَيَرْجِعُ الْمُشْتَرِي عَلَى الْبَائِعِ بِالثَّمَنِ ‏","","",""],[19288,19288,"","আমরা অনেক খুশি হয়েছি যখন সে ঈশ্বরকে বলেছিল, সে বাড়ির প্রতিবেশীকে পাঠিয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَارُ الدَّارِ أَحَقُّ بِالدَّارِ ‏","","",""],[19289,19289,"","আমরা আমার বাবার সাথে শোকের সময় কথা বলেছি, তিনি ঈশ্বরের ইচ্ছার কথা জিজ্ঞেস করেছেন এবং তার সম্মান ও সম্মান খুঁজে বের করে তার টাকা উদ্ধার করে তার টাকা উদ্ধার করবেন। লেখা","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ أَبِي زَكَرِيَّا ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَنْ ‏ ‏مُوسَى بْنِ السَّائِبِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْمَرْءُ أَحَقُّ بِعَيْنِ مَالِهِ حَيْثُ عَرَفَهُ وَيَتَّبِعُ الْبَيْعُ بَيْعَهُ ‏","","",""],[19290,19290,"","ঈশ্বর এই পাপের জন্য আপনাকে শাস্তি দেননি আর তাই এত ভদ্র হওয়া ঠিক নয় ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ إِبْرَاهِيمَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ اللَّهِ بْنُ سَوَادَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَغُرَّنَّكُمْ أَذَانُ ‏ ‏بِلَالٍ ‏ ‏وَلَا هَذَا الْبَيَاضُ لِعَمُودِ الصُّبْحِ حَتَّى ‏ ‏يَسْتَطِيرَ ‏","","",""],[19291,19291,"","আমরা অনেক সময় নিয়ে কথা বলেছি যখন আমরা আগুনে একটা দাম জিতেছিলাম। লর্ড প্রার্থনা করলেন তার জন্য এবং আত্মসমর্পণ করলেন আপনার নামে, লর্ড লর্ডের নামে। ( ১ করি.","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏مَعْبَدُ بْنُ خَالِدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي الْجُمُعَةِ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَهَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ‏","","",""],[19292,19292,"","আমরা অনেক খুশি যে আমাদের সাহায্য করতে চলে যাবে, বুঝতে যে আমরা কত কঠিন। আমি ঈশ্বরের কাছে প্রার্থনা করছি, সে বলবে সিগারেটের ছায়া সে আর দুনিয়ার চেহারা নিয়ে গেছে, তার বিচারালয় আর নাচতে সে মানুষকে বলতে পারে যে ঈশ্বর মারা যাবেন, হয়ত তার পাপের আর কোন কথা না। তার পর থেকে তার আর না, তাদের একটা ছেলেকে এই চমকের স্টান্ট থেকে স্বপ্ন দেখতে হবে আর রাজার মাংসের গৌরবের সাথে আবদ্ধ থাকবে। সময়.","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏وَعَبْدُ الْوَهَّابِ ‏ ‏أَخْبَرَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏إِنَّ ‏ ‏الدَّجَّالَ ‏ ‏خَارِجٌ وَهُوَ أَعْوَرُ عَيْنِ الشِّمَالِ عَلَيْهَا ‏ ‏ظَفَرَةٌ ‏ ‏غَلِيظَةٌ وَإِنَّهُ ‏ ‏يُبْرِئُ ‏ ‏الْأَكْمَهَ ‏ ‏وَالْأَبْرَصَ ‏ ‏وَيُحْيِي الْمَوْتَى وَيَقُولُ لِلنَّاسِ أَنَا رَبُّكُمْ فَمَنْ قَالَ أَنْتَ رَبِّي فَقَدْ ‏ ‏فُتِنَ ‏ ‏وَمَنْ قَالَ ‏ ‏رَبِّيَ اللَّهُ حَتَّى يَمُوتَ فَقَدْ ‏ ‏عُصِمَ ‏ ‏مِنْ ‏ ‏فِتْنَتِهِ ‏ ‏وَلَا ‏ ‏فِتْنَةَ ‏ ‏بَعْدَهُ عَلَيْهِ وَلَا عَذَابَ فَيَلْبَثُ فِي الْأَرْضِ مَا شَاءَ اللَّهُ ثُمَّ يَجِيءُ ‏ ‏عِيسَى ابْنُ مَرْيَمَ ‏ ‏عَلَيْهِمَا السَّلَام ‏ ‏مِنْ قِبَلِ الْمَغْرِبِ مُصَدِّقًا ‏ ‏بِمُحَمَّدٍ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَى مِلَّتِهِ فَيَقْتُلُ ‏ ‏الدَّجَّالَ ‏ ‏ثُمَّ إِنَّمَا هُوَ قِيَامُ السَّاعَةِ ‏","","",""],[19293,19293,"","তিনি চাঁদকে তার কাছে এক পুরস্কার হিসেবে দিয়েছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْعُمْرَى ‏ ‏جَائِزَةٌ لِأَهْلِهَا ‏","","",""],[19294,19294,"","আমরা বৃষ্টির দিনে বেঁচে থাকার চেয়ে আরও ভাল এক জীবন থাকার বিষয়ে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏كَانَ يَوْمًا مَطِيرًا فَأَمَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنَادِيَهُ فَنَادَى أَنَّ ‏ ‏الصَّلَاةَ فِي ‏ ‏الرِّحَالِ ‏","","",""],[19295,19295,"","আমরা বাবার প্রতি ২ বছরের সুখী পুত্রদের কথা বলেছি, আর আমার বাবা কাপুরুষ। লর্ড অফ গড-এর কাছে প্রার্থনা করল। এতদুর চলে গেল যে সে পরিষ্কার আর অট্টহাসি পরিষ্কার করবে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏حَدَّثَنِي ‏ ‏حَبِيبُ بْنُ أَبِي ثَابِتٍ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ أَبِي شَبِيبٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَسُوا الثِّيَابَ الْبِيضَ فَإِنَّهَا أَطْهَرُ وَأَطْيَبُ وَكَفِّنُوا فِيهَا مَوْتَاكُمْ ‏","","",""],[19296,19296,"","আমরা প্রভুর মঙ্গলের ব্যাপারে খুশি হয়েছি, সে বলল, চোরদের প্রার্থনার জন্য প্রার্থনা করা হয়।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏سَعِيدٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الصَّلَاةُ الْوُسْطَى صَلَاةُ الْعَصْرِ ‏","","",""],[19297,19297,"","আমরা বাবার এক সুখী ছেলের কথা বলেছি, তাকে তার হাত ছেড়ে দিতে হবে, যতক্ষণ সে এটা করতে ভুলে যায় যে সে এটা ভুলে যায় না। অন্তর্ভুক্ত মান","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏عَلَى الْيَدِ مَا أَخَذَتْ حَتَّى تُؤَدِّيَهُ ‏ ‏ثُمَّ نَسِيَ ‏ ‏الْحَسَنُ ‏ ‏قَالَ لَا يَضْمَنُ ‏","","",""],[19298,19298,"","আমরা বাবার ছেলের কথা বলেছিলাম একটা ছেলের সাথে একটা ছেলের মৃত্যুর পর... ...তার মৃত্যু আর তাকে হত্যা করতে হবে, ঈশ্বরের আছে আর সে তোমার কথা শুনবে দুই হাত দিয়ে সকালটা দুই হাত দিয়ে অপরাধের দরজার সামনে চলে যেতে পারে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ يَعْنِي ابْنَ أَبِي خَالِدٍ ‏ ‏عَنْ ‏ ‏عَامِرٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الْفَجْرَ ذَاتَ يَوْمٍ فَقَالَ هَاهُنَا مِنْ بَنِي فُلَانٍ أَحَدٌ مَرَّتَيْنِ فَقَالَ رَجُلٌ هُوَ ذَا فَكَأَنِّي أَسْمَعُ صَوْتَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ صَاحِبَكُمْ قَدْ حُبِسَ عَلَى بَابِ الْجَنَّةِ بِدَيْنٍ كَانَ عَلَيْهِ ‏","","",""],[19299,19299,"","আমরা একটা ঠান্ডা ছেলের কথা বলেছি... ...যে বলেছে সে তোমাকে কখনও এত জাদু করা থেকে বিরত করবে না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو هِلَالٍ ‏ ‏عَنْ ‏ ‏سَوَادَةَ بْنِ حَنْظَلَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَمْنَعَنَّكُمْ مِنْ سُحُورِكُمْ أَذَانُ ‏ ‏بِلَالٍ ‏ ‏وَلَا الْفَجْرُ ‏ ‏الْمُسْتَطِيلُ ‏ ‏وَلَكِنْ الْفَجْرُ ‏ ‏الْمُسْتَطِيرُ ‏ ‏فِي الْأُفُقِ ‏","","",""],[19300,19300,"","আমরা অনেকবার তার বিরুদ্ধে কথা বলেছি। আল্লাহ তাঁর জন্য প্রার্থনা করেছেন এবং তিনি সেই জনতাকে উদ্ধার করেছেন যারা আমার হৃদয়ের সাথে এক ডজনের মধ্যে বিশ্বাস করতে ব্যর্থ হয়েছে। ডজন ডলার।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏قُدَامَةَ بْنِ وَبَرَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ فَاتَتْهُ الْجُمُعَةُ فَلْيَتَصَدَّقْ بِدِينَارٍ أَوْ بِنِصْفِ دِينَارٍ ‏","","",""],[19301,19301,"","আমরা দুই বছর ধরে আমার ভালবাসার জন্য ভাল আচরণের জন্য আমার সর্বোচ্চ ব্যবহার করে এসেছি। তিনি প্রার্থনা করেছিলেন আমরা ঈশ্বরের কাছে প্রার্থনা করব এবং কথা বলি তার নীরবতার কথা।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ الْعَبْديِّ ‏ ‏عَنْ ‏ ‏ثَعْلَبَةَ بْنِ عَبَّادٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي كُسُوفٍ فَلَمْ نَسْمَعْ لَهُ صَوْتًا ‏","","",""],[19302,19302,"","আমরা ফিরে আসার কথা বলেছি আর আমি খাবার নিয়ে ফিরে যাচ্ছি। তুমি প্রতারণার কথা বলছ.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏وَأَبُو نُعَيْمٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْعِيدَيْنِ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَهَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ‏","","",""],[19303,19303,"","আমরা হারুনের চেয়ে অনেক ভাল ছিলাম... ...আমাদের প্রভু তার কাছে প্রার্থনা করেছিলেন আর তিনি আমার মায়ের মৃত্যুর দুই বছর আগে আমার মাকে সমর্পণ করবেন।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حُسَيْنٌ يَعْنِي الْمُعَلِّمَ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى عَلَى أُمِّ فُلَانٍ مَاتَتْ فِي نِفَاسِهَا فَقَامَ وَسَطَهَا ‏","","",""],[19304,19304,"","আমাদের বিচার করার চেয়ে অনেক বেশি বলা হয়েছে, আমার বাবা কতটা ভালো। ঈশ্বর তাকে জিজ্ঞেস করেছেন, আর কে আমাকে দেখছে সে আমাকে কথা বলছে আর তাকে মিথ্যা বলে মনে করছে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏الْحَكَمِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ رَوَى عَنِّي حَدِيثًا وَهُوَ يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبِينَ ‏","","",""],[19305,19305,"","আমরা একটা হাত দিয়ে বাপ্তিস্ম নিয়েছি, আমরা একটা কাপুরুষের মত অশুভ লক্ষণের পূজা করার চেষ্টা করছি। ঈশ্বর তাঁর কাছে প্রার্থনা করেছেন এবং আপনার নামে তিনি এই র‍্যালিতে আত্মসমর্পণ করবেন, যাতে তিনি কথা বলতে পারেন নির্বোধ.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ عُبَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏زَيْدٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقْرَأُ فِي الْجُمُعَةِ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَهَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ‏","","",""],[19306,19306,"","আমরা শুনেছি একটা দেয়াল চালাতে যেখানে বাবা আমার আগুন লেগে যেতে পারে, একটা উপায় খুঁজে বের করতে। সে প্রার্থনা করছিল, ঈশ্বর যেন সাহায্য করে। যদি সে জাদুবিদ্যার জাদু করতো, তাহলে দেখ সে রাতে কেউ তার গল্প তাকে কিছু বলতে দেখবে। মনে হয় আজ রাতে আমরা এমন একজনকে দেখলাম যে আমরা কিছু বলিনি কিন্তু আমি একজনকে দেখেছি। যে এটা নিয়েছে, আমার একজন নির্দেশ দিয়েছে যে তার মাথা তার হাতের কাছে দেখেছে, তারপর সে বের হয়ে আসবে, আর সে তার এপার্টমেন্টে প্রবেশ করবে। তারপর, যে তার মৃত্যুর জন্য উজ্জ্বল হয়ে উঠেছে সে এটা ফিরে পেতে চায় যখন সে বলেছিল সে ব্যর্থ হয়েছে, স্কার্টটা খুবই সরু এবং খুবই সরু আমি এটা করব, আর আমি এটা একজন মানুষ আর খারাপ লোকের সাথে বন্ধ করব, সে চলে যাবে, তাই সে আমাকে যা বলেছে তা সে বলেছে, সে তার কাছে গেছে। আমি যা বলেছি তা ভুল, কিন্তু আমি তো চলে যাবো। গাছের মধ্যে দিয়ে যাব, গাছের মধ্যে দিয়ে যাব, গাছের নিচে যাবে, গাছের নিচে যাবে, গাছের নিচে যাবে, গাছে যাবে, তারপর শহরে যাবে, আর ওই জায়গায় যাবে। শহর, তুমি যা কিছু হতে চাও তার থেকেও একটু বেশী বিপদজনক হতে পারে, সে হচ্ছে এমন এক যুবক যে কিনা হৃদয়ে হামলা করে গাছের উপর দাড়িয়ে আছে। যখন আমি পড়ে গেল তখন থেকে আমি দেখলাম, এটা একটা লোক মিথ্যা কথা বলছে যেন সে গর্তে ভর করে। তুমি এটা নিয়ে কথা বলো অথবা ঐ লোকটা যে লোকের কাছে পাঠানো হয়েছে তাকে নিয়ে। কিন্তু সে দিন পর্যন্ত তার কাজ করেছে, সে আর কখনো সময় দেখেনি। নদীগুলো ঈশ্বরের খেসার বা বড় বড় যার সাথে গাছের উৎপত্তি হয়েছে, আর রাজকুমারের আছে রাজকুমারের যারা আগুন দেখেছে তারা আপনার টাকা খেয়ে ফেলেছে, আগুন শেষ হয়ে গেছে । আমি তোমাকে দেখতে চাই, আমি আমার প্রেসিডেন্টকে জিতেছি, তাই যেভাবে আমাকে মেরে ফেলা যায় আর তোমার বাড়ি বলে আমি এটা বলতে চাই। তুমি এটা করতে না পারলেও না।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَبَا رَجَاءٍ الْعُطَارِدِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا صَلَّى صَلَاةَ ‏ ‏الْغَدَاةِ ‏ ‏أَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ هَلْ رَأَى أَحَدٌ مِنْكُمْ اللَّيْلَةَ رُؤْيَا فَإِنْ كَانَ أَحَدٌ رَأَى تِلْكَ اللَّيْلَةَ رُؤْيَا قَصَّهَا عَلَيْهِ فَيَقُولُ فِيهَا مَا شَاءَ اللَّهُ أَنْ يَقُولَ فَسَأَلَنَا يَوْمًا فَقَالَ هَلْ رَأَى أَحَدٌ مِنْكُمْ اللَّيْلَةَ رُؤْيَا قَالَ فَقُلْنَا لَا قَالَ لَكِنْ أَنَا ‏ ‏رَأَيْتُ رَجُلَيْنِ أَتَيَانِي فَأَخَذَا بِيَدَيَّ فَأَخْرَجَانِي إِلَى أَرْضٍ فَضَاءٍ أَوْ أَرْضٍ مُسْتَوِيَةٍ فَمَرَّا بِي عَلَى رَجُلٍ وَرَجُلٌ قَائِمٌ عَلَى رَأْسِهِ بِيَدِهِ ‏ ‏كَلُّوبٌ ‏ ‏مِنْ حَدِيدٍ فَيُدْخِلُهُ فِي ‏ ‏شِدْقِهِ ‏ ‏فَيَشُقُّهُ حَتَّى يَبْلُغَ قَفَاهُ ثُمَّ يُخْرِجُهُ فَيُدْخِلُهُ فِي ‏ ‏شِقِّهِ ‏ ‏الْآخَرِ ‏ ‏وَيَلْتَئِمُ ‏ ‏هَذَا ‏ ‏الشِّقُّ ‏ ‏فَهُوَ يَفْعَلُ ذَلِكَ بِهِ قُلْتُ مَا هَذَا قَالَا انْطَلِقْ فَانْطَلَقْتُ مَعَهُمَا فَإِذَا رَجُلٌ مُسْتَلْقٍ عَلَى قَفَاهُ وَرَجُلٌ قَائِمٌ بِيَدِهِ ‏ ‏فِهْرٌ ‏ ‏أَوْ صَخْرَةٌ ‏ ‏فَيَشْدَخُ ‏ ‏بِهَا رَأْسَهُ ‏ ‏فَيَتَدَهْدَى ‏ ‏الْحَجَرُ فَإِذَا ذَهَبَ لِيَأْخُذَهُ عَادَ رَأْسُهُ كَمَا كَانَ فَيَصْنَعُ مِثْلَ ذَلِكَ فَقُلْتُ مَا هَذَا قَالَا ‏ ‏لِيَ انْطَلِقْ فَانْطَلَقْتُ مَعَهُمَا فَإِذَا بَيْتٌ مَبْنِيٌّ عَلَى بِنَاءِ ‏ ‏التَّنُّورِ ‏ ‏وَأَعْلَاهُ ضَيِّقٌ وَأَسْفَلُهُ وَاسِعٌ يُوقَدُ تَحْتَهُ نَارٌ فَإِذَا فِيهِ رِجَالٌ وَنِسَاءٌ عُرَاةٌ فَإِذَا أُوقِدَتْ ارْتَفَعُوا حَتَّى يَكَادُوا أَنْ يَخْرُجُوا فَإِذَا خَمَدَتْ رَجَعُوا فِيهَا فَقُلْتُ مَا هَذَا قَالَا ‏ ‏لِيَ انْطَلِقْ فَانْطَلَقْتُ فَإِذَا نَهَرٌ مِنْ دَمٍ فِيهِ رَجُلٌ وَعَلَى شَطِّ النَّهَرِ رَجُلٌ بَيْنَ يَدَيْهِ حِجَارَةٌ فَيُقْبِلُ الرَّجُلُ الَّذِي فِي النَّهَرِ فَإِذَا ‏ ‏دَنَا ‏ ‏لِيَخْرُجَ رَمَى فِي ‏ ‏فِيهِ حَجَرًا فَرَجَعَ إِلَى مَكَانِهِ فَهُوَ يَفْعَلُ ذَلِكَ بِهِ فَقُلْتُ مَا هَذَا فَقَالَا انْطَلِقْ فَانْطَلَقْتُ فَإِذَا رَوْضَةٌ خَضْرَاءُ فَإِذَا فِيهَا شَجَرَةٌ عَظِيمَةٌ وَإِذَا شَيْخٌ فِي أَصْلِهَا حَوْلَهُ صِبْيَانٌ وَإِذَا رَجُلٌ قَرِيبٌ مِنْهُ بَيْنَ يَدَيْهِ نَارٌ فَهُوَ ‏ ‏يَحْشُشُهَا ‏ ‏وَيُوقِدُهَا فَصَعِدَا بِي فِي الشَّجَرَةِ فَأَدْخَلَانِي دَارًا لَمْ أَرَ دَارًا قَطُّ أَحْسَنَ مِنْهَا فَإِذَا فِيهَا رِجَالٌ شُيُوخٌ وَشَبَابٌ وَفِيهَا نِسَاءٌ وَصِبْيَانٌ فَأَخْرَجَانِي مِنْهَا فَصَعِدَا بِي فِي الشَّجَرَةِ فَأَدْخَلَانِي دَارًا هِيَ أَحْسَنُ وَأَفْضَلُ مِنْهَا فِيهَا شُيُوخٌ وَشَبَابٌ فَقُلْتُ لَهُمَا إِنَّكُمَا قَدْ طَوَّفْتُمَانِي مُنْذُ اللَّيْلَةِ فَأَخْبِرَانِي عَمَّا رَأَيْتُ فَقَالَا نَعَمْ أَمَّا الرَّجُلُ الْأَوَّلُ الَّذِي رَأَيْتَ فَإِنَّهُ رَجُلٌ كَذَّابٌ يَكْذِبُ الْكَذِبَةَ فَتُحْمَلُ عَنْهُ فِي الْآفَاقِ فَهُوَ يُصْنَعُ بِهِ مَا رَأَيْتَ إِلَى يَوْمِ الْقِيَامَةِ ثُمَّ يَصْنَعُ اللَّهُ تَبَارَكَ وَتَعَالَى بِهِ مَا شَاءَ وَأَمَّا الرَّجُلُ الَّذِي رَأَيْتَ مُسْتَلْقِيًا فَرَجُلٌ آتَاهُ اللَّهُ تَبَارَكَ وَتَعَالَى الْقُرْآنَ ‏ ‏فَنَامَ عَنْهُ بِاللَّيْلِ وَلَمْ يَعْمَلْ بِمَا فِيهِ بِالنَّهَارِ فَهُوَ يُفْعَلُ بِهِ مَا رَأَيْتَ إِلَى يَوْمِ الْقِيَامَةِ وَأَمَّا الَّذِي رَأَيْتَ فِي ‏ ‏التَّنُّورِ ‏ ‏فَهُمْ الزُّنَاةُ وَأَمَّا الَّذِي رَأَيْتَ فِي النَّهَرِ فَذَاكَ آكِلُ الرِّبَا وَأَمَّا الشَّيْخُ الَّذِي رَأَيْتَ فِي أَصْلِ الشَّجَرَةِ فَذَاكَ ‏ ‏إِبْرَاهِيمُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَأَمَّا الصِّبْيَانُ الَّذِي رَأَيْتَ فَأَوْلَادُ النَّاسِ وَأَمَّا الرَّجُلُ الَّذِي رَأَيْتَ يُوقِدُ النَّارَ ‏ ‏وَيَحْشُشُهَا ‏ ‏فَذَاكَ ‏ ‏مَالِكٌ ‏ ‏خَازِنُ ‏ ‏النَّارِ وَتِلْكَ النَّارُ وَأَمَّا الدَّارُ الَّتِي دَخَلْتَ أَوَّلًا فَدَارُ عَامَّةِ الْمُؤْمِنِينَ وَأَمَّا الدَّارُ الْأُخْرَى فَدَارُ الشُّهَدَاءِ وَأَنَا ‏ ‏جِبْرِيلُ ‏ ‏وَهَذَا ‏ ‏مِيكَائِيلُ ‏ ‏ثُمَّ قَالَا ‏ ‏لِيَ ارْفَعْ رَأْسَكَ فَرَفَعْتُ رَأْسِي فَإِذَا هِيَ كَهَيْئَةِ السَّحَابِ فَقَالَا لِي وَتِلْكَ دَارُكَ فَقُلْتُ لَهُمَا دَعَانِي أَدْخُلْ دَارِي فَقَالَا لِي إِنَّهُ قَدْ بَقِيَ لَكَ عَمَلٌ لَمْ تَسْتَكْمِلْهُ فَلَوْ اسْتَكْمَلْتَهُ دَخَلْتَ دَارَكَ ‏","","",""],[19307,19307,"","আমাদের বলা হয়েছে হামাদের বিষ কিন্তু আল্লাহ তা করেন আর শান্তি আছে। তৃতীয়টি কথা বলতে হবে। তোমার মৃত্যুর পর একবার তার পাপকে হত্যা করো.","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَتْ لَهُ سَكْتَتَانِ سَكْتَةٌ حِينَ يَفْتَتِحُ الصَّلَاةَ وَسَكْتَةٌ إِذَا فَرَغَ مِنْ السُّورَةِ الثَّانِيَةِ قَبْلَ أَنْ يَرْكَعَ ‏ ‏فَذُكِرَ ذَلِكَ ‏ ‏لِعِمْرَانَ بْنِ حُصَيْنٍ ‏ ‏فَقَالَ كَذَبَ ‏ ‏سَمُرَةُ ‏ ‏فَكَتَبَ فِي ذَلِكَ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏إِلَى ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏فَقَالَ ‏ ‏صَدَقَ ‏ ‏سَمُرَةُ ‏","","",""],[19308,19308,"","জয় পাওয়ার চেয়ে ভালো কথা বলেছি, করুণা মুক্ত।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏رَفَعَهُ قَالَ ‏ ‏مَنْ مَلَكَ ذَا ‏ ‏رَحِمٍ ‏ ‏فَهُوَ حُرٌّ ‏","","",""],[19309,19309,"","বাবা বুঝতে পেরেছিলেন যে, আমার বাবা যে - ই হোন না কেন, তিনি হলেন সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি । সে-ই হবে সেই ব্যক্তি যে হবে হবে, সে হবে একজন যে হবে হবে সেই হবে, সে হবে একজন যে হবে। সে-ই হবে সেই লোক যে তাকে হতে দেবে, যে হবে সে হবে সবচেয়ে বেশি সম্ভবত সেই ব্যক্তি । সে-ই হবে সেই ব্যক্তি যে হবে সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি, যিনি হবেন সেই ব্যক্তি, যিনি হবেন একজন হবে সেই ব্যক্তি । যে হবে সেই ব্যক্তি যে আমার বাবার রাজা হতে পেরে সবচেয়ে খুশি হবে, সে আমার বাবার রাজা হতে পারবে। আমার বাবার রাজা হওয়ার জন্য আমার বাবার রাজা হওয়া উচিত, আমার বাবার রাজা হওয়া. তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং তিনি যা চান তাই করলেন. আগুন থেকে বের হয়ে আসা এক ভ্রমণ।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَبِي عَدِيٍّ ‏ ‏عَنْ ‏ ‏دَاوُدَ يَعْنِي ابْنَ أَبِي هِنْدٍ ‏ ‏عَنْ ‏ ‏أَبِي قَزَعَةَ ‏ ‏عَنِ ‏ ‏الْأَسْقَعِ بْنِ الْأَسْلَعِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا تَحْتَ الْكَعْبَيْنِ مِنْ ‏ ‏الْإِزَارِ ‏ ‏فِي النَّارِ ‏","","",""],[19310,19310,"","আমরা সময়ের মাংস মুক্ত করার চেষ্টা করেছি বিষ শোনার একটি উপায় খুঁজে পাওয়ার জন্য। ভাববাদী প্রার্থনা করেছিলেন এবং সূর্য উদিত হতে এবং তাকে আত্মসমর্পণ করতে বলা হবে যখন সূর্য উদিত হয় এবং যখন এটা পড়ে গেল, আমার সুলতানের শিং।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏سِمَاكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُهَلَّبَ ‏ ‏يَخْطُبُ ‏ ‏قَالَ قَالَ ‏ ‏سَمُرَةُ بْنُ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا تُصَلُّوا حِينَ تَطْلُعُ الشَّمْسُ وَلَا حِينَ تَسْقُطُ فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ الشَّيْطَانِ وَتَغْرُبُ بَيْنَ قَرْنَيْ الشَّيْطَانِ ‏","","",""],[19311,19311,"","ঈশ্বর তাঁর কাছে প্রার্থনা করেছিলেন এবং ভ্রমণকারীদের প্রার্থনা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏أَصَابَتْنَا السَّمَاءُ وَنَحْنُ مَعَ نَبِيِّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنَادَى ‏ ‏الصَّلَاةُ فِي ‏ ‏الرِّحَالِ ‏","","",""],[19312,19312,"","আমরা আবেগে বাপ্তাইজিত হয়েছি... ...একজন ভালবাসার প্রতি অন্ধ হয়ে... ...আর প্রভু তার কাছে প্রার্থনা করেছেন... ...যে সুন্দর মানুষদের সাথে.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ أَبِي الْحُرِّ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏إِنَّ مِنْ خَيْرِ مَا تَدَاوَى بِهِ النَّاسُ ‏ ‏الْحَجْمَ ‏","","",""],[19313,19313,"","আমরা আমার বাবা বড় কথা বলেছিলাম যে তিনি আমাদের ব্যাপারে একটু বেশি কথা বলতে চাচ্ছেন. একজন সৈনিক বলেছিলেন আমি লর্ডের প্রার্থনা করছি তার জন্য আমি একটা মহিষ করতে যাচ্ছি, যে তার নাক ভেঙ্গে ফেলতে চায়। যেখানে লোকেরা কথা বলে, সেই রাজা দুটো ঘোড়ার চোখ খুলেন, যে - ঘোড়ার সঙ্গে আমার বাবা কথা বলার জন্য স্বাধীন ।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ أَبِي بُكَيْرٍ ‏ ‏قَالَ ‏ ‏زُهَيْرُ بْنُ مُعَاوِيَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏حَدَّثَنِي ‏ ‏حُصَيْنُ بْنُ أَبِي الْحُرِّ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَدَعَا ‏ ‏حَجَّامًا ‏ ‏فَأَمَرَهُ أَنْ ‏ ‏يَحْجُمَهُ ‏ ‏فَأَخْرَجَ مَحَاجِمَ لَهُ مِنْ ‏ ‏قُرُونٍ ‏ ‏فَأَلْزَمَهُ إِيَّاهُ فَشَرَطَهُ بِطَرَفِ ‏ ‏شَفْرَةٍ ‏ ‏فَصَبَّ الدَّمَ فِي إِنَاءٍ عِنْدَهُ فَدَخَلَ عَلَيْهِ رَجُلٌ مِنْ ‏ ‏بَنِي فَزَارَةَ ‏ ‏فَقَالَ مَا هَذَا يَا رَسُولَ اللَّهِ عَلَامَ تُمَكِّنُ هَذَا مِنْ جِلْدِكَ يَقْطَعُهُ قَالَ فَسَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ هَذَا ‏ ‏الْحَجْمُ ‏ ‏قَالَ وَمَا ‏ ‏الْحَجْمُ ‏ ‏قَالَ هُوَ مِنْ خَيْرِ مَا تَدَاوَى بِهِ النَّاسُ ‏ ‏حَدَّثَنَا ‏ ‏الْأَشْيَبُ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ أَبِي الْحُرِّ الْعَنْبَرِيِّ ‏ ‏فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏زُهَيْرٍ ‏","","",""],[19314,19314,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং জিজ্ঞেস করেছিলেন যে, তিনি কার হাতে মারা গিয়েছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ يَوْمَ الْجُمُعَةِ فَبِهَا ‏ ‏وَنِعْمَتْ وَمَنْ اغْتَسَلَ فَهُوَ أَفْضَلُ ‏","","",""],[19315,19315,"","আমরা আমার প্রতিভা আর বাবা দুদুদের সব থেকে ভালো কিছু নিয়ে কথা বলেছি। সে ঈশ্বরের কাছে প্রার্থনা করতে বলেছে, সে আল্লাহকে অভিশাপ দিবে না আর তাকে দূরে নিয়ে আসবে।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَلَاعَنُوا بِلَعْنَةِ اللَّهِ وَلَا بِغَضَبِهِ وَلَا بِالنَّارِ ‏","","",""],[19316,19316,"","আমরা একটা স্বপ্নের কথা বলেছি, যেখানে থাকার স্বপ্ন আছে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ إِسْحَاقَ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ عَمْرِو بْنِ عَطَاءٍ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏عَلِيُّ بْنُ حُسَيْنٍ ‏ ‏اسْمُ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏عَبْدُ اللَّهِ ‏ ‏وَاسْمُ ‏ ‏مِيكَائِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏عُبَيْدُ اللَّهِ ‏","","",""],[19317,19317,"","তাকে তার সঙ্গে উজ্জ্বলদের বিষ প্রয়োগ করে উদ্ধার করতে হবে এবং আমাদের জিজ্ঞেস করতে হবে আমি কাকে ডুবে যাচ্ছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ تَوَضَّأَ يَوْمَ الْجُمُعَةِ فَبِهَا ‏ ‏وَنِعْمَتْ وَمَنْ اغْتَسَلَ فَالْغُسْلُ أَفْضَلُ ‏","","",""],[19318,19318,"","সেই দর্শন তাকে তার পাপের কথা উল্লেখ করার জন্য একটা দাগ দিয়ে আটকে রাখা অবস্থায় এতিম হয়ে গিয়েছিল । বলেছি, আমাদের একটা ছেলে আছে, যাকে আগুনে ফেলে দিতে হবে আর আমাদের ঈশ্বরের দোহাই ধরে রাখতে হবে। সূর্য তার মৃত্যুর দৃশ্যের মাঝে তিন বা তিন বার বাঁধা। তার নিজের মৃত্যুর জন্য, এই সন্ধ্যায় ঈশ্বরের দয়ায় ঈশ্বরের দয়া প্রদর্শিত হয়। তাই তিনি একজন বারাসকে বলেছিলেন তিনি ঈশ্বরের কাছে প্রার্থনা করতে রাজি হয়েছেন তিনি তার হৃদয়ের অবস্থা থেকেই আমরা প্রার্থনা করতে পারি। আমরা তাকে অনেক কিছু করেছি। আমরা জানি, আমরা আমাদের জীবনের জন্য। আমরা তাকে ধন্যবাদ জানাতে চাই। আমরা তাকে আমরা যদি আমাদের জীবনের উদ্দেশ্য নিয়ে কথা বলি, আমরা তাকে বলি, আমরা তাকে বলি, আমরা আমাদের জীবনের জন্য, আমরা তাকে ধন্যবাদ জানাতে পারি। আর আমরা আমাদের জীবনের জন্য ধন্যবাদ জানাতে চাই। আর আমরা আমাদের জীবনের জন্য একটি উদ্দেশ্য নিয়ে কথা বলি, আমরা তাকে ধন্যবাদ দিতে চাই। (হাসি) তার কথা কখনো শুনে নি, আর তাই সে অনেক দূর চলে গেছে। আর এই কারণেই তুমি সূর্য হারিয়েছো। দ্বিতীয় কোয়ার্টারে তার জিহ্বা বলে, ঈশ্বর তাকে ধরে নিয়ে গেছেন এবং বললেন, আমি তোমাকে ছোট হতে শেখাবো। আমি তোমাকে কখনোই বলবো না আমি গান গাইতে যাচ্ছি আর আমি কিভাবে ছিলাম। আমি বলেছিলাম যে, একজন মানুষকে হত্যা করলে তুমি মারা যেতে পারো। আমি যখন অন্ধকার অবস্থায় থেকে তুমি যা - কিছু করছ, তার জন্য ঈশ্বর আমাকে দেখতে এসেছেন । আরো একে অপরকে বের করে, তারা আমার ভাইয়ের ভাই হতে যাচ্ছে, কিন্তু এটা আমার পরিতৃপ্তির দেয়াল এবং এটা যখন আসে তখন এটা ঈশ্বরের কাজ করে। বিশ্বাস করো তাকে আর তার নিজের রক্তের রক্ষক হিসেবে কাজ না করাই ভালো। ভাল খবর হচ্ছে, খারাপ খবর হচ্ছে আর এটা সব দেখা যাবে। আর সে আদালতে নিরাপদ থাকবে। পবিত্র মুসা, দেয়াল মৃত হয়, অথবা বলে যে ভাল কিছু হবে। তিনি বললেন, \"আমি তাকে খুন করবো না,\" অথবা তিনি বলেছেন, এটা আপনার সেরাটা হবে। আমি নিশ্চিত করছি, আমি নিশ্চিত যে, আমি নিশ্চিত যে, আমি এই দেয়ালটি পেয়ে যাব। অথবা যদি কোন কিছুর উপর ভিত্তি করে বলি, তাহলে আমি তাকে হত্যা করতে চাই। এবং আমি যদি বলি, আমি বলি, আমি বলি, \"আমি তাকে হত্যা করবো\" এবং আমি জানি, \"আমি তাকে বলি, \"আমি\" ঈশ্বরের কাছে আপনি তার কথা চিন্তা করছিলেন আর তিনি তাকে বিয়ে করতে যাচ্ছেন ।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ قَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏ثَعْلَبَةُ بْنُ عَبَّادٍ الْعَبْدِيُّ ‏ ‏مِنْ أَهْلِ ‏ ‏الْبَصْرَةِ ‏ ‏قَالَ ‏ ‏شَهِدْتُ يَوْمًا خُطْبَةً ‏ ‏لِسَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏فَذَكَرَ فِي خُطْبَتِهِ حَدِيثًا ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بَيْنَا أَنَا وَغُلَامٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏نَرْمِي فِي غَرَضَيْنِ لَنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَتَّى إِذَا كَانَتْ الشَّمْسُ قِيدَ رُمْحَيْنِ أَوْ ثَلَاثَةٍ فِي عَيْنِ النَّاظِرِ اسْوَدَّتْ حَتَّى ‏ ‏آضَتْ ‏ ‏كَأَنَّهَا تَنُّومَةٌ قَالَ فَقَالَ أَحَدُنَا لِصَاحِبِهِ انْطَلِقْ بِنَا إِلَى الْمَسْجِدِ فَوَاللَّهِ لَيُحْدِثَنَّ شَأْنُ هَذِهِ الشَّمْسِ لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي أُمَّتِهِ حَدَثًا قَالَ فَدَفَعْنَا إِلَى الْمَسْجِدِ فَإِذَا هُوَ بَارِزٌ قَالَ وَوَافَقْنَا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حِينَ خَرَجَ إِلَى النَّاسِ فَاسْتَقْدَمَ فَقَامَ بِنَا كَأَطْوَلِ مَا قَامَ بِنَا فِي صَلَاةٍ قَطُّ لَا نَسْمَعُ لَهُ صَوْتًا ثُمَّ رَكَعَ كَأَطْوَلِ مَا رَكَعَ بِنَا فِي صَلَاةٍ قَطُّ لَا نَسْمَعُ لَهُ صَوْتًا ثُمَّ فَعَلَ فِي الرَّكْعَةِ الثَّانِيَةِ مِثْلَ ذَلِكَ فَوَافَقَ تَجَلِّيَ الشَّمْسِ جُلُوسُهُ فِي الرَّكْعَةِ الثَّانِيَةِ ‏ ‏قَالَ ‏ ‏زُهَيْرٌ ‏ ‏حَسِبْتُهُ قَالَ فَسَلَّمَ ‏ ‏فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ وَشَهِدَ أَنَّهُ عَبْدُ اللَّهِ وَرَسُولُهُ ثُمَّ قَالَ أَيُّهَا النَّاسُ ‏ ‏أَنْشُدُكُمْ بِاللَّهِ إِنْ كُنْتُمْ تَعْلَمُونَ أَنِّي قَصَّرْتُ عَنْ شَيْءٍ مِنْ تَبْلِيغِ رِسَالَاتِ رَبِّي عَزَّ وَجَلَّ لَمَا أَخْبَرْتُمُونِي ذَاكَ فَبَلَّغْتُ رِسَالَاتِ رَبِّي كَمَا يَنْبَغِي لَهَا أَنْ تُبَلَّغَ وَإِنْ كُنْتُمْ تَعْلَمُونَ أَنِّي بَلَّغْتُ رِسَالَاتِ رَبِّي لَمَا أَخْبَرْتُمُونِي ذَاكَ قَالَ فَقَامَ رِجَالٌ فَقَالُوا نَشْهَدُ أَنَّكَ قَدْ بَلَّغْتَ رِسَالَاتِ رَبِّكَ وَنَصَحْتَ لِأُمَّتِكَ وَقَضَيْتَ الَّذِي عَلَيْكَ ثُمَّ سَكَتُوا ثُمَّ قَالَ أَمَّا بَعْدُ فَإِنَّ رِجَالًا يَزْعُمُونَ أَنَّ كُسُوفَ هَذِهِ الشَّمْسِ وَكُسُوفَ هَذَا الْقَمَرِ وَزَوَالَ هَذِهِ النُّجُومِ عَنْ مَطَالِعِهَا لِمَوْتِ رِجَالٍ عُظَمَاءَ مِنْ أَهْلِ الْأَرْضِ وَإِنَّهُمْ قَدْ كَذَبُوا وَلَكِنَّهَا آيَاتٌ مِنْ آيَاتِ اللَّهِ تَبَارَكَ وَتَعَالَى يَعْتَبِرُ بِهَا عِبَادُهُ فَيَنْظُرُ مَنْ يُحْدِثُ لَهُ مِنْهُمْ تَوْبَةً وَايْمُ اللَّهِ لَقَدْ رَأَيْتُ مُنْذُ قُمْتُ أُصَلِّي مَا أَنْتُمْ لَاقُونَ فِي أَمْرِ دُنْيَاكُمْ وَآخِرَتِكُمْ وَإِنَّهُ وَاللَّهِ لَا تَقُومُ السَّاعَةُ حَتَّى يَخْرُجَ ثَلَاثُونَ كَذَّابًا آخِرُهُمْ الْأَعْوَرُ ‏ ‏الدَّجَّالُ ‏ ‏مَمْسُوحُ الْعَيْنِ الْيُسْرَى كَأَنَّهَا عَيْنُ ‏ ‏أَبِي يَحْيَى ‏ ‏لِشَيْخٍ حِينَئِذٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏بَيْنَهُ وَبَيْنَ حُجْرَةِ ‏ ‏عَائِشَةَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهَا ‏ ‏وَإِنَّهَا مَتَى يَخْرُجُ ‏ ‏أَوْ قَالَ مَتَى مَا يَخْرُجُ ‏ ‏فَإِنَّهُ سَوْفَ يَزْعُمُ أَنَّهُ اللَّهُ فَمَنْ آمَنَ بِهِ وَصَدَّقَهُ وَاتَّبَعَهُ لَمْ يَنْفَعْهُ صَالِحٌ مِنْ عَمَلِهِ سَلَفَ وَمَنْ كَفَرَ بِهِ وَكَذَّبَهُ لَمْ يُعَاقَبْ بِشَيْءٍ مِنْ عَمَلِهِ ‏ ‏وَقَالَ ‏ ‏حَسَنٌ الْأَشْيَبُ ‏ ‏بِسَيِّئٍ مِنْ عَمَلِهِ سَلَفَ ‏ ‏وَإِنَّهُ سَيَظْهَرُ ‏ ‏أَوْ قَالَ سَوْفَ يَظْهَرُ ‏ ‏عَلَى الْأَرْضِ كُلِّهَا إِلَّا ‏ ‏الْحَرَمَ ‏ ‏وَبَيْتَ الْمَقْدِسِ ‏ ‏وَإِنَّهُ يَحْصُرُ الْمُؤْمِنِينَ فِي ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏فَيُزَلْزَلُونَ زِلْزَالًا شَدِيدًا ثُمَّ يُهْلِكُهُ اللَّهُ تَبَارَكَ وَتَعَالَى وَجُنُودَهُ حَتَّى إِنَّ ‏ ‏جِذْمَ ‏ ‏الْحَائِطِ ‏ ‏أَوْ قَالَ ‏ ‏أَصْلَ ‏ ‏الْحَائِطِ ‏ ‏وَقَالَ ‏ ‏حَسَنٌ الْأَشْيَبُ ‏ ‏وَأَصْلَ الشَّجَرَةِ ‏ ‏لَيُنَادِي ‏ ‏أَوْ قَالَ يَقُولُ ‏ ‏يَا مُؤْمِنُ ‏ ‏أَوْ قَالَ يَا مُسْلِمُ ‏ ‏هَذَا يَهُودِيٌّ ‏ ‏أَوْ قَالَ هَذَا كَافِرٌ ‏ ‏تَعَالَ فَاقْتُلْهُ قَالَ وَلَنْ يَكُونَ ذَلِكَ كَذَلِكَ حَتَّى تَرَوْا أُمُورًا يَتَفَاقَمُ شَأْنُهَا فِي أَنْفُسِكُمْ ‏ ‏وَتَسَاءَلُونَ بَيْنَكُمْ هَلْ كَانَ نَبِيُّكُمْ ذَكَرَ لَكُمْ مِنْهَا ذِكْرًا وَحَتَّى تَزُولَ جِبَالٌ عَلَى مَرَاتِبِهَا ثُمَّ عَلَى أَثَرِ ذَلِكَ الْقَبْضُ ‏ ‏قَالَ ‏ ‏ثُمَّ شَهِدْتُ خُطْبَةً ‏ ‏لِسَمُرَةَ ‏ ‏ذَكَرَ فِيهَا هَذَا الْحَدِيثَ فَمَا قَدَّمَ كَلِمَةً وَلَا أَخَّرَهَا عَنْ مَوْضِعِهَا ‏","","",""],[19319,19319,"","আমরা হামাদের ব্যাপারে কথা বলেছি কিন্তু আমরা ঈশ্বরকে ছাড়া আরো ভালো কিছুর জন্য লড়াই করতে বলেছিলাম। তিনি আত্মসমর্পণ করেছেন এবং বলেন যে মুক্তির জন্য আমাদের বানরগুলো বিক্রি করা উচিত।","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَزَلَ الْقُرْآنُ عَلَى سَبْعَةِ أَحْرُفٍ ‏","","",""],[19320,19320,"","আমরা এক সুখী কুত্তার বাচ্চা, যে আমাকে এক সেকেন্ডের জন্য বাঁচাতে চেষ্টা করছে। আমি সেই ভাববাদী যে তার জন্য প্রার্থনা করে, আর সূর্য হত্যার আগ পর্যন্ত একটা লাইন তৈরি করে দিয়েছে। অথবা পরে।","‏ ‏حَدَّثَنَا ‏ ‏عُمَرُ بْنُ سَعْدٍ أَبُو دَاوُدَ الْحَفَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏ثَعْلَبَةَ بْنِ عَبَّادٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَطَبَ ‏ ‏حِينَ انْكَسَفَتْ الشَّمْسُ فَقَالَ أَمَّا بَعْدُ ‏","","",""],[19321,19321,"","আমরা একটা বাপ্তিস্ম নিয়ে আমাদের কথা বলেছিলাম ভাল বলতে সে বলবে ঈশ্বর তোমাকে পূর্ণ করবে আর বলে দেবে যে সিংহ তোমাদের হত্যা করবে না আর খেয়ে ফেলবে তোমার পাপ.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُوشِكُونَ أَنْ يَمْلَأَ اللَّهُ تَبَارَكَ وَتَعَالَى أَيْدِيَكُمْ مِنْ ‏ ‏الْعُجْمِ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً مِنْ ‏ ‏الْأَعَاجِمِ ‏ ‏ثُمَّ ‏ ‏يَكُونُوا ‏ ‏أُسْدًا لَا يَفِرُّونَ يَقْتُلُونَ مُقَاتِلَتَكُمْ وَيَأْكُلُونَ فَيْئَكُمْ ‏","","",""],[19322,19322,"","আমরা আমার সর্বোচ্চ মর্যাদা নিয়ে কথা বলেছি... ...দয়ার রাজত্বের ব্যাপারে, ঈশ্বর আমাদের মঙ্গলের কথা কখনো পূরণ করবেন না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏عَنْ ‏ ‏هِشَامٍ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا ‏","","",""],[19323,19323,"","আমি যে - প্রতিবেশীদের বিশ্বাস করি বা সিঁড়িতে বিশ্বাস করি, তাদের তিনি রক্ষা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْجَارُ أَحَقُّ بِالْجِوَارِ أَوْ بِالدَّارِ ‏","","",""],[19324,19324,"","আমরা নিশ্চিত হয়েছি যে আমরা কিছু কথা জয় করতে যথেষ্ট করেছি, ঈশ্বরের কাছে প্রার্থনা করতে হবে তাকে আমাদের বাড়িতে ভাল মানুষের চেহারা নিতে হবে এবং আমরা তাকে দেখতে পাব।","‏ ‏حَدَّثَنَا ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏بَقِيَّةُ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ ثَعْلَبَةَ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏أَمَرَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ نَتَّخِذَ الْمَسَاجِدَ فِي دِيَارِنَا وَأَمَرَنَا أَنْ نُنَظِّفَهَا ‏","","",""],[19325,19325,"","আমরা দুইটা বই দিয়ে তৈরি হওয়ার চেষ্টা করেছি, যা আমার ভালবাসার জন্য আমার ভালোবাসাকে বাড়িয়ে দিয়েছে। যাওয়ার জন্য প্রস্তুত হও।","‏ ‏حَدَّثَنَا ‏ ‏الْفَضْلُ بْنُ دُكَيْنٍ ‏ ‏حَدَّثَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏وَحَبِيبٍ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ أَبِي شَبِيبٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَسُوا الثِّيَابَ الْبَيَاضَ فَإِنَّهَا أَطْهَرُ وَأَطْيَبُ وَكَفِّنُوا فِيهَا مَوْتَاكُمْ ‏","","",""],[19326,19326,"","আমরা তোমাকে বলছি কিভাবে চুদতে হয় তা বলার চেয়ে ভালো কথা বলেছি। আমরা ঈশ্বরের সঙ্গে কথা বলেছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ بْنُ يَحْيَى ‏ ‏مِنْ أَهْلِ ‏ ‏مَرْوٍ ‏ ‏وَعَلِيُّ بْنُ إِسْحَاقَ ‏ ‏قَالَا أَخْبَرَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏وِقَاءَ بْنِ إِيَاسٍ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ رَبِيعَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَامَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَخَطَبَ ‏ ‏فَنَهَى عَنْ ‏ ‏الدُّبَّاءِ ‏ ‏وَالْمُزَفَّتِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَحْمَدُ بْنُ جَمِيلٍ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ الْمُبَارَكِ ‏ ‏مِثْلَهُ ‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ هِشَامٍ ‏ ‏وَعَبْدُ الْوَاحِدِ بْنُ غِيَاثٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏ثَعْلَبَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[19327,19327,"","আমরা উড়ন্ত লোকের ছেলের কথা বলেছিলাম আমরা আমার ছেলের চেয়ে ভালো কথা বলেছি, সে বলত তার সব প্রিয় ছবি তার জন্য আর মৃত্যুর জন্য অত্যাচার করা হচ্ছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏كُلُّ غُلَامٍ ‏ ‏مُرْتَهَنٌ ‏ ‏بِعَقِيقَتِهِ ‏ ‏تُذْبَحُ عَنْهُ يَوْمَ سَابِعِهِ ‏ ‏وَيُمَاطُ ‏ ‏عَنْهُ الْأَذَى وَيُسَمَّى ‏","","",""],[19328,19328,"","আমরা কথা বলেছিলাম যে এটা কি ভালো ছিল যে ভবিষ্যদ্বাণী প্রভুর সাথে হয়েছে, ভালোটা কখনো ভেঙ্গে যায়নি এবং তাদের প্রত্যেককে নিয়ে নি পাপ নিয়ে খেলার জন্য একজন যাজককে জেতার জন্য সে আমাদের প্রভুর ইচ্ছা গণনা করতে শিখিয়েছে, সে ছিল দৃষ্টির দৃষ্টিতে, আর সে বলেছে সে হারিয়ে যাওয়ার আগেই যখন সে তার বাসায় হাল ছেড়ে দিয়েছিল, তখন সে আমাকে যেতে দিত না। জয়ের মেঘ এবং একটা কথা বলার আগ পর্যন্তও হারিয়ে যায়। কথা দাও, সে একটা দুর্বল জিনিস সম্পর্কে জেনেছে আর একজনের খেলা আবার হতে যাচ্ছে। লর্ডের কাছে প্রার্থনা করছে তার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا وَيَأْخُذْ كُلُّ وَاحِدٍ مِنْهُمَا مَا رَضِيَ مِنْ الْبَيْعِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ قَيْسٍ ‏ ‏عَنْ ‏ ‏ثَعْلَبَةَ بْنِ عَبَّادٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَامَ يَوْمًا خَطِيبًا فَذَكَرَ فِي خُطْبَتِهِ حَدِيثًا قَالَ بَيْنَمَا أَنَا وَغُلَامٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏نَرْمِي فِي غَرَضَيْنِ لَنَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ طَلَعَتْ الشَّمْسُ فَكَانَتْ فِي عَيْنِ النَّاظِرِ قَيْدَ رُمْحَيْنِ ‏ ‏وَسَاقَ الْحَدِيثَ ‏ ‏ثُمَّ قَالَ أَمَّا بَعْدُ وَقَالَ ثُمَّ قَبَضَ أَطْرَافَ أَصَابِعِهِ ثُمَّ قَالَ ‏ ‏أَوْ قَامَ أَنَا أَشُكُّ مَرَّةً أُخْرَى وَقَدْ حَفِظْتُ مَا قَالَ ‏ ‏قَالَ فَمَا قَدَّمَ كَلِمَةً عَنْ مَنْزِلَتِهَا وَلَا أَخَّرَ شَيْئًا ‏ ‏وَقَدْ ‏ ‏قَالَ ‏ ‏أَبُو عَوَانَةَ ‏ ‏بَيْنَمَا أَنَا وَغُلَامٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَقَالَ أَيْضًا فَاسْوَدَّتْ حَتَّى ‏ ‏آضَتْ ‏ ‏وَقَدْ ‏ ‏قَالَ ‏ ‏أَبُو عَوَانَةَ ‏ ‏زُوُولٌ ‏ ‏وَلَكِنَّهَا ‏ ‏زُوُولٌ أَصَوْبُ ‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ هِشَامٌ ‏ ‏وَعَبْدُ الْوَاحِدِ بْنِ غِيَاثٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏ثَعْلَبَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[19329,19329,"","আমার ছেলের ভালো নাম নিয়ে বাবার সাথে কথা বলেছিলাম, সে আছে আর সে ঐ ওক গাছের সাথে কাজ করেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَلِيٌّ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏التَّبَتُّلِ ‏","","",""],[19330,19330,"","আমরা আমাদের কথাবার্তাকে বড় হওয়ার চেয়ে ভালো করার সিদ্ধান্ত নিয়েছি। প্রত্যেক ব্যস্ত শপথ পরে পরে পরে গেছে। মাথা, আমরা একবার ঈশ্বর তার নিজের কথা তুলে ধরেছেন, সে তার কথাবার্তার মধ্যে আছে আর সে বলেছে যে সে নাকি খুব স্টিমর, সে ছিল রক্ত সম্বন্ধে বর্ণনা করতে গিয়ে সে শপথ নিতে বলছে, একটা পশম গ্রহণ করা হবে অথবা তার কামনার জন্য তাকে ছেড়ে দেওয়া হবে যতক্ষণ না সে তার দুর্দশার জন্য অনুরোধ করে, ততক্ষণ পর্যন্ত সে তাকে ছেড়ে চলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏كُلُّ غُلَامٍ ‏ ‏مُرْتَهَنٌ ‏ ‏بِعَقِيقَتِهِ ‏ ‏تُذْبَحُ يَوْمَ سَابِعِهِ وَيُحْلَقُ رَأْسُهُ ‏ ‏وَيُدَمَّى ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ الْعَطَّارُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ إِلَّا أَنَّهُ قَالَ ‏ ‏وَيُسَمَّى ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏فِي حَدِيثِهِ ‏ ‏وَرَاجَعْنَاهُ ‏ ‏وَيُدَمَّى ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏فَكَانَ ‏ ‏قَتَادَةُ ‏ ‏يَصِفُ الدَّمَ فَيَقُولُ إِذَا ذَبَحَ ‏ ‏الْعَقِيقَةَ ‏ ‏تُؤْخَذُ صُوفَةٌ فَتُسْتَقْبَلُ ‏ ‏أَوْدَاجُ ‏ ‏الذَّبِيحَةِ ثُمَّ تُوضَعُ عَلَى ‏ ‏يَافُوخِ ‏ ‏الصَّبِيِّ حَتَّى إِذَا سَالَ غُسِلَ رَأْسُهُ ثُمَّ حُلِقَ بَعْدُ ‏","","",""],[19331,19331,"","আমরা একটি মেয়ে বড় হওয়ার চেয়ে ভাল কথা বলেছিলাম.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَارُ الدَّارِ أَحَقُّ بِالدَّارِ مِنْ غَيْرِهِ ‏","","",""],[19332,19332,"","আমরা আমাদের বাবার স্বপ্নের হারুনের কথা বলেছি... ...আমার বাবার নাম কাপুরুষের মত বানিয়ে... ...আমাদের ভাগ্যকে... ...আর তাকে একটা ছায়ার ছায়া থেকে পিছু নিতে হবে. ছায়া যা পৃথিবীর সেরা হবে, সে কি তোমার কাছ থেকে যা বলছিল, সে কি তোমার চেয়ে বড় ছিল?","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ التَّيْمِيُّ ‏ ‏عَنْ ‏ ‏أَبِي الْعَلَاءِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ ‏ ‏بِقَصْعَةٍ ‏ ‏فِيهَا ‏ ‏ثَرِيدٌ ‏ ‏فَتَعَاقَبُوهَا إِلَى الظُّهْرِ مِنْ ‏ ‏غُدْوَةٍ ‏ ‏يَقُومُ نَاسٌ وَيَقْعُدُ آخَرُونَ قَالَ لَهُ رَجُلٌ هَلْ كَانَتْ تُمَدُّ قَالَ فَمِنْ أَيِّ شَيْءٍ تَعْجَبُ مَا كَانَتْ تُمَدُّ إِلَّا مِنْ هَاهُنَا وَأَشَارَ إِلَى السَّمَاءِ ‏","","",""],[19333,19333,"","আমরা প্রেম দেখানোর চেয়ে ভাল কথা বলেছি, আর কে তাকে খুন করেছে, আর কে তার মৃত্যুর জন্য তার অনুসন্ধান এনেছে। আমরা একবার কথা বলেছি যে আমি কার প্রাণ হারিয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَتَلَ عَبْدَهُ قَتَلْنَاهُ وَمَنْ ‏ ‏جَدَعَ ‏ ‏عَبْدَهُ ‏ ‏جَدَعْنَاهُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏عَنْ ‏ ‏أَبِي أُمَيَّةَ ‏ ‏شَيْخٍ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏وَمَنْ ‏ ‏أَخْصَى ‏ ‏عَبْدَهُ ‏ ‏خَصَيْنَاهُ ‏","","",""],[19334,19334,"","আমরা কথা বলেছি কিভাবে আমরা ওকে যুদ্ধ করতে বলেছিলাম। ভবিষ্যদ্বাণীর ভয়ে তার কাছে প্রার্থনা করে তাকে বাড়িতে থাকা প্রতিবেশীকে বলতে বলি।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏وَأَبُو دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏جَارُ الدَّارِ أَحَقُّ بِالدَّارِ ‏","","",""],[19335,19335,"","আমাদের তিন বছর ধরে বাবাকে ভালোবাসতে বলা হয়েছে আর আমার ভালবাসার জন্য বাবাকে বিচার করতে। একজন সৈনিক বলেছিল যে খোদা তার কাছে ভালো আর তারা তাকে যে কাপড় দিতে চায় তা সে ছেড়ে দেবে।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏الْمَسْعُودِيُّ ‏ ‏عَنْ ‏ ‏حَبِيبِ بْنِ أَبِي ثَابِتٍ ‏ ‏وَالْحَكَمِ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ أَبِي شَبِيبٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَسُوا الثِّيَابَ الْبِيضَ فَإِنَّهَا أَطْيَبُ وَأَطْهَرُ وَكَفِّنُوا فِيهَا مَوْتَاكُمْ ‏","","",""],[19336,19336,"","আমাদের প্রভু ক্ষমতা একে অপরের শাস্তি জয়ের জন্য, ঈশ্বর তার কাছে প্রার্থনা করেছেন এবং তার ভাইয়ের বন্দীর কাছ থেকে নিজের কাছে নিজেকে উৎসর্গ না করার জন্য।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏بَقِيَّةُ بْنُ الْوَلِيدِ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ ثَعْلَبَةَ ‏ ‏عَنْ ‏ ‏مَكْحُولٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا ‏ ‏يَتَعَاطَى أَحَدُكُمْ مِنْ أَسِيرِ أَخِيهِ فَيَقْتُلَهُ ‏","","",""],[19337,19337,"","আমরা চেষ্টা করেছি একটা ছেলেকে তার ঘাড়ের সাথে সাহায্য করার চেয়ে, একটা দাগ তার কাছে প্রার্থনা করে তার নিজের চোখে কে খুশি তা জানতে। মজা।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَجَّاجُ بْنُ أَرْطَأَةَ ‏ ‏عَنْ ‏ ‏سَعِيدِ بْنِ زَيْدِ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ ‏ ‏أَصَابَ ‏ ‏مَتَاعَهُ بِعَيْنِهِ فَهُوَ أَحَقُّ بِهِ وَيَتْبَعُ صَاحِبُهُ مَنْ اشْتَرَاهُ مِنْهُ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏مَرَّةً مَنْ وَجَدَ مَتَاعَهُ ‏","","",""],[19338,19338,"","আমরা একটি হারুন গঠন করার চেষ্টা করেছি, আমাদেরকে বল, শার্কবি কল করতে বলা হয়েছে। ঈশ্বর আপনাকে পাপ এবং মৃত্যুর জন্য প্রলুব্ধ না করতে বলেছেন। অথবা তার হাত এই ধরনের খারাপ এবং খারাপ জিনিস দিয়ে। তার ডান হাত বাড়িয়ে দাও।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَوَادَةَ الْقُشَيْرِيَّ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏لَا يَغُرَّنَّكُمْ أَذَانُ ‏ ‏بِلَالٍ ‏ ‏وَلَا هَذَا الْفَجْرُ ‏ ‏الْمُسْتَطِيلُ ‏ ‏وَلَكِنْ الْفَجْرُ ‏ ‏الْمُسْتَطِيرُ ‏ ‏وَأَوْمَأَ ‏ ‏بِيَدِهِ ‏ ‏هَكَذَا وَأَشَارَ ‏ ‏يَزِيدُ ‏ ‏بِيَدِهِ الْيُمْنَى ‏","","",""],[19339,19339,"","আমরা হামাদকে অনেক বেশি কথা বলেছি কিন্তু তাকে আরো ভালো কিছুর জন্য লড়াই করতে হবে। সে আত্মসমর্পণ করেছে এবং বলছে যে, তোমার রাজা এত দুর্বল যে সে একজন প্রাচীন দুঃখকর।","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَلَكَ ذَا ‏ ‏رَحِمٍ ‏ ‏مَحْرَمٍ فَهُوَ ‏ ‏عَتِيقٌ ‏","","",""],[19340,19340,"","আমি এক গ্রীষ্মে হেঁটে যাওয়ার শপথ করে বলেছিলাম এবং তিনি বলেছিলেন যে, তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং বলেছিলেন, তিনি আপনার জন্য ভাল করবেন ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْحَاقُ بْنُ يُوسُفَ ‏ ‏أَخْبَرَنَا ‏ ‏عَوْفٌ ‏ ‏وَهَوْذَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَوْفٌ ‏ ‏حَدَّثَنَا ‏ ‏شَيْخٌ ‏ ‏مِنْ ‏ ‏بَكْرِ بْنِ وَائِلٍ ‏ ‏فِي مَجْلِسِ ‏ ‏قَسَامَةٍ ‏ ‏قَالَ ‏ ‏دَخَلْتُ عَلَى ‏ ‏سَمُرَةَ ‏ ‏وَهُوَ ‏ ‏يَحْتَجِمُ ‏ ‏فَقَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّ مِنْ خَيْرِ دَوَائِكُمْ ‏ ‏الْحِجَامَةَ ‏","","",""],[19341,19341,"","আমরা কথা বলেছি, ঈশ্বরের দোহাই দিয়ে করাটা কতটা ভালো ছিল, যদি ওয়ালিয়ানরা প্রথমে তাদের কাছে বিক্রি করে দেয়।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو قَطَنٍ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا أَنْكَحَ ‏ ‏الْوَلِيَّانِ ‏ ‏فَهُوَ لِلْأَوَّلِ مِنْهُمَا وَإِذَا بَاعَ بَيْعًا مِنْ رَجُلَيْنِ فَهُوَ لِلْأَوَّلِ مِنْهُمَا ‏","","",""],[19342,19342,"","আমরা বাবার সাথে কথা বলেছিলাম একবার সে এটা করতে ভুলে গিয়েছিল. সে বলেছিল আগুন নেভানোর জন্য তারা আগুন নিয়ে যাচ্ছে যাদের তুমি গুলি করবে. তুমি এটাকে ফেলে দিবে.","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَبِي نَضْرَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْهُمْ مَنْ تَأْخُذُهُ النَّارُ إِلَى رُكْبَتَيْهِ وَمِنْهُمْ مَنْ تَأْخُذُهُ النَّارُ إِلَى ‏ ‏حُجْزَتِهِ ‏ ‏وَمِنْهُمْ مَنْ تَأْخُذُهُ النَّارُ إِلَى ‏ ‏تَرْقُوَتِهِ ‏","","",""],[19343,19343,"","আমরা ঈশ্বরের দ্বারা আমার বাবার মৃত্যু নিয়ে কথা বলেছি এবং তিনি সৎ শাসনের দ্বারা সুরক্ষিত ছিলেন। ঈশ্বর তাকে বলেছেন তিনি কখনো কোন নারী নন, আমার মুখোমুখি হয়েছেন এবং তার সাথে আছে। জন্ম, প্রথমে তাদের জন্য.","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ أَبِي عَبْدِ اللَّهِ ‏ ‏وَحَمَّادٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَيُّمَا امْرَأَةٍ زَوَّجَهَا ‏ ‏وَلِيَّانِ ‏ ‏فَهِيَ لِلْأَوَّلِ مِنْهُمَا وَأَيُّمَا رَجُلٍ بَاعَ بَيْعًا ‏ ‏مِنْ رَجُلَيْنِ فَهُوَ لِلْأَوَّلِ مِنْهُمَا ‏","","",""],[19344,19344,"","আমরা তোমার বাবার কথা বলেছিলাম যখন আমরা ঘুরেছি, দুজন সৈনিক আমাকে একবারের জন্য যে ভগবান আমাকে এটা করেছে, সে বলেছে, প্রভু, আপনি কিভাবে বলেছেন যে তিনি একজন ইম্যাম। দরজা ব্যবহার করা হয়। আমরা যা করেছি তা হচ্ছে মোশির চেয়ে ভাল। ঈশ্বর তাঁর শান্তি নিয়ে আসবেন এবং তিনি কথা বলার সময় তিনি তা করবেন।","‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ عَبْدِ الْمَلِكِ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏وَعَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏حُصَيْنٍ ‏ ‏رَجُلٍ مِنْ ‏ ‏بَنِي فَزَارَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏أَتَى نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْرَابِيٌّ وَهُوَ يَخْطُبُ فَقَطَعَ عَلَيْهِ خُطْبَتَهُ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏كَيْفَ تَقُولُ فِي الضَّبِّ قَالَ أُمَّةٌ مُسِخَتْ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَلَا أَدْرِي أَيَّ الدَّوَابِّ ‏ ‏مُسِخَتْ ‏ ‏حَدَّثَنَا ‏ ‏حَسَنُ بْنُ مُوسَى ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ قَبِيصَةَ الْفَزَارِيِّ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏سَأَلَ أَعْرَابِيٌّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[19345,19345,"","আমরা একজন মানুষের নাম হারানোর কথা বলেছি, ঈশ্বর তাকে চিনেছেন আর আমি বাতাসে তার ক্লাব পার করব.","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمَرَ مُنَادِيَهُ فَنَادَى فِي يَوْمٍ مَطِيرٍ الصَّلَاةُ فِي الرِّحَالِ ‏","","",""],[19346,19346,"","আমরা একটি ধূসর খুঁজে পেতে ঘটেছে কিন্তু আমরা একটি রাজাকে খুঁজে পেতে চেষ্টা করেছি, তিনি দেখেছি লর্ড প্রার্থনা তিনি আত্মসমর্পণ করেছেন এবং তিনি হতাশ হবেন। আর তোমাকে জড়িয়ে ধর... ...আমি যা দেখছি তা তার সাথে যা করো.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرُ بْنُ حَازِمٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏حُصَيْنِ بْنِ أَبِي الْحُرِّ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ ‏ ‏يَحْتَجِمُ ‏ ‏بِقَرْنٍ وَيُشْرَطُ بِطَرْفِ سِكِّينٍ فَدَخَلَ رَجُلٌ مِنْ ‏ ‏شَمْخَ ‏ ‏فَقَالَ لَهُ لِمَ تُمَكِّنُ ظَهْرَكَ أَوْ عُنُقَكَ مِنْ هَذَا يَفْعَلُ بِهَا مَا أَرَى فَقَالَ هَذَا ‏ ‏الْحَجْمُ ‏ ‏وَهُوَ مِنْ خَيْرِ مَا تَدَاوَيْتُمْ بِهِ ‏","","",""],[19347,19347,"","আমরা সেই বধিরদের কথা বলেছিলাম, বাবা, আমরা দুটো বিষয় নিয়ে কথা বলেছি, একটা ভালো ছেলে, সে আমাকে আমার কথা বলতে দেবে না, আমি আগে কখনো শুনেছি না। মেঘের শব্দ শুনে আমি শুনেছি যে ঈশ্বরের কাছে প্রার্থনা করছে, সে মারা গেছে এবং সে শুধু ঈশ্বরের কাছে প্রার্থনা করছিল যেন তিনি তার শান্তি কামনা করেন।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ بُرَيْدَةَ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏سَمُرَةَ بْنَ جُنْدُبٍ ‏ ‏يَقُولُ ‏ ‏إِنَّهُ لَيَمْنَعُنِي أَنْ أَتَكَلَّمَ بِكَثِيرٍ مِمَّا كُنْتُ أَسْمَعُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ هَاهُنَا مَنْ هُوَ أَكْثَرُ مِنِّي وَكُنْتُ لَيْلَتَئِذٍ غُلَامًا وَإِنِّي كُنْتُ لَأَحْفَظُ مَا أَسْمَعُ مِنْهُ صَلَّيْتُ وَرَاءَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَصَلَّى عَلَى ‏ ‏أُمِّ كَعْبٍ ‏ ‏مَاتَتْ وَهِيَ ‏ ‏نُفَسَاءُ ‏ ‏فَقَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِلصَّلَاةِ عَلَيْهَا وَسَطَهَا ‏","","",""],[19348,19348,"","আমরা একটি সুখী কামনার ছেলে কথা বলেছি যা আমরা বাধ্যতার বিচারের জন্য বেছে নিয়েছি। লর্ড প্রার্থনা করলেন এবং খুনীকে হত্যা করে হত্যা করেছেন। যে তাকে খুঁজে পেয়েছে, তাকে মারতে না বলার পর","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ قَتَلَ عَبْدَهُ قَتَلْنَاهُ وَمَنْ ‏ ‏جَدَعَهُ ‏ ‏جَدَعْنَاهُ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏ثُمَّ نَسِيَ ‏ ‏الْحَسَنُ ‏ ‏بَعْدُ فَقَالَ لَا يُقْتَلُ بِهِ ‏","","",""],[19349,19349,"","আমরা বাবার সাথে লড়াই করতে এবং অন্য আত্মা খুঁজতে পেরে খুশি হব, কারণ একবার একজন সৈনিক ঈশ্বরের কাছে প্রার্থনা করেছে যে, ঈশ্বরের কাছে তাঁর প্রয়োজন আছে। এটা তুলে ধরে যে, তার জীবনের সর্বোত্তম হবে বলে প্রতিজ্ঞা করা হয়েছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي عَرُوبَةَ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ ‏ ‏نَهَى عَنْ بَيْعِ الْحَيَوَانِ بِالْحَيَوَانِ ‏ ‏نَسِيئَةً ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏ثُمَّ نَسِيَ ‏ ‏الْحَسَنُ ‏ ‏فَقَالَ إِذَا اخْتَلَفَ الصِّنْفَانِ فَلَا بَأْسَ ‏","","",""],[19350,19350,"","আমরা আমাদের দেখা সবচেয়ে ভালো বিজ্ঞান নিয়ে কথা বলেছি, ঈশ্বর তাকে এমন একজন মহিলাকে উদ্ধার করতে বলেছেন যে তার আত্মাতে মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏حُسَيْنٌ الْمُعَلِّمُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ بُرَيْدَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏صَلَّى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى امْرَأَةٍ مَاتَتْ فِي نِفَاسِهَا فَقَامَ وَسَطَهَا ‏","","",""],[19351,19351,"","আমরা একটি কঠিন এবং সুখী সন্তানের সাথে শেষ হওয়া একটি ছেলের সাথে কথা বলেছি, যে সন্তান সন্তান আছে তার ছেলে আছে, যার একটা মেয়ে আছে। লর্ড তার জন্য প্রার্থনা করেছিলেন এবং সাধারণ ভাবে তাকে আত্মসমর্পণ করেছিলেন এবং আপনার প্রভুর নামে নয়, তাই না।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏مِسْعَرٌ ‏ ‏وَسُفْيَانُ ‏ ‏عَنْ ‏ ‏مَعْبَدِ بْنِ خَالِدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَقْرَأُ فِي الْعِيدَيْنِ ‏ ‏بِسَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى ‏ ‏وَهَلْ أَتَاكَ حَدِيثُ الْغَاشِيَةِ ‏","","",""],[19352,19352,"","বাবার ভালবাসার জন্য আমরা আমাদের জীবনের কিছু ভাল কাজ করেছি। একজন সৈনিক ঈশ্বরের কাছে প্রার্থনা করলেন তিনি মুক্তি পেয়েছেন এবং প্রভু তার দুর্দশার মুক্তি দিয়েছেন। দুঃখ এবং তোমার ইচ্ছার তীব্রতরতরতরতরতা।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَعَبْدُ الرَّحْمَنِ ‏ ‏عَنْ ‏ ‏سُفْيَانَ ‏ ‏عَنْ ‏ ‏حَبِيبٍ ‏ ‏عَنْ ‏ ‏مَيْمُونِ بْنِ أَبِي شَبِيبٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَسُوا الثِّيَابَ الْبِيضَ وَكَفِّنُوا فِيهَا مَوْتَاكُمْ فَإِنَّهَا أَطْهَرُ وَأَطْيَبُ ‏","","",""],[19353,19353,"","আমরা কয়েক বছর কাজ করেছি, কিন্তু আমাদের একটু সমস্যা আছে। একবার একজন সৈনিক তাকে জিজ্ঞাসা করে যে, ঈশ্বর তাকে আদেশ দিয়েছেন আর আশ্বস্ত করেছেন যে তিনি এরকম একটা কাজ করেছেন দয়া করে, একজন বিপথগামী ব্যক্তির ছেলের কোন দেশ বা অন্য কোন জিনিস জিজ্ঞাসা করার প্রয়োজন নেই।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏وَابْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ عُقْبَةَ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ هَذِهِ الْمَسَائِلَ كَدٌّ يَكُدُّ بِهَا أَحَدُكُمْ وَجْهَهُ ‏ ‏وَقَالَ ‏ ‏ابْنُ جَعْفَرٍ ‏ ‏كُدُوحٌ يُكْدَحُ بِهَا الرَّجُلُ إِلَّا أَنْ يَسْأَلَ ذَا سُلْطَانٍ أَوْ فِي أَمْرٍ لَا بُدَّ مِنْهُ ‏","","",""],[19354,19354,"","আমরা গত দুই বছর ধরে এমন কিছু কাজ করেছি, যা ঈশ্বর তাকে শিখিয়েছেন এবং তার নীরবতার কথা কখনো শোনেননি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنِ ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏ثَعْلَبَةَ بْنِ عَبَّادٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى فِي كُسُوفٍ فَلَمْ يُسْمَعْ لَهُ صَوْتٌ ‏","","",""],[19355,19355,"","আমরা বাবার ইচ্ছার খারাপ কথা বলেছি, ঈশ্বর তার কাছে প্রার্থনা করেছেন আর তার কাছে প্রার্থনা করেছেন তার সাথে কথা বলার সময় যে সে মিথ্যা বলে।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏قَالَ قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَحَدَّثَنَا ‏ ‏الْحَكَمُ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ حَدَّثَ بِحَدِيثٍ وَهُوَ يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبِينَ ‏","","",""],[19356,19356,"","আমরা একে অপরের সাথে কথা বলেছি... ...এই দাঙ্গার কথা যখন একবার জানতে পারলাম... ...আর এই ভবিষ্যদ্বাণীটা দেয়া হয়েছে, আমার ছেলের কাছ থেকে তিনি আরো এক বছর আগে এখানে বললেন যে তোমার বন্ধু অনেক খুশি হলাম।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَّى الْفَجْرَ فَقَالَ هَاهُنَا مِنْ بَنِي فُلَانٍ أَحَدٌ ثَلَاثًا فَقَالَ رَجُلٌ أَنَا قَالَ فَقَالَ ‏ ‏إِنَّ صَاحِبَكُمْ مَحْبُوسٌ عَنْ الْجَنَّةِ بِدَيْنِهِ ‏","","",""],[19357,19357,"","আমরা অনেক বছর ধরে বলেছি যে ঈশ্বর তা উদ্ধার করতে পারবেন এবং আমি পবিত্র পিতার নামে কথা বলতে পছন্দ করব... ...আমি পবিত্র পিতার ভাগ্যের দ্বারা ক্ষতিগ্রস্ত হব, ঈশ্বর. আমি বড় হয়ে গেছি।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏سُفْيَانُ ‏ ‏عَنْ ‏ ‏سَلَمَةَ بْنِ كُهَيْلٍ ‏ ‏عَنْ ‏ ‏هِلَالِ بْنِ يِسَافٍ ‏ ‏عَنْ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَفْضَلُ الْكَلَامِ بَعْدَ الْقُرْآنِ أَرْبَعٌ وَهِيَ مِنْ الْقُرْآنِ لَا يَضُرُّكَ بِأَيِّهِنَّ بَدَأْتَ سُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَلَا إِلَهَ إِلَّا اللَّهُ وَاللَّهُ أَكْبَرُ ‏","","",""],[19358,19358,"","আমরা আবেগ নিয়ে কথা বলেছি, আমার ছেলের বিচার থেকে আমাদের কথা বাদ দিয়ে, আমি বলেছিলাম আমার বাবার ছেলে ঈশ্বরের ভালুকের উপর পাস করতে। আমি বলতে চাই, ঈশ্বরের উপর আস্থা রেখে, আমার ছেলের মৃত্যুর পর... সে এটাকে মিথ্যা বলে, যে মিথ্যা বলে।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنِ ‏ ‏الْحَكَمِ ‏ ‏عَنِ ‏ ‏ابْنِ أَبِي لَيْلَى ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏الْحَكَمُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏ابْنَ أَبِي لَيْلَى ‏ ‏عَنْ ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ رَوَى عَنِّي حَدِيثًا وَهُوَ يَرَى أَنَّهُ كَذِبٌ فَهُوَ أَحَدُ الْكَاذِبِينَ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏أَيْضًا الْكَذَّابِينَ ‏","","",""],[19359,19359,"","আমরা একে অপরের সাথে কথা বলেছি, ঈশ্বরের কাছে প্রার্থনা করার চেয়ে বরং একটি ছেলে আরও ভালো কিছুর জন্য।","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ يَعْنِي ابْنَ إِبْرَاهِيمَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏مَا خَطَبَنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خُطْبَةً إِلَّا ‏ ‏نَهَانَا عَنْ ‏ ‏الْمُثْلَةِ ‏ ‏وَأَمَرَنَا ‏ ‏بِالصَّدَقَةِ ‏","","",""],[19360,19360,"","আমরা তর্কের কথা বলেছি, আমি শুনেছি আমার বাবা অন্ধকারতম আলোর কাছে এসে পৌঁছেছেন... ...তার জন্য লর্ড প্রার্থনা করেন আর আপনি আপনার জন্য প্রার্থনা করবেন না। সুর্যটা স্পর্শ করে যে সূর্যয় সে গ্রাস করবে, আমার বানর শয়তান","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَن ‏ ‏سِمَاكٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْمُهَلَّبَ بْنَ أَبِي صُفْرَةَ ‏ ‏قَالَ قَالَ ‏ ‏سَمُرَةُ بْنُ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تُصَلُّوا حِينَ تَطْلُعُ الشَّمْسُ فَإِنَّهَا تَطْلُعُ بَيْنَ قَرْنَيْ شَيْطَانٍ وَلَا حِينَ تَغِيبُ فَإِنَّهَا تَغِيبُ بَيْنَ قَرْنَيْ شَيْطَانٍ ‏","","",""],[19361,19361,"","আমরা কথা বলেছিলাম আমার প্রভুর অনুগ্রহ আর আত্মা যদি একবার ভালো হতো, সে বলল যে তোমার রাজা কে মুক্তির প্রতীক।","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ مَلَكَ ذَا ‏ ‏رَحِمٍ ‏ ‏مَحْرَمٍ فَهُوَ حُرٌّ ‏","","",""],[19362,19362,"","আমরা কথা বলেছি বাবা কিভাবে ভালো হয়েছে এটা সমাধান করতে। আমি সার্ভিসে যেতে পারবো আর আমি যদি তোমাকে নিয়ে ভাবি তাহলে গরু থেকে বের হয়ে যাবো। গোপন গোপনীয়","‏ ‏حَدَّثَنَا ‏ ‏أَبُو كَامِلٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَن ‏ ‏حُمَيْدٍ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَسْكُتُ سَكْتَتَيْنِ إِذَا دَخَلَ فِي الصَّلَاةِ وَإِذَا فَرَغَ مِنْ الْقِرَاءَةِ ‏ ‏فَأَنْكَرَ ذَلِكَ ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏فَكَتَبُوا إِلَى ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏يَسْأَلُونَهُ عَنْ ذَلِكَ فَكَتَبَ أَنْ ‏ ‏صَدَقَ ‏ ‏سَمُرَةُ ‏","","",""],[19363,19363,"","আমরা মহান সংবাদ দ্বারা বাপ্তাইজিত হয়েছি... ...তারপর আমরা বলছি যে সে বই আমাকে সাহায্য করবে... ...একটা দুঃখের ছেলে হবে, একবার সে বলল যে আমি আমার তলোয়ার ঈশ্বরের কাছে রেখে দেব ( ২ শমূ.","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَكْرٍ ‏ ‏أَخْبَرَنَا ‏ ‏عُثْمَانُ بْنُ سَعْدٍ ‏ ‏الْكَاتِبُ ‏ ‏قَالَ قَالَ ‏ ‏لِي ‏ ‏ابْنُ سِيرِينَ ‏ ‏صَنَعْتُ سَيْفِي عَلَى سَيْفِ ‏ ‏سَمُرَةَ ‏ ‏وَقَالَ ‏ ‏سَمُرَةُ ‏ ‏صَنَعْتُ سَيْفِي عَلَى سَيْفِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَكَانَ ‏ ‏حَنَفِيًّا ‏","","",""],[19364,19364,"","আমরা লড়াই করার জন্য লড়াই করার বিষয়ে কথা বলেছিলাম, জয়ী হওয়ার জন্য আরও ভালো কিছু করার জন্য ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏حَجَّاجُ بْنُ أَرْطَاةَ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اقْتُلُوا شُيُوخَ الْمُشْرِكِينَ وَاسْتَبْقُوا ‏ ‏شَرْخَهُمْ ‏","","",""],[19365,19365,"","আমরা ভাববাদীর কাছে প্রার্থনা করেছিলাম এবং তাকে একটা গুরুতর ভুল জায়গায় পাঠিয়ে দেওয়া হয়েছিল, যেটা তিনি আমার ছেলে ছিলেন, একটা শপথের মাধ্যমে বলেছিলেন । ঈশ্বর তাকে আদেশ দিয়েছেন আর তোমাকে আমার প্রথম স্থানে পেশ করবেন, তাদের একজন মানুষ মারা যাচ্ছে. শেষ বার আমি যে লোকটির কাছে গিয়েছিলাম, বাবার দুই চাঁদ একটা বর্বরের ছেলের কথা শুনতে পাবে। আমরা ঈশ্বর সম্পর্কে কথা বলেছিলাম বাবা আমার সাথে বড় হয়ে উঠছে। খারাপ ছেলে, সে আমার বাবার সাথে এমন হয়েছে... ...সে বলেছিল আমি একে অপরের কথা শুনি নি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏الثَّوْرِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنِ ‏ ‏الشَّعْبِيِّ ‏ ‏عَن ‏ ‏سَمْعَانَ بْنِ مُشَنَّجٍ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏كُنَّا مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي جَنَازَةٍ فَقَالَ أَهَاهُنَا مِنْ بَنِي فُلَانٍ أَحَدٌ قَالَهَا ثَلَاثًا فَقَامَ رَجُلٌ فَقَالَ لَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مَنَعَكَ فِي الْمَرَّتَيْنِ الْأُولَيَيْنِ أَنْ تَكُونَ أَجَبْتَنِي أَمَا إِنِّي لَمْ ‏ ‏أُنَوِّهْ ‏ ‏بِكَ إِلَّا لِخَيْرٍ ‏ ‏إِنَّ فُلَانًا لِرَجُلٍ مِنْهُمْ مَاتَ إِنَّهُ مَأْسُورٌ بِدَيْنِهِ قَالَ قَالَ لَقَدْ رَأَيْتُ أَهْلَهُ وَمَنْ يَتَحَزَّنُ لَهُ قَضَوْا عَنْه حَتَّى مَا جَاءَ أَحَدٌ يَطْلُبُهُ بِشَيْءٍ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَن ‏ ‏فِرَاسٍ ‏ ‏عَن ‏ ‏الشَّعْبِيِّ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو سُفْيَانَ الْمَعْمَرِيُّ ‏ ‏عَن ‏ ‏سُفْيَانَ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَن ‏ ‏الشَّعْبِيِّ ‏ ‏عَن ‏ ‏سَمْعَانَ بْنِ مُشَنَّجٍ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَن ‏ ‏سَعِيدِ بْنِ مَسْرُوقٍ ‏ ‏عَن ‏ ‏الشَّعْبِيِّ ‏ ‏فَذَكَرَ هَذَا الْحَدِيثَ ‏ ‏فَحَدَّثْتُ بِهِ أَبِي فَقَالَ لَمْ أَسْمَعْهُ مِنْ ‏ ‏وَكِيعٍ ‏","","",""],[19366,19366,"","আমি বলেছিলাম, আমার বাবার সাথে আমার ঝগড়া শুরু করে কিভাবে আমার বাবার সাথে যুদ্ধ শুরু করলাম। আমার বাবা, একবার সে তার প্রভুকে পাঠিয়েছিলো এবং তার সাথে লড়াই করতে বলেছিল, আমি আপনাকে বলছি, সে আমার বাবার সাথে লড়াই করতে এসেছে। আপনার সবচেয়ে ভালো দাস হতে হবে, হামাদ আমার বাবার সাথে কথা বলার চেষ্টা করছে... ...সে একবার বলেছিল... ...আর সে আমাকে তার বদলে আমার কথা বলেছে.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّزَّاقِ ‏ ‏حَدَّثَنَا ‏ ‏مَعْمَرٌ ‏ ‏عَن ‏ ‏أَيُّوبَ ‏ ‏وَرَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَن ‏ ‏أَيُّوبَ ‏ ‏عَن ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَن ‏ ‏أَبِي الْمُهَلَّبِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَيْكُمْ بِهَذَا الْبَيَاضِ فَيَلْبَسُهُ أَخْيَارُكُمْ ‏ ‏وَقَالَ ‏ ‏رَوْحٌ ‏ ‏فَلْيَلْبَسْهُ أَحْيَاؤُكُمْ ‏ ‏وَكَفِّنُوا فِيهِ مَوْتَاكُمْ فَإِنَّهُ مِنْ خَيْرِ ثِيَابِكُمْ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَن ‏ ‏أَبِي قِلَابَةَ ‏ ‏قَالَ قَالَ ‏ ‏سَمُرَةُ ‏ ‏فَذَكَرَهُ ‏ ‏وَذَكَرَ ‏ ‏يَعْنِي ‏ ‏عَفَّانَ ‏ ‏عَن ‏ ‏وُهَيْبٍ ‏ ‏أَيْضًا لَيْسَ فِيهِ ‏ ‏أَبُو الْمُهَلَّبِ ‏","","",""],[19367,19367,"","আমরা আগেও বলেছি, ঈশ্বরের ইচ্ছার শেষ হওয়ার আগে আমরা ভালোর জন্য সুখী হয়েছি।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدَةُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏نَهَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ بَيْعِ الْحَيَوَانِ بِالْحَيَوَانِ ‏ ‏نَسِيئَةً ‏","","",""],[19368,19368,"","আমরা একটা ভালো খারাপ সাথে কথা বলেছি... ...যা বাবার পাপের শাস্তি... ...ভালো শাসনের জন্য, ঈশ্বরের কাছে বলতে হবে যে আমি কার সাহায্য করছি, আমি ঘিরে আছি।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بِشْرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ أَبِي عَرُوبَةَ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ أَحَاطَ حَائِطًا عَلَى أَرْضٍ فَهِيَ لَهُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَهَّابِ ‏ ‏عَن ‏ ‏سَعِيدٍ ‏ ‏مِثْلَهُ إِلَّا أَنَّهُ قَالَ مَنْ أَحَاطَ ‏","","",""],[19369,19369,"","আমরা একে অপরের সাথে কথা বলেছি, একজন সৈনিক বলল আমি ঈশ্বরের সাথে লড়াই করতে চাই, তুমি জানো যে অফিসাররা আমার সাথে এমনটি করেছে যে আমাকে জিজ্ঞেস করবে তুমি দরজা দিয়ে যাও.","‏ ‏حَدَّثَنَا ‏ ‏زَكَرِيَّا بْنُ عَدِيٍّ ‏ ‏أَخْبَرَنَا ‏ ‏عُبَيْدُ اللَّهِ ‏ ‏عَن ‏ ‏عَبْدِ الْمَلِكِ بْنِ عُمَيْرٍ ‏ ‏عَن ‏ ‏حُصَيْنِ بْنِ قَبِيصَةَ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏سَأَلَ أَعْرَابِيٌّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ يَخْطُبُ فَقَطَعَ عَلَيْهِ خُطْبَتَهُ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏مَا تَقُولُ فِي الضِّبَابِ فَقَالَ ‏ ‏مُسِخَتْ ‏ ‏أُمَّةٌ مِنْ ‏ ‏بَنِي إِسْرَائِيلَ ‏ ‏فَاللَّهُ تَبَارَكَ وَتَعَالَى أَعْلَمُ فِي أَيِّ الدَّوَابِّ ‏ ‏مُسِخَتْ ‏","","",""],[19370,19370,"","ঈশ্বর তাকে প্রার্থনা করেছিলেন এবং তাকে কখনোই ভাল কিছু দিতে দেননি ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏هِشَامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا ‏","","",""],[19371,19371,"","আমরা বধিরদের সম্বন্ধে কথা বলতাম এবং তাদের দিকে তাকিয়ে তাকে বলতে চেষ্টা করি যে, কীভাবে ভালটা খুঁজে পেতে হয় । বাবা ঈশ্বরের সাথে বড় হয়ে উঠেছে, সে এটাকে ডাবলক্রসিং যুদ্ধ বলে। সে এটা পরিষ্কার ছিল.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الصَّمَدِ ‏ ‏وَعَفَّانُ ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏الْأَشْعَثُ بْنُ عَبْدِ الرَّحْمَنِ الْجَرْمِيُّ ‏ ‏عَن ‏ ‏أَبِيهِ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَأَيْتُ كَأَنَّ دَلْوًا دُلِّيَتْ مِنْ السَّمَاءِ فَجَاءَ ‏ ‏أَبُو بَكْرٍ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُ ‏ ‏فَأَخَذَ ‏ ‏بِعَرَاقِيبِهَا ‏ ‏فَشَرِبَ مِنْهُ شُرْبًا ضَعِيفًا ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَفِيهِ ضَعْفٌ ‏ ‏ثُمَّ جَاءَ ‏ ‏عُمَرُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَأَخَذَ ‏ ‏بِعَرَاقِيبِهَا ‏ ‏فَشَرِبَ حَتَّى ‏ ‏تَضَلَّعَ ‏ ‏ثُمَّ جَاءَ ‏ ‏عُثْمَانُ ‏ ‏رَضِيَ اللَّهُ عَنْهُ ‏ ‏فَأَخَذَ ‏ ‏بِعَرَاقِيبِهَا ‏ ‏فَشَرِبَ فَانْتَشَطَتْ مِنْهُ فَانْتَضَحَ عَلَيْهِ مِنْهَا شَيْءٌ ‏","","",""],[19372,19372,"","সেই সময়ে আমরা একটা বাপ্তিস্মের বিষয়ে কথা বলেছিলাম, যার কাপুরুষের চেয়ে আরও ভাল একটা ঘোড়া ছিল । বাবার ছেলে একজন মিথ্যাবাদী হিসেবে লিখেছে যে একবার তাদের একটা গোপন কথা বিশ্বাস করা উচিত ছিল।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَن ‏ ‏حُمَيْدٍ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَسْكُتُ سَكْتَتَيْنِ إِذَا دَخَلَ فِي الصَّلَاةِ وَإِذَا فَرَغَ مِنْ الْقِرَاءَةِ ‏ ‏فَأَنْكَرَ ذَلِكَ ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏وَكَتَبُوا إِلَى ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏فَكَتَبَ إِلَيْهِمْ أَنْ ‏ ‏صَدَقَ ‏ ‏سَمُرَةُ ‏","","",""],[19373,19373,"","আমরা একটা ছেলে হওয়া সম্পর্কে কথা বলেছি যে বিয়ে থেকে বেঁচে গেছে। সে ঈশ্বরকে বলে যে সে তোমাকে সাহায্য করতে চায়, আমি তোমার সাথে কথা বলতে চাই, আর ঈশ্বরের দয়া আছে তার উপর যারা একটা বিষ খেতে শুরু করেছে তাদের ক্ষতি হচ্ছে। তুমি বলো, দামটা বলার মত নয়, যখন আমি আরও বেশি কিছু পাবো।","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَن ‏ ‏مَنْصُورٍ ‏ ‏عَن ‏ ‏هِلَالِ بْنِ يَسَافٍ ‏ ‏عَن ‏ ‏رَبِيعِ بْنِ عُمَيْلَةَ الْفَزَارِيِّ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَحَبُّ الْكَلَامِ إِلَى اللَّهِ تَبَارَكَ وَتَعَالَى أَرْبَعٌ لَا إِلَهَ إِلَّا اللَّهُ وَسُبْحَانَ اللَّهِ وَالْحَمْدُ لِلَّهِ وَاللَّهُ أَكْبَرُ لَا يَضُرُّكَ بِأَيِّهِنَّ بَدَأْتَ وَلَا تُسَمِّيَنَّ غُلَامَكَ يَسَارًا وَلَا رَبَاحًا وَلَا نَجِيحًا وَلَا أَفْلَحَ فَإِنَّكَ تَقُولُ أَثَمَّ هُوَ فَلَا يَكُونُ فَيَقُولُ لَا إِنَّمَا هُنَّ أَرْبَعٌ فَلَا تَزِيدُنَّ عَلَيَّ ‏","","",""],[19374,19374,"","এমনকি পড়ে এবং নিরবতা সত্ত্বেও হতাশা ও হতাশার আনন্দ সম্বন্ধে পড়তে শুরু করে । তারা আমার বাবাকে সেই শহরে চিঠি লিখেছিল, যেখানে তিনি বলেছিলেন যে তিনি একবার গোপনভাবে বিশ্বাস করতেন ।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏قَالَ قَالَ ‏ ‏سَمُرَةُ ‏ ‏حَفِظْتُ ‏ ‏سَكْتَتَيْنِ فِي الصَّلَاةِ سَكْتَةٌ إِذَا كَبَّرَ الْإِمَامُ حَتَّى يَقْرَأَ وَسَكْتَةٌ إِذَا فَرَغَ مِنْ قِرَاءَةِ ‏ ‏فَاتِحَةِ الْكِتَابِ ‏ ‏وَسُورَةٍ عِنْدَ الرُّكُوعِ ‏ ‏قَالَ ‏ ‏فَأَنْكَرَ ذَلِكَ عَلَيْهِ ‏ ‏عِمْرَانُ بْنُ حُصَيْنٍ ‏ ‏فَكَتَبُوا إِلَى ‏ ‏أُبَيٍّ ‏ ‏فِي ذَلِكَ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏قَالَ ‏ ‏فَصَدَقَ ‏ ‏سَمُرَةُ ‏","","",""],[19375,19375,"","আমরা একটি ভাল বয়স সম্পর্কে কথা বলেছি যখন আমরা ভালো ছিলাম. সে বলবে সে ঈশ্বরের আশীর্বাদ নিয়ে বলবে তুমি তার হাতে ফিরে আসবে আর তারপর সে এটা করবে. তোমার হৃদয়ের ভেতর খুন করে খেয়ে ফেলবে... ...আর আমরা যুদ্ধ করেছি যেটা আমাদের ধোঁকা দিবে. সে বলল সে তাকে জানে আর সে ঈশ্বরের দোহাই দেয়.","‏ ‏حَدَّثَنَا ‏ ‏أَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَن ‏ ‏يُونُسَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُوشِكُ أَنْ يَمْلَأَ اللَّهُ تَبَارَكَ وَتَعَالَى أَيْدِيَكُمْ مِنْ ‏ ‏الْأَعَاجِمِ ‏ ‏ثُمَّ يَجْعَلُهُمْ اللَّهُ أُسْدًا لَا يَفِرُّونَ فَيَقْتُلُونَ مُقَاتِلَتَكُمْ وَيَأْكُلُونَ ‏ ‏فَيْئَكُمْ ‏ ‏حَدَّثَنَا ‏ ‏مُؤَمَّلٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُوشِكُ أَنْ يَمْلَأَ اللَّهُ أَيْدِيَكُمْ ‏ ‏فَذَكَرَ مِثْلَهُ ‏","","",""],[19376,19376,"","আমরা একটা স্বপ্নের বাপ্তিস্মের কথা বলেছিলাম... ...আমি কাপুরুষের ভালো নাম সম্পর্কে আমাদের বলেছিলাম, ঈশ্বর আপনাকে বলতেই হবে যে আপনি আপনার আশীর্বাদ পূরণ করতে যাচ্ছেন এবং আপনার হাত সরিয়ে নিতে হবে. ঈশ্বরের কাছে করা ভবিষ্যদ্বাণীর বিষয়ে একবার চিন্তা করার পর । তার আদর্শকে রক্ষা করুন","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏تُوشِكُونَ أَنْ يَمْلَأَ اللَّهُ تَبَارَكَ وَتَعَالَى أَيْدِيَكُمْ مِنْ ‏ ‏الْعَجَمِ ‏ ‏ثُمَّ ‏ ‏يَكُونُوا ‏ ‏أُسْدًا لَا يَفِرُّونَ فَيَقْتُلُونَ مُقَاتِلَتَكُمْ وَيَأْكُلُونَ ‏ ‏فَيْئَكُمْ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏يُونُسُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَذَكَرَ مِثْلَهُ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنَاه ‏ ‏سُرَيْجُ بْنُ النُّعْمَانِ ‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏عَن ‏ ‏يُونُسَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[19377,19377,"","আমরা কথা বলেছি... ...ঈশ্বর তাকে প্রেরণ করার পর ভালো শাসনের প্রতি আগ্রহ নিয়ে, সে প্রতিবেশীদের রক্ষা করে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏وَحُمَيْدٍ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْجَارُ أَحَقُّ بِالْجِوَارِ ‏","","",""],[19378,19378,"","তিনি বলেছিলেন যে, উত্তম উত্তম বিষয়গুলো কখনোই ভেঙে যায় না বা প্রভুর চেয়ে নিজেদেরই নিয়ে নেয় না ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا أَوْ يَأْخُذْ كُلُّ وَاحِدٍ مِنْهُمَا مَا رَضِيَ مِنْ الْبَيْعِ ‏","","",""],[19379,19379,"","আমরা আমাদের সাহায্য করেছি কাপুরুষের মত বয়স নিরাপদ করতে সাহায্য করার জন্য, ঈশ্বরের সব ক্ষতি হয়েছে আর কখনো চিন্তাও করিনি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏قَالَا ثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا ‏","","",""],[19380,19380,"","আমরা বলেছিলাম যে ছেলেটিকে উদ্ধার করার চেয়ে ভাল কিছু বেছে নিতে হবে আর সেটা আত্মসমর্পণ করতে হবে ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْعُمْرَى ‏ ‏جَائِزَةٌ ‏","","",""],[19381,19381,"","আমরা বলেছিলাম যে, ছেলেটি যখন সেটা ফিরিয়ে দিয়েছিল তখন তিনি আরও ভাল কিছু করার চেষ্টা করেছিলেন এবং তা করেছিলেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏صَلَاةُ الْوُسْطَى صَلَاةُ الْعَصْرِ ‏","","",""],[19382,19382,"","আমরা যখন লর্ডের দয়ায় ছিলাম, তখন আমরা কথা বলেছিলাম, সে বলছিল সব জিম্মিকে তার সময় ভেঙে ফেলা হয়েছে আর মারা গেছে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏كُلُّ غُلَامٍ ‏ ‏رَهِينَةٌ ‏ ‏لِعَقِيقَتِهِ ‏ ‏تُذْبَحُ يَوْمَ سَابِعِهِ وَيُحْلَقُ ‏ ‏وَيُدَمَّى ‏","","",""],[19383,19383,"","আমরা কথা বলেছি, কিভাবে আমরা তাকে তাকে এটা খুঁজে বের করতে এবং খুঁজে বের করতে বলা হয়েছে। আগামীকাল তাকে বলা হয় আমাদেরকে মেরে ফেলার চেষ্টা করতে, সে তার প্রার্থনার উত্তর দেয় এবং সে তার প্রার্থনার উত্তর দেয়। আদর্শ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏أَخْبَرَنَا ‏ ‏بِشْرُ بْنُ حَرْبٍ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏أَحْسَبُهُ ‏ ‏مَرْفُوعًا ‏ ‏مَنْ نَسِيَ صَلَاةً فَلْيُصَلِّهَا حِينَ يَذْكُرُهَا وَمِنْ الْغَدِ لِلْوَقْتِ ‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏وَسُرَيْجٌ ‏ ‏قَالَا ثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَن ‏ ‏بِشْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَمُرَةَ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[19384,19384,"","আমরা কথা বলেছিলাম, বাবার চেয়ে বরং তার বাবার চেয়ে ভাল কথা বলেছিলাম আর তিনি তা করবেন বলে আমরা বিস্মিত হয়েছিলাম ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ تَوَضَّأَ يَوْمَ الْجُمُعَةِ فَبِهَا ‏ ‏وَنِعْمَتْ وَمَنْ اغْتَسَلَ فَذَلِك أَفْضَلُ ‏","","",""],[19385,19385,"","আমরা মৃত্যুকে না ভেবে বরং বরং মৃত্যুর ইতিহাস থাকার বিষয়ে কথা বলেছিলাম । আগের চেয়ে ভাল হবে.","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏أَنَّ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏كَانَ يَوْمًا مَطِيرًا فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مُنَادِيَهُ أَنَّ ‏ ‏الصَّلَاةَ فِي ‏ ‏الرِّحَالِ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏مِثْلَهُ سَوَاءً ‏","","",""],[19386,19386,"","আমরা একবার ভুলে যাওয়ার পর বলেছিলাম যে ঈশ্বর এসে গেছেন ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نَزَلَ الْقُرْآنُ عَلَى ثَلَاثَةِ ‏ ‏أَحْرُفٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً أُنْزِلَ الْقُرْآنُ ‏","","",""],[19387,19387,"","তিনি বলেছিলেন যে, সেই ব্যক্তি যদি শিশুটা কিনে নিয়ে থাকেন, তা হলে আমি প্রথমে সেই মহিলাকে বিয়ে করব কি না ।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا تَزَوَّجَ الرَّجُلَانِ الْمَرْأَةَ فَالْأَوَّلُ أَحَقُّ وَإِذَا اشْتَرَى الرَّجُلَانِ الْبَيْعَ فَالْأَوَّلُ أَحَقُّ ‏","","",""],[19388,19388,"","আমরা একবার ভুলে যাওয়ার কথা বলেছিলাম যে খোদা এসে গেছে, সে আমাদের প্রায় বিক্রি করে দেবে, ভুলে যাবে।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ بَيْعِ الْحَيَوَانِ بِالْحَيَوَانِ ‏ ‏نَسِيئَةً ‏","","",""],[19389,19389,"","আমরা আমাদের বলতে চাই কিভাবে আপনি একটি আংটি শুনেছেন যে, একটি ভাল্লুক তার কাছে প্রার্থনা করে... ...আর প্রভু তার কাছে প্রার্থনা করে... যে কেউ এক অথবা অন-লাইন এক হওয়া আবশ্যক আর যারা তাকে মৃত বা অন্ধকারে খুঁজে পাওয়া যাবে তাদের কেউ যেন না যায়, আমাকে জিজ্ঞেস করবে আমি নাগরিক কিনা।","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏عَبْدُ الْمَلِكِ بْنُ عُمَيْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏زَيْدَ بْنَ عُقْبَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏سَمُرَةَ بْنَ جُنْدُبٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏الْمَسَائِلُ ‏ ‏كُدُوحٌ ‏ ‏يَكْدَحُ ‏ ‏بِهَا الرَّجُلُ وَجْهَهُ فَمَنْ شَاءَ أَبْقَى عَلَى وَجْهِهِ وَمَنْ شَاءَ تَرَكَ إِلَّا أَنْ يَسْأَلَ الرَّجُلُ ذَا سُلْطَانٍ أَوْ يَسْأَلَ فِي الْأَمْرِ لَا يَجِدُ مِنْهُ بُدًّا ‏ ‏قَالَ ‏ ‏فَحَدَّثْتُ ‏ ‏بِهِ ‏ ‏الْحَجَّاجَ ‏ ‏فَقَالَ ‏ ‏سَلْنِي فَإِنِّي ذُو سُلْطَانٍ ‏","","",""],[19390,19390,"","আমরা একটা দৃশ্যের কথা বলেছি এবং কাপুরুষের বাচ্চাের প্রতি বাধ্য হয়ে... ...তুমি খুশি হবে যদি তুমি বলো \"আর তুমি পথ না করো\" একবার যখন আমরা বের হই, তখন সে তার ব্রেসলেট থেকে বের হয় ।","‏ ‏حَدَّثَنَا ‏ ‏هُشَيْمٌ ‏ ‏أَخْبَرَنَا ‏ ‏مَنْصُورٌ ‏ ‏وَيُونُسُ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏أَنَّهُ ‏ ‏كَانَ إِذَا صَلَّى بِهِمْ ‏ ‏سَكَتَ سَكْتَتَيْنِ إِذَا افْتَتَحَ الصَّلَاةَ وَإِذَا قَالَ ‏ { ‏وَلَا الضَّالِّينَ ‏} ‏سَكَتَ أَيْضًا ‏ ‏هُنَيَّةً ‏ ‏فَأَنْكَرُوا ذَلِكَ عَلَيْهِ فَكَتَبَ إِلَى ‏ ‏أُبَيِّ بْنِ كَعْبٍ ‏ ‏فَكَتَبَ إِلَيْهِمْ ‏ ‏أُبَيٌّ ‏ ‏أَنَّ ‏ ‏الْأَمْرَ كَمَا صَنَعَ ‏ ‏سَمُرَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ زُرَيْعٍ ‏ ‏عَن ‏ ‏يُونُسَ ‏ ‏قَالَ ‏ ‏وَإِذَا فَرَغَ مِنْ قِرَاءَةِ السُّورَةِ ‏","","",""],[19391,19391,"","আমরা মাদির সবচেয়ে ভালটা নিয়ে কথা বলেছিলাম, যিনি আমার বাবার কাছে জীবনের সবচেয়ে খারাপ বিষয় নিয়ে এসেছিল । ( যাত্রা.","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏سَلَّامُ بْنُ أَبِي مُطِيعٍ ‏ ‏عَن ‏ ‏الْأَسْوَدِ بْنِ قَيْسٍ ‏ ‏عَن ‏ ‏ثَعْلَبَةَ بْنِ عَبَّادٍ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏صَلَّى بِنَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي كُسُوفِ الشَّمْسِ رَكْعَتَيْنِ لَا نَسْمَعُ لَهُ فِيهِمَا صَوْتًا ‏","","",""],[19392,19392,"","আমরা মৃত্যুর প্রতি শ্রদ্ধার সাথে কথা বলেছি এবং প্রশংসা করেছি... ...আমরা কাপুরুষ হওয়ার যোগ্য হওয়ার জন্য... ...সুবিধে দিয়েছি। ভাল কখনো ভাবি নি।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏وَمُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَن ‏ ‏قَتَادَةَ ‏ ‏عَن ‏ ‏الْحَسَنِ ‏ ‏عَن ‏ ‏سَمُرَةَ بْنِ جُنْدُبٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْبَيِّعَانِ ‏ ‏بِالْخِيَارِ ‏ ‏مَا لَمْ يَتَفَرَّقَا ‏","","",""],[19393,19393,"","আমরা এমন এক ছেলের কথা বলেছি যে আমাদের ভালোবাসার সময় এসে হাজির হয়েছে। আমি তাকে খুঁজে পেয়েছি যে কুকুরের মুখ থেকে আমি শ্বাস নিতে পেরে আমি খুশি। তার জন্য প্রার্থনা করে আমি আমার মৃত্যুর জন্য পাপ করেছি. ( ১ করি.","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عُبَيْدَةَ عَبْدُ الْوَاحِدِ بْنُ وَاصِلٍ ‏ ‏حَدَّثَنَا ‏ ‏سَلْمٌ يَعْنِي ابْنَ زَرِيرٍ ‏ ‏وَأَبُو الْأَشْهَبِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ طَرَفَةَ ‏ ‏أَنَّ جَدَّهُ ‏ ‏عَرْفَجَةَ بْنَ أَسْعَدَ ‏ ‏أُصِيبَ أَنْفُهُ فِي الْجَاهِلِيَّةِ يَوْمَ ‏ ‏الْكُلَابِ ‏ ‏فَاتَّخَذَ أَنْفًا مِنْ وَرِقٍ فَأَنْتَنَ عَلَيْهِ ‏ ‏فَأَمَرَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَتَّخِذَ أَنْفًا ‏ ‏يَعْنِي مِنْ ذَهَبٍ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ مَهْدِيٍّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ طَرَفَةَ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَرْفَجَةَ بْنِ أَسْعَدَ ‏ ‏أَنَّهُ أُصِيبَ أَنْفُهُ يَوْمَ ‏ ‏الْكُلَابِ ‏ ‏فِي الْجَاهِلِيَّةِ فَذَكَرَ الْحَدِيثَ ‏ ‏مِثْلَهُ ‏","","",""],[19394,19394,"","ঈশ্বর আমাদের খুঁজে বের করার চেষ্টা করার সময় আমাদের খুঁজে বের করেছেন। আমাকে ছেড়ে দাও, শত্রু আমাকে অনেক বেশি বলছে আমি ঝড়াপন্ন হয়ে দুঃখিত হতে পারবো না, একটি ছেলের বিয়ে আমি ঈশ্বরের ভালোবাসার সম্মুখীন। আমি তার দাদাকে দেখেছি যে আমরা প্রেম করেছি এটা জেনে যে, একটা ছেলে জেনে আমি খুশি যে তার অপ্রিয়তার সৌন্দর্য নিয়ে তাকে যেতে আমি খুশি। আমরা বলেছিলাম, আমরা তার দাদাকে এই প্রেম করতে পারি। আমার বাবা ঈশ্বরকে খুঁজে পাওয়ার চেষ্টা করতেন । আমার সিংহাসনের উপর এক উজ্জ্বল আবরণ রয়েছে ।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ الْعُطَارِدِيُّ جَعْفَرُ بْنُ حَيَّانَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ طَرَفَةَ بْنِ عَرْفَجَةَ ‏ ‏قَالَ ‏ ‏وَزَعَمَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏أَنَّهُ رَأَى ‏ ‏عَرْفَجَةَ ‏ ‏قَالَ ‏ ‏أُصِيبَ أَنْفُ ‏ ‏عَرْفَجَةَ ‏ ‏يَوْمَ ‏ ‏الْكُلَابِ ‏ ‏فَاتَّخَذَ أَنْفًا مِنْ وَرِقٍ فَأَنْتَنَ عَلَيْهِ ‏ ‏فَأَمَرَهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَتَّخِذَ أَنْفًا مِنْ ذَهَبٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ الْعَدَوِيُّ حَوْثَرَةُ بْنُ أَشْرَسَ ‏ ‏أَخْبَرَنِي ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ طَرَفَةَ بْنِ عَرْفَجَةَ بْنِ أَسْعَدَ ‏ ‏أَنَّ ‏ ‏جَدَّهُ ‏ ‏عَرْفَجَةَ بْنَ أَسْعَدَ ‏ ‏أُصِيبَ أَنْفُهُ فِي الْجَاهِلِيَّةِ يَوْمَ ‏ ‏الْكُلَابِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏قَالَ ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏وَزَعَمَ ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏أَنَّهُ قَدْ رَأَى جَدَّهُ ‏ ‏يَعْنِي ‏ ‏عَرْفَجَةَ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ تَمِيمٍ النَّهْشَلِيُّ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ طَرَفَةَ بْنِ عَرْفَجَةَ بْنِ أَسْعَدَ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏عَرْفَجَةَ بْنِ أَسْعَدَ ‏ ‏أَنَّ أَنْفَهُ أُصِيبَ يَوْمَ ‏ ‏الْكُلَابِ ‏ ‏فِي الْجَاهِلِيَّةِ فَذَكَرَ ‏ ‏مِثْلَهُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ الْمُبَارَكِ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ حَيَّانَ ‏ ‏حَدَّثَنِي ‏ ‏عَبْدُ الرَّحْمَنِ بْنُ طَرَفَةَ بْنِ عَرْفَجَةَ ‏ ‏أَنَّ ‏ ‏جَدَّهُ ‏ ‏عَرْفَجَةَ ‏ ‏أُصِيبَ أَنْفُهُ يَوْمَ الْكِلَابِ ‏ ‏فَذَكَرَ الْحَدِيثَ ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ عُثْمَانَ يَعْنِي الْجَرْمِىَّ السِّمْسَارَ ‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ بْنُ عَيَّاشٍ ‏ ‏عَنْ ‏ ‏جَعْفَرِ بْنِ حَيَّانَ الْعُطَارِدِيِّ ‏ ‏عَنْ ‏ ‏عَبْدِ الرَّحْمَنِ بْنِ طَرَفَةَ بْنِ عَرْفَجَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏قَالَ أُصِيبَ أَنْفُهُ يَوْمَ ‏ ‏الْكُلَابِ ‏ ‏يَعْنِي مَاءً اقْتَتَلُوا عَلَيْهِ فِي الْجَاهِلِيَّةِ ‏ ‏فَذَكَرَ مِثْلَهُ قَالَ فَمَا أَنْتَنَ عَلَيَّ ‏","","",""],[19395,19395,"","আমরা ঈশ্বরের সাথে কথা বলেছি, বাবার সাথে কথা বলেছিলাম আমার কথা। আমার বাবা আমাকে থামাতে চেষ্টা করছিল। হিংসার কারণে তোমার মত হয়ে যাবে। আমি দুঃখিত, সে কুকুরদের ঘুমাচ্ছিল।","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏شَيْبَانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو الْأَشْهَبِ ‏ ‏عَنْ ‏ ‏حَمَّادِ بْنِ أَبِي سُلَيْمَانَ الْكُوفِيِّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏الْمُغِيرَةَ بْنَ عَبْدِ اللَّهِ ‏ ‏قَدْ ‏ ‏شَدَّ أَسْنَانَهُ بِالذَّهَبِ فَذُكِرَ مِثْلَ ذَلِكَ ‏ ‏لِإِبْرَاهِيمَ ‏ ‏فَقَالَ لَا بَأْسَ بِهِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏أَبُو عَبْد الرَّحْمَنِ ‏ ‏قَالَ ‏ ‏سَمِعْت ‏ ‏أَبِي ‏ ‏يَقُولُ ‏ ‏جَاءَ قَوْمٌ مِنْ أَصْحَابِ الْحَدِيثِ فَاسْتَأْذَنُوا عَلَى ‏ ‏أَبِي الْأَشْهَبِ ‏ ‏فَأَذِنَ لَهُمْ ‏ ‏فَقَالُوا حَدِّثْنَا قَالَ ‏ ‏سَلُوا فَقَالُوا مَا مَعَنَا شَيْءٌ نَسْأَلُكَ عَنْهُ فَقَالَتْ ابْنَتُهُ مِنْ وَرَاءِ السِّتْرِ سَلُوهُ عَنْ حَدِيثِ ‏ ‏عَرْفَجَةَ بْنِ أَسْعَدَ ‏ ‏أُصِيبَ أَنْفُهُ يَوْمَ ‏ ‏الْكُلَابِ ‏","","",""],[19396,19396,"","আমরা আমাদের আবেগ দ্বারা বাপ্তাইজিত হয়েছি... ...একটা লড়াই চালিয়ে যাওয়ার রীতি নিয়ে... ...আমি আল্লাহ্‌কে জেনে রাখার জন্য শুনেছি আর বলবো এটা এমন ভয়ানক ব্যাপার যা আমি চাই বিরতি, কে ছিলো।","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏زِيَادِ بْنِ عِلَاقَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَرْفَجَةَ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏إِنَّهُ سَتَكُونُ ‏ ‏هَنَاتٌ ‏ ‏وَهَنَاتٌ ‏ ‏فَمَنْ أَرَادَ أَنْ يُفَرِّقَ أَمْرَ هَذِهِ الْأُمَّةَ وَهُمْ جَمِيعٌ فَاضْرِبُوهُ بِالسَّيْفِ كَائِنًا مَنْ كَانَ ‏","","",""],[19397,19397,"","আমরা আমাদের সব থেকে ভালো কথা বলেছি, কিন্তু আমি সবচেয়ে ভালো কথা বলব যে আমি বিয়ে করব এমন একজন মানুষ হয়ে যাবে যে হবে সে হবে ঈশ্বর তার জন্য প্রার্থনা করেছেন আর তিনি আমার কাছে তার আত্মধার্মিকতা তুলে দেবেন। তিনি বললেন শান্তি ভাই তাকে যেতে দিবে না।","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الرَّحْمَنِ ‏ ‏حَدَّثَنَا ‏ ‏عَبَّادُ بْنُ رَاشِدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏الْحَسَنَ ‏ ‏يَقُولُ حَدَّثَنِي ‏ ‏رَجُلٌ ‏ ‏مِنْ ‏ ‏بَنِي سَلِيطٍ ‏ ‏أَنَّهُ مَرَّ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ جَالِسٌ عَلَى بَابِ الْمَسْجِدِ وَعَلَيْهِ ثَوْبٌ ‏ ‏قِطْرِيٌّ ‏ ‏لَيْسَ عَلَيْهِ غَيْرُهُ ‏ ‏مُحْتَبٍ ‏ ‏بِهِ وَهُوَ يَقُولُ ‏ ‏الْمُسْلِمُ أَخُو الْمُسْلِمِ لَا يَظْلِمُهُ وَلَا يَخْذُلُهُ التَّقْوَى هَاهُنَا وَيُشِيرُ بِيَدِهِ إِلَى صَدْرِهِ ‏","","",""],[19398,19398,"","তিনি ঈশ্বরের কাছে প্রার্থনা করেছিলেন এবং ঈশ্বর ও আমি যে আপনাকে আশীর্বাদ করেছিলেন, তা গ্রহণ করেছিলেন কিন্তু তিনি আমাকে ও আমার সঙ্গে কথা বলেছিলেন । তার নিজের সর্বোচ্চ চেষ্টা করতে হতো।","‏ ‏حَدَّثَنَا ‏ ‏إِسْمَاعِيلُ ‏ ‏عَنْ ‏ ‏يُونُسَ ‏ ‏حَدَّثَنِي ‏ ‏أَبُو الْعَلَاءِ بْنُ الشِّخِّيرِ ‏ ‏حَدَّثَنِي ‏ ‏أَحَدُ ‏ ‏بَنِي سُلَيْمٍ ‏ ‏وَلَا أَحْسَبُهُ إِلَّا قَدْ ‏ ‏رَأَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّ اللَّهَ تَبَارَكَ وَتَعَالَى ‏ ‏يَبْتَلِي عَبْدَهُ بِمَا أَعْطَاهُ فَمَنْ رَضِيَ بِمَا قَسَمَ اللَّهُ عَزَّ وَجَلَّ لَهُ بَارَكَ اللَّهُ لَهُ فِيهِ وَوَسَّعَهُ وَمَنْ لَمْ يَرْضَ لَمْ يُبَارِكْ لَهُ ‏","","",""],[19399,19399,"","আমি ঈশ্বরের কাছে শপথ করে বলছি যে, আমার লোকেরা আমার প্রতি বিরক্ত হচ্ছে । আমাদের কাছে একবারের মতো এমন হয়েছিল, সে একটা উপহার আর আমার বাবার ছেলে, রাজা আর মন দেখেছে, কিন্তু সে তার নিজের একটাকে ছুঁড়ে ফেলে দিয়েছে, যে কোন বছরেই তুমি শুনেছ। কাজের মাধ্যমে এক বছর... ...আর আনন্দের বছর পার করে.","‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ عَمْرٍو الضَّبِّيُّ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ هَاشِمٍ يَعْنِي ابْنَ الْبَرِيدِ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ الْحَلَبِيِّ ‏ ‏عَنْ ‏ ‏أَبِي مَلِيحِ بْنِ أُسَامَةَ ‏ ‏عَنْ ‏ ‏أَبِيهِ ‏ ‏قَالَ ‏ ‏أَصَابَ النَّاسَ فِي يَوْمِ جُمُعَةٍ ‏ ‏يَعْنِي مَطَرًا ‏ ‏فَأَمَرَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنُودِيَ أَنَّ ‏ ‏الصَّلَاةَ الْيَوْمَ ‏ ‏أَوْ الْجُمُعَةَ الْيَوْمَ ‏ ‏فِي ‏ ‏الرِّحَالِ ‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏نَافِعُ بْنُ عُمَرَ بْنِ جَمِيلٍ الْجُمَحِيُّ ‏ ‏قَالَ ‏ ‏رَأَيْتُ ‏ ‏عَطَاءً ‏ ‏وَابْنَ أَبِي مُلَيْكَةَ ‏ ‏وَعِكْرِمَةَ بْنَ خَالِدٍ ‏ ‏يَرْمُونَ الْجَمْرَةَ قَبْلَ الْفَجْرِ يَوْمَ النَّحْرِ فَقَالَ لَهُ أَبِي يَا ‏ ‏أَبَا سُلَيْمَانَ ‏ ‏فِي أَيِّ سَنَةٍ سَمِعْتَ مِنْ ‏ ‏نَافِعِ بْنِ عُمَرَ ‏ ‏قَالَ سَنَةَ تِسْعٍ وَسِتِّينَ وَمِائَةٍ سَنَةَ وَقْعَةِ ‏ ‏الْحُسَيْنِ ‏","","",""],[19400,19400,"","আমরা কথা বলেছিলাম, যখন সে তার এলাকায় ছিল তখন আমার বাবা কিভাবে কথা বলেছিলেন। তুমি আশা করতে যে তুমি মনে করতে পারবে তুমি এটা চেয়ে বেশি কিছু দিতে চাও নি।","‏ ‏حَدَّثَنَا ‏ ‏دَاوُدُ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏نَافِعُ بْنُ عُمَرَ الْجُمَحِيُّ ‏ ‏عَنِ ‏ ‏الْقَاسِمِ بْنِ أَبِي بَزَّةَ ‏ ‏فِي قَوْلِهِ تَبَارَكَ وَتَعَالَى ‏ { ‏وَلَا تَمْنُنْ تَسْتَكْثِرُ ‏} ‏قَالَ ‏ ‏لَا ‏ ‏تُعْطِي شَيْئًا تَطْلُبُ أَكْثَرَ مِنْهُ ‏","","",""]];
